    textfix["一种能增添节日气氛的特殊燃料。"] = "Một loại nhiên liệu đặc biệt có thể thêm không khí lễ hội."
    textfix["一簇草，可以收割。"] = "Một cụm cỏ, có thể thu hoạch."
    textfix["一道不稳定的天体裂隙，能量在其中涌动。"] = "Một thiên thể liệt khích không ổn định, năng lượng trong đó cuộn sóng."
    textfix["一铃一契，方是正理。"] = "Một chuông một khế, mới là đạo lý đúng đắn."
    textfix["一锅烹饪失败、糊状的食物。"] = "Một nồi thức ăn nấu thất bại, dạng hồ."
    textfix["一阶妖鱼，也敢在我面前游弋？"] = "Yêu ngư nhất giai, cũng dám bơi lượn trước mặt ta?"
    textfix["一顶舒适的睡帽，有助于安眠。"] = "Mũ ngủ thoải mái, có ích cho giấc ngủ."
    textfix["一颗乳牙，应是某个孩子换牙期脱落的。"] = "Một chiếc răng sữa, hẳn là rụng trong thời kỳ thay răng của đứa trẻ nào đó."
    textfix["一颗流光溢彩的琉璃珠，似是孩童遗失的玩物。"] = "Một viên thủy tinh rực rỡ, dường như là đồ chơi trẻ em bị thất lạc."
    textfix["一首级竟能存世，其上怨念与魔力交织。"] = "Một đầu người thực sự có thể tồn tại trên đời, oán niệm và ma lực trên đó đan xen."
    textfix["七彩流光，内含乾坤...此物绝非寻常！"] = "Bảy màu lưu quang, bên trong chứa kiền khôn... vật này tuyệt không tầm thường!"
    textfix["七彩灵丹，虽为糖衣所裹，却蕴含精纯元气，可瞬复法力。"] = "Thất Thái Linh Đan, tuy được bọc bởi đường, nhưng hàm chứa nguyên khí thuần tịnh, có thể tức thì phục hồi pháp lực."
    textfix["万物终将归于尘土。"] = "Vạn vật cuối cùng cũng về với bụi đất."
    textfix["三叉戟？似是水系法宝。"] = "Đinh ba? Dường như là pháp bảo thủy hệ."
    textfix["三息之内，取你性命。"] = "Trong ba nhịp thở, lấy mạng ngươi."
    textfix["三昧真火面前，此等控火术如同儿戏。"] = "Trước Tam Muội Chân Hỏa, thuật khống chế lửa như vậy chỉ là trò trẻ con."
    textfix["上古修士遗物，岁月流逝，灵韵几近消散。"] = "Di vật của tu sĩ thượng cổ, năm tháng trôi qua, linh vận gần như tiêu tán."
    textfix["上古宝箱？如何开启。"] = "Rương kho thượng cổ? Làm sao mở."
    textfix["上古文字，难以解读。"] = "Văn tự thượng cổ, khó giải đọc."
    textfix["上古符文，晦涩难懂。"] = "Phù văn thượng cổ, tối nghĩa khó hiểu."
    textfix["上古遗珍，重见天日。"] = "Trân bảo thượng cổ, lại thấy ánh sáng."
    textfix["上古魔角！可炼破阵法宝"] = "Ma giác thượng cổ! Có thể luyện phá trận pháp bảo."
    textfix["上品灵偶，灵气充盈。"] = "Linh ngẫu thượng phẩm, linh khí đầy ắp."
    textfix["不灭金身，万劫不磨。"] = "Kim thân bất diệt, vạn kiếp không mài mòn."
    textfix["不见明月，唯有地脉阴寒。"] = "Không thấy minh nguyệt, chỉ có địa mạch âm hàn."
    textfix["不过尔尔。"] = "Chẳng qua vậy thôi."
    textfix["不过是一群前来送死的蝼蚁。"] = "Chẳng qua là một đám kiến đến chịu chết."
    textfix["不过是个荒废的洞府。"] = "Chẳng qua là một động phủ hoang phế."
    textfix["且看捞到了何物。"] = "Hãy xem vớt được vật gì."
    textfix["且看这未知之种，能结何等因果。"] = "Cứ xem giống chưa biết này, kết ra nhân quả gì."
    textfix["且观此兽有何能耐……"] = "Cứ xem con thú này có năng lực gì..."
    textfix["业火焚身，合该如此。"] = "Nghiệp hỏa thiêu thân, đáng như vậy."
    textfix["东北方，寒湿之地。"] = "Đông bắc, vùng đất hàn ẩm."
    textfix["东南方，暖湿交汇。"] = "Đông nam, ấm ẩm giao nhau."
    textfix["东方，属木，主生长。"] = "Phía đông, thuộc mộc, chủ sinh trưởng."
    textfix["中音贝壳，似含韵律。"] = "Vỏ sò âm giữa, dường như chứa vận luật."
    textfix["丰饶角雕像，象征富足。"] = "Tượng đá sừng sung túc, tượng trưng cho giàu có."
    textfix["串在棍子上的鱼头，是猪人的特色食物。"] = "Đầu cá xiên que, là đặc sản của người lợn."
    textfix["串起来的泡芙球，是节庆小吃。"] = "Bánh bông lan xâu chuỗi, là đồ ăn vặt ngày lễ."
    textfix["临死前还想带本尊去何处……"] = "Trước lúc chết còn muốn dẫn bổn tôn đi đâu..."
    textfix["丹炉空空如也。"] = "Đan lò rỗng không."
    textfix["丹药已成。"] = "Đan dược đã thành."
    textfix["为何我仍感心神不宁？"] = "Sao ta vẫn cảm thấy tâm thần bất an?"
    textfix["主教雕像，形态庄重。"] = "Tượng đá giám mục, hình thái trang trọng."
    textfix["主旋律音，气势恢宏。"] = "Âm chủ nhạc, khí thế hùng tráng."
    textfix["乌鸦主持人？节庆司仪。"] = "MC quạ? Nghi lễ lễ hội."
    textfix["乌鸦在手中挣扎，羽翼扑腾。"] = "Quạ trong tay vùng vẫy, cánh đập phần phật."
    textfix["乌鸦巢穴？喂食游戏。"] = "Tổ quạ? Trò chơi cho ăn."
    textfix["乌鸦形状的节日装饰。"] = "Đồ trang trí ngày lễ hình quạ."
    textfix["乌鸦羽毛。"] = "Lông quạ."
    textfix["乌鸦，叫声聒噪，常被视为不祥之兆。"] = "Quạ, tiếng kêu ồn ào, thường được coi là điềm bất tường."
    textfix["乙木灵苗，假以时日，可成聚灵之木。"] = "Linh miêu mộc ất, chờ thêm thời gian, có thể thành tụ linh chi mộc."
    textfix["九幽炼器炉，可铸魔兵。"] = "Lò luyện khí cửu u, có thể đúc ma binh."
    textfix["九幽玄柱，亟待处置。"] = "Huyền trụ cửu u, cần gấp xử lý."
    textfix["九幽玄柱，竟也崩塌..."] = "Huyền trụ cửu u, lại cũng sụp đổ..."
    textfix["九幽硝石，可炼阴雷。"] = "Tiêu thạch cửu u, có thể luyện âm lôi."
    textfix["九幽魔物，正好拿来祭炼法宝。"] = "Ma vật Cửu U, vừa hay dùng để tế luyện pháp bảo."
    textfix["也罢，便看看你们有何神通。"] = "Thôi được, cứ xem các ngươi có thần thông gì."
    textfix["乱石嶙峋，乃地脉不稳之象。"] = "Đá lởm chởm lồi lõm, là dấu hiệu địa mạch bất ổn."
    textfix["乱神音律，邪门歪道。"] = "Âm luật loạn thần, tà môn lệch đạo."
    textfix["乳白灵液，功效未知。"] = "Linh dịch nhũ trắng, công hiệu chưa biết."
    textfix["乾坤挪移大阵已成！"] = "Đại trận kiền khôn chuyển dời đã thành!"
    textfix["乾坤挪移，方寸之间。"] = "Kiền khôn dời chuyển, trong tấc đất."
    textfix["人偶戏服，可扮傀儡。"] = "Trang phục người ngẫu, có thể đóng giả quái lỗi."
    textfix["人偶无法装备此物。"] = "Con rối không thể trang bị vật này."
    textfix["人偶面具，诡异非常。"] = "Mặt nạ người ngẫu, quái dị phi thường."
    textfix["人妖殊途，心意难通。"] = "Người yêu khác đường, tâm ý khó thông."
    textfix["人工开凿的路径，便于行走。"] = "Con đường được đào tay, tiện đi lại."
    textfix["人已散去，来迟一步。"] = "Người đã tan đi, đến muộn một bước."
    textfix["人形生物的肉，食用它是不被允许的。"] = "Thịt sinh vật hình người, ăn nó là không được phép."
    textfix["人造晶球，光华流转，可作装饰。"] = "Tinh cầu nhân tạo, quang hoa lưu chuyển, có thể làm trang trí."
    textfix["仅余骨架，此鸟早已亡故。"] = "Chỉ còn bộ xương, con chim này đã chết từ lâu."
    textfix["今日且留你性命。"] = "Hôm nay tạm để ngươi sống."
    textfix["今日已尽兴，明日再来。"] = "Hôm nay đã vui đủ, ngày mai hãy đến."
    textfix["今日鱼口不佳，莫非时辰不对？"] = "Hôm nay cá không cắn câu, hay là thời khắc không đúng?"
    textfix["从桦栗果中诞生的树精，具有攻击性。"] = "Cây tinh được sinh ra từ quả dẻ bạch, có tính tấn công."
    textfix["仙人掌果实已被采摘，需待其重新生长。"] = "Quả xương rồng đã được hái, cần đợi mọc lại."
    textfix["仙人掌肉，需剔除尖刺方可食用。"] = "Thịt xương rồng, cần loại bỏ gai nhọn mới có thể ăn."
    textfix["仙人掌花，于恶劣环境中绽放，生命顽强。"] = "Hoa xương rồng, nở trong môi trường khắc nghiệt, sức sống mãnh liệt."
    textfix["仙人掌，耐旱多刺，果实可食，但需小心处理。"] = "Xương rồng, chịu hạn nhiều gai, quả có thể ăn, nhưng cần cẩn thận xử lý."
    textfix["仙缘法坛基座..."] = "Đế tòa pháp đàn tiên duyên..."
    textfix["以妖物之皮炼制的辟谷甲。"] = "Giáp bịt cốc được luyện bằng da yêu vật."
    textfix["以妖物甲壳制成，防护尚可。"] = "Được chế từ vỏ giáp yêu vật, phòng hộ tạm được."
    textfix["以妖禽翎羽所制宝扇，轻轻一挥，可唤来清凉罡风。"] = "Bảo phiến được chế từ lông yêu cầm, khẽ vẫy một cái, có thể gọi đến cương phong thanh mát."
    textfix["以妖蝠精魄炼制成兵，手段阴邪，然威力不俗。"] = "Luyện binh khí từ tinh phách dơi yêu, thủ đoạn âm tà, nhưng uy lực không tầm thường."
    textfix["以妖齿为器，当真粗鄙。"] = "Dùng nanh yêu làm khí, thật thô bỉ."
    textfix["以巨鹿眼球制成的伞，能有效抵御雨雪。"] = "Ô được chế từ mắt nai khổng lồ, có thể chống mưa tuyết hiệu quả."
    textfix["以心神损耗为代价换取防护，邪门。"] = "Đánh đổi tâm thần để lấy phòng hộ, môn phái tà đạo."
    textfix["以我法力，为你重聚魂魄。"] = "Dùng pháp lực của ta, giúp ngươi tụ lại hồn phách."
    textfix["以执念化形，长存于世，可叹亦可悲。"] = "Dùng chấp niệm hóa hình, trường tồn trên đời, đáng thán cũng đáng bi."
    textfix["以此架风干灵肉，可锁其精华。"] = "Dùng giá này phơi linh nhục, có thể khóa giữ tinh hoa của nó."
    textfix["以此符箓封存物品，可保灵机不泄。"] = "Dùng phù lục này phong tồn vật phẩm, có thể bảo toàn linh cơ không rò rỉ."
    textfix["以浊养清，倒是暗合阴阳之道。"] = "Dùng trọc nuôi thanh, lại ngầm hợp với âm dương chi đạo."
    textfix["以灵兽皮毛制成，可助凝神静气。"] = "Được chế từ da lông linh thú, có thể giúp tập trung thần khí."
    textfix["以灵力包裹，暂可隔绝其寒毒。"] = "Bọc bằng linh lực, tạm thời có thể cách ly hàn độc."
    textfix["以灵瓜粉所制小点，香甜可口，可稍补元气。"] = "Bánh điểm tâm được làm từ bột linh dưa, thơm ngọt ngon, có thể bổ sung chút nguyên khí."
    textfix["以灵瓜雕琢的辟邪灯，烛光可驱散低阶邪祟。"] = "Đèn trừ tà được điêu khắc từ linh dưa, ánh nến có thể xua tan tà ma cấp thấp."
    textfix["以灵蜜调和草药，略有疗伤之效。"] = "Dùng linh mật điều hòa thảo dược, có chút hiệu quả chữa thương."
    textfix["以熊妖精皮所制，御寒之效非凡。"] = "Được chế từ da tinh gấu yêu, hiệu quả chống lạnh phi thường."
    textfix["以蛛魔精魄炼制的帽子，戴上后可令群蛛误认为同类。"] = "Mũ luyện chế từ tinh phách nhện ma, đội lên thì khiến nhện bầy nhầm tưởng là đồng loại."
    textfix["以蝴蝶翅粉入食，可稍补心神。"] = "Dùng phấn cánh bướm vào thức ăn, có thể bổ sung chút tâm thần."
    textfix["以鬃毛织毯，煞气逼人，非祥瑞之物。"] = "Thảm dệt từ bờm, sát khí bức người, không phải vật cát tường."
    textfix["仿制古砖，徒具其形，神韵不足。"] = "Gạch cổ bắt chước, chỉ có hình, thần vận không đủ."
    textfix["仿古砖雕，匠气过重，失了古意。"] = "Điêu khắc gạch cổ bắt chước, thợ thủ công khí quá nặng, mất đi ý cổ."
    textfix["伏特羊被闪电充能，变得更具攻击性。"] = "Cừu Volt bị sét nạp năng, trở nên tấn công mạnh hơn."
    textfix["伏特羊角，是良好的导电材料。"] = "Sừng cừu Volt, là nguyên liệu dẫn điện tốt."
    textfix["伏特羊，一种能产生电荷的山羊。"] = "Cừu Volt, một loại dê có thể sản sinh điện tích."
    textfix["伐木狂魔...正好替王某收集炼制法宝的灵木"] = "Cuồng ma đốn củi... vừa hay thay Vương Mỗ thu thập linh mộc luyện pháp bảo."
    textfix["休眠的魔瞳...暗藏凶煞之气"] = "Ma đồng đang ngủ... ẩn chứa hung sát chi khí."
    textfix["会发声的奇异匣子，其原理难以参透。"] = "Hộp kỳ lạ biết phát âm, nguyên lý của nó khó mà thấu suốt."
    textfix["传送门能量尽失。"] = "Năng lượng cổng truyền tống tận mất."
    textfix["传送阵波动不稳，尚可一用。"] = "Sóng động trận truyền tống không ổn, vẫn có thể dùng một lần."
    textfix["伪装之术，拙劣不堪。"] = "Thuật giả trang, vụng về không chịu được."
    textfix["伪装的宝箱？其上附着迷惑心智的微弱禁制。"] = "Rương kho giả trang? Trên đó gắn có cấm chế vi nhược mê hoặc tâm trí."
    textfix["位面通道，可跨越世界。"] = "Thông đạo vị diện, có thể vượt qua thế giới."
    textfix["体修莽夫，不足为惧"] = "Thể tu cục súc, không đáng ngại."
    textfix["体修魂魄竟如此强悍...有趣"] = "Hồn phách thể tu thực sự mạnh mẽ như vậy... thú vị."
    textfix["何人敢伤月宫灵物？不知死活！"] = "Ai dám làm hại linh vật nguyệt cung? Không biết sống chết!"
    textfix["何人施法？"] = "Ai thi pháp?"
    textfix["何人毁我月宫法阵？定不轻饶！"] = "Ai hủy trận pháp nguyệt cung của ta? Chắc chắn không tha!"
    textfix["何人胆敢乱画？"] = "Ai dám vẽ bậy?"
    textfix["何人胆敢破坏王某藏品？"] = "Ai dám phá hoại đồ sưu tầm của Vương Mỗ?"
    textfix["作物已成熟。"] = "Cây trồng đã chín."
    textfix["作物已腐烂。"] = "Cây trồng đã thối rữa."
    textfix["作物正在生长。"] = "Cây trồng đang sinh trưởng."
    textfix["作物生长中。"] = "Cây trồng đang sinh trưởng."
    textfix["作物起火。"] = "Cây trồng bốc lửa."
    textfix["你的内丹，本尊收了。"] = "Nội đan của ngươi, bổn tôn thu lấy rồi."
    textfix["你的影子...已被九幽魔气侵蚀！"] = "Bóng của ngươi... đã bị ma khí Cửu U xâm thực!"
    textfix["你那姐妹亡魂...竟能助你作战？"] = "Vong hồn chị gái của ngươi... thực sự có thể giúp ngươi chiến đấu?"
    textfix["你那玩偶...莫非是件火系法宝？"] = "Búp bê của ngươi... hay chăng là pháp bảo hỏa hệ?"
    textfix["供奉不合，机缘未到。"] = "Cúng phẩm không hợp, cơ duyên chưa đến."
    textfix["依附地脉阴气而生的苔藓。"] = "Rêu mọc nương nhờ địa mạch âm khí."
    textfix["便携丹炉，可炼简单丹药。"] = "Đan lò di động, có thể luyện đan dược đơn giản."
    textfix["便携耕地机？便于携带。"] = "Máy cày di động? Tiện mang theo."
    textfix["俗物不堪入局。"] = "Vật tục không đủ tư cách vào cuộc."
    textfix["俗礼而已，不必挂心。"] = "Tục lễ mà thôi, không cần bận tâm."
    textfix["保暖冬帽，能有效防止头部热量流失。"] = "Mũ đông giữ ấm, có thể ngăn hiệu quả nhiệt lượng đầu tản đi."
    textfix["保险箱被锁住了。"] = "Két sắt bị khoá."
    textfix["信号弹，发射后能发出亮光，用于标记位置或求救。"] = "Pháo hiệu, sau khi phóng có thể phát ra ánh sáng, dùng để đánh dấu vị trí hoặc cầu cứu."
    textfix["修复完了也不过是死物。"] = "Tu phục xong cũng chỉ là vật chết."
    textfix["修复完成，正好看守山门"] = "Tu phục hoàn thành, đúng lúc canh giữ sơn môn."
    textfix["修补人偶面具，勉强可用。"] = "Mặt nạ người ngẫu tu bổ, miễn cưỡng có thể dùng."
    textfix["修补完成，给童儿当练功靶子"] = "Tu bổ hoàn thành, cho đồng nhi làm bia luyện công."
    textfix["倒是比那些蠢货让人省心。"] = "Thực ra so với những đồ ngu kia, dễ chịu hơn nhiều."
    textfix["借风雷之力，淬炼草木精华。"] = "Mượn sức phong lôi, tôi luyện tinh hoa thảo mộc."
    textfix["假凤傀儡，可娱灵猫。"] = "Quái lỗi phượng giả, có thể vui linh miêu."
    textfix["假凤机关组件，待我组装。"] = "Cấu kiện cơ quan phượng giả, chờ ta lắp ráp."
    textfix["傀儡已毁，劫数难逃。"] = "Quái lỗi đã huỷ, kiếp số khó thoát."
    textfix["傀儡已毁，灵性尽失。"] = "Bù nhìn đã hủy, linh tính mất hết."
    textfix["傀儡戏文，何人执笔？"] = "Kịch văn quái lỗi, ai cầm bút?"
    textfix["傀儡手隐于台下，伺机而动。"] = "Tay quái lỗi ẩn dưới sân khấu, chờ cơ hội mà động."
    textfix["傀儡焚毁，化为灰烬。"] = "Quái lỗi bị thiêu, hóa thành tro tàn."
    textfix["傀儡焚毁，徒留残骸。"] = "Quái lỗi bị thiêu, chỉ còn tàn tích."
    textfix["储物箱，可存放些不甚重要的杂物。"] = "Hộp lưu trữ, có thể cất giữ một số tạp vật không quan trọng lắm."
    textfix["储物袋已满，这些材料暂且由我保管。"] = "Túi đã đầy, những vật liệu này tạm thời ta giữ hộ."
    textfix["储物袋已满，需整理一番。"] = "Túi trữ vật đã đầy, cần sắp xếp lại."
    textfix["催眠吹箭，中者昏睡，可制敌而非杀敌。"] = "Tên thổi thôi miên, người trúng hôn mê, có thể chế địch mà không giết."
    textfix["元神又精进了一分。"] = "Nguyên thần lại tinh tiến thêm một phần."
    textfix["元素书，能召唤元素生物助战。"] = "Nguyên tố thư, có thể triệu hoán sinh vật nguyên tố trợ chiến."
    textfix["先来后到，此乃规矩。"] = "Đến trước đến sau, đó là quy tắc."
    textfix["光华万丈，令人顿悟。"] = "Quang hoa vạn trượng, khiến người đốn ngộ."
    textfix["光华收敛，进入蛰伏。"] = "Quang hoa thu liễm, bước vào ngủ đông."
    textfix["光华渐暗，需换新蕊。"] = "Quang hoa dần tối, cần thay nhụy mới."
    textfix["光耀护身，可破迷障。"] = "Quang huy hộ thân, có thể phá mê chướng."
    textfix["克劳斯的礼物袋，击败他后才能打开。"] = "Túi quà của Klaus, chỉ có thể mở sau khi đánh bại hắn."
    textfix["克劳斯雕像，刻画了某种被封印的魔物。"] = "Tượng đá Klaus, khắc họa một loại ma vật bị phong ấn."
    textfix["克劳斯，一只强大的冬季boss，携带着礼物袋。"] = "Klaus, một boss mùa đông mạnh mẽ, mang theo túi quà."
    textfix["兔人祭坛，与它们的节庆活动有关。"] = "Tế đàn người thỏ, liên quan đến hoạt động lễ hội của chúng."
    textfix["兔人雕像，石材似乎不够坚固。"] = "Tượng đá người thỏ, đá có vẻ không đủ vững chắc."
    textfix["兔妖尾毛，柔软异常，可作符笔。"] = "Lông đuôi thỏ yêu, mềm mại khác thường, có thể làm bút vẽ phù."
    textfix["兔妖巢穴，幻化胡萝卜形，拙劣掩饰。"] = "Tổ thỏ yêu, huyễn hóa thành hình cà rốt, che giấu vụng về."
    textfix["兔妖毛球，可作法器材料。"] = "Cầu lông thỏ yêu, có thể làm vật liệu pháp khí."
    textfix["兔毛耳罩，能有效抵御寒冷。"] = "Bịt tai lông thỏ, có thể chống lạnh hiệu quả."
    textfix["入定之时，不宜打扰。"] = "Lúc nhập định, không nên làm phiền."
    textfix["公园大门被锁住了。"] = "Cổng công viên bị khoá."
    textfix["公牛海带已被采摘。"] = "Tảo bò đã bị hái."
    textfix["公牛海带的根部。"] = "Phần rễ của tảo bò."
    textfix["养蜂帽，可防蜂针刺面，便于收取蜂蜜。"] = "Mũ nuôi ong, có thể phòng kim ong châm mặt, tiện thu hoạch mật ong."
    textfix["兽毛织就，踏之松软，可聚些许暖意。"] = "Được dệt từ lông thú, bước lên mềm mại, có thể tụ chút ấm áp."
    textfix["兽踪残留的气息，可循迹追踪。"] = "Khí tức còn lại từ dấu thú, có thể theo dõi."
    textfix["内含迷魂烟瘴，可制敌于无形。"] = "Bên trong chứa khói mê hồn, có thể chế địch vô hình."
    textfix["内含须弥芥子之妙，可纳物于方寸。"] = "Bên trong chứa diệu lý Tu Di hạt mù tạt, có thể thu vật vào tấc đất."
    textfix["内蕴纯阳之气。"] = "Ẩn chứa thuần dương chi khí."
    textfix["内藏天机，需细参悟。"] = "Bên trong ẩn thiên cơ, cần tỉ mỉ tham ngộ."
    textfix["内藏惊喜的泥馅饼，猪人对此颇有兴致。"] = "Bánh nhân bùn ẩn chứa bất ngờ, người lợn có hứng thú khá nhiều với cái này."
    textfix["农产品秤？称量作物之用。"] = "Cân nông sản? Dùng để cân cây trồng."
    textfix["农田杂物？需要清理。"] = "Tạp vật nông điền? Cần dọn dẹp."
    textfix["农田被烧毁了。"] = "Ruộng nương đã bị thiêu hủy."
    textfix["冠冕焚毁，孢子尽灭，威胁已除。"] = "Mũ bị thiêu hủy, bào tử diệt hết, mối đe dọa đã trừ."
    textfix["冬季知更鸟的蓝色羽毛。"] = "Lông xanh của chim cổ đỏ mùa đông."
    textfix["冬季考拉象，皮毛厚实以御寒。"] = "Koalephant mùa đông, da lông dày thực để chống lạnh."
    textfix["冬季象鼻，更为肥厚。"] = "Vòi voi mùa đông, dày hơn nhiều."
    textfix["冰属性妖鱼，可炼寒系法宝。"] = "Yêu ngư thuộc tính băng, có thể luyện pháp bảo hàn hệ."
    textfix["冰山已经完全融化了。"] = "Tảng băng đã hoàn toàn tan chảy."
    textfix["冰帽，佩戴时能缓慢降低体温。"] = "Mũ băng, khi đội có thể từ từ hạ thân nhiệt."
    textfix["冰晶哑铃，寒气凛冽。"] = "Tạ băng tinh, hàn khí lẫm liệt."
    textfix["冰猎犬，死亡时会释放寒气。"] = "Chó săn băng, khi chết sẽ phóng thích hàn khí."
    textfix["冰眼法器，可镇心魔。"] = "Pháp khí băng nhãn, có thể trấn tâm ma."
    textfix["冰箱，能有效延长食物的保鲜期。"] = "Tủ lạnh, có thể kéo dài thời gian bảo quản thức ăn hiệu quả."
    textfix["冰系傀儡，寒意凛然。"] = "Quái lỗi băng hệ, hàn ý lẫm nhiên."
    textfix["冰镇灵蕉，清凉解暑。"] = "Linh tiêu ướp lạnh, thanh lương giải nhiệt."
    textfix["冰霜法杖，能发射冰冻射线。"] = "Băng sương pháp trượng, có thể phát xạ tia băng đông."
    textfix["冰魄之眼，洞察秋毫。"] = "Băng phách chi nhãn, thấu suốt từng sợi thu."
    textfix["冰魄护符，散发寒气，可保尸体不腐，亦可伤敌。"] = "Hộ phù băng phách, tỏa ra hàn khí, có thể giữ thi thể không thối, cũng có thể làm thương địch."
    textfix["冷却的虫卵，岩浆虫在其中休眠。"] = "Trứng sâu đã nguội, sâu dung nham ngủ đông bên trong."
    textfix["冷汤，清爽解暑。"] = "Canh lạnh, thanh mát giải nhiệt."
    textfix["冷火坑在稳定燃烧。"] = "Hầm lạnh đang cháy ổn định."
    textfix["冷火坑已经熄灭。"] = "Hầm lạnh đã tắt."
    textfix["冷火坑的火即将熄灭。"] = "Lửa trong hầm lạnh sắp tắt."
    textfix["冷火坑的火焰减弱了。"] = "Lửa trong hầm lạnh yếu đi."
    textfix["冷火坑的火焰很猛烈。"] = "Lửa trong hầm lạnh rất mãnh liệt."
    textfix["冷火坑，发出寒光而非热量。"] = "Hầm lạnh, phát ra ánh sáng lạnh chứ không phải nhiệt lượng."
    textfix["冷焰燃烧，散发寒意，可保存食物。"] = "Lạnh diệm cháy, tỏa ra hàn ý, có thể bảo quản thức ăn."
    textfix["净面灵刃，可断烦恼丝，亦能采集某些脆弱灵材。"] = "Tịnh diện linh nhận, có thể đoạn phiền não ti, cũng có thể thu thập một số linh tài mong manh."
    textfix["凝练的梦魇精华，是修炼邪功、炼制魔器的至阴之物。"] = "Tinh hoa ác mộng ngưng luyện, là vật chí âm để tu luyện tà công, luyện chế ma khí."
    textfix["凝蜜太妃糖，过甜腻口，偶尔食之无妨。"] = "Ngưng mật thái phi đường, quá ngọt béo miệng, thỉnh thoảng ăn cũng không sao."
    textfix["凡俗之物，不堪大用。"] = "Vật phàm tục, không đủ dùng việc lớn."
    textfix["凡俗之物，毫无灵性。"] = "Vật trần tục, hoàn toàn không có linh tính."
    textfix["凡俗哨音，扰人清修。"] = "Tiêu âm phàm tục, quấy rối tu luyện thanh tịnh."
    textfix["凡俗炊爨，徒耗光阴。"] = "Nấu nướng trần tục, chỉ phí thời gian."
    textfix["凡俗玩物，毫无灵气。"] = "Đồ chơi phàm tục, không có chút linh khí."
    textfix["凡俗画像，难登大雅之堂。"] = "Tranh vẽ phàm tục, khó lên đại nhã chi đường."
    textfix["凡俗的戏法道具，无甚稀奇。"] = "Đạo cụ trò ảo thuật phàm tục, không có gì lạ."
    textfix["凡俗食物，仅能果腹。"] = "Thức ăn trần tục, chỉ đủ no bụng."
    textfix["凡修妄录，不足为凭。"] = "Phàm tu vọng lục, không đủ làm bằng chứng."
    textfix["凡木遇真火，自取灭亡。"] = "Phàm mộc gặp chân hỏa, tự chuốc diệt vong."
    textfix["凡火也配与三昧真火争辉？"] = "Phàm hỏa cũng đáng tranh sáng với Tam Muội Chân Hỏa?"
    textfix["凡石顽砾，岂是灵材。"] = "Đá thường thô lậu, sao xứng là linh tài."
    textfix["凡纸俗墨，不堪承载道韵。"] = "Giấy thường mực tục, không thể chứa đựng đạo vận."
    textfix["凡铁俗器，不配本尊使用。"] = "Sắt thường khí tục, không xứng với bổn tôn sử dụng."
    textfix["凡铁哑铃，轻若无物。"] = "Tạ phàm sắt, nhẹ như không có gì."
    textfix["凡铁长矛，锋刃尚可，对付寻常妖兽足矣。"] = "Trường mâu phàm sắt, lưỡi thương tạm được, đối phó yêu thú tầm thường là đủ."
    textfix["凡间乐器，不足为奇。"] = "Nhạc cụ phàm trần, không đủ lạ."
    textfix["凡间木工坊，可制寻常家具。"] = "Xưởng mộc phàm trần, có thể chế đồ nội thất thường."
    textfix["凡间草种，也配入我洞天？"] = "Hạt giống cỏ phàm trần, cũng đáng vào động thiên của ta?"
    textfix["凡间食物，勉强果腹。"] = "Thức ăn phàm trần, miễn cưỡng lấp đầy bụng."
    textfix["凡鸟之卵，勉强果腹。"] = "Trứng điểu phàm, miễn cưỡng no bụng."
    textfix["凡鸟图谱，也配入王某法眼？"] = "Đồ quyển phàm điểu, cũng đáng lọt vào mắt xanh của Vương Mỗ?"
    textfix["凶兽傀儡，气势尚可。"] = "Quái lỗi hung thú, khí thế tạm được."
    textfix["凶兽图谱，野性难驯。"] = "Đồ phổ hung thú, dã tính khó thuần."
    textfix["凶险之音，不宜多听。"] = "Âm thanh hung hiểm, không nên nghe nhiều."
    textfix["切割规整的石砖，是建筑的基石。"] = "Gạch đá được cắt ngay ngắn, là nền tảng của kiến trúc."
    textfix["划桨之韵，稍有偏差。"] = "Nhịp chèo hơi lệch một chút."
    textfix["利齿陷阱，触发时迅疾狠辣，可伤妖物筋骨。"] = "Cạm bẫy răng sắc, khi kích hoạt nhanh nhẹn hiểm ác, có thể thương gân cốt yêu vật."
    textfix["制图桌已被焚毁。"] = "Bàn vẽ bản đồ đã bị thiêu hủy."
    textfix["制图桌起火，正在燃烧。"] = "Bàn vẽ bản đồ bốc lửa, đang cháy."
    textfix["制图桌，可绘制并分享所探明的地形。"] = "Bàn vẽ bản đồ, có thể vẽ và chia sẻ địa hình đã khảo sát."
    textfix["刺骨毒木，盘踞污秽之地，吸纳死气而生。"] = "Độc mộc đâm xương, chiếm giữ đất ô uế, hút tử khí mà sống."
    textfix["前方阻塞，稍候再行。"] = "Phía trước bị tắc nghẽn, đợi chút rồi đi."
    textfix["割下的草，是常用的编织和建造材料。"] = "Cỏ đã cắt, là nguyên liệu thường dùng để đan và xây dựng."
    textfix["力场护体？倒也玄妙。"] = "Lực trường hộ thể? Cũng khá huyền diệu."
    textfix["力士，可愿做王某麾下战奴？"] = "Lực sĩ, có muốn làm chiến nô dưới trướng Vương Mỗ không?"
    textfix["力道未济，还需协调。"] = "Lực đạo chưa đủ, cần điều chỉnh thêm."
    textfix["功德兑换？以物易物。"] = "Đổi công đức? Vật đổi vật."
    textfix["加入了香料的温热饮品，能驱散寒意。"] = "Đồ uống ấm nóng thêm hương liệu, có thể xua tan cái lạnh."
    textfix["加工过的木板，是建造的基础材料。"] = "Gỗ ván đã gia công, là vật liệu cơ bản để xây dựng."
    textfix["加速手杖，持之可提升脚力，便于赶路。"] = "Trượng tăng tốc, cầm nó có thể nâng cao tốc độ chân, tiện đi đường."
    textfix["劣根凡木，也妄想成精？"] = "Phàm mộc gốc kém, cũng dám vọng tưởng thành tinh?"
    textfix["勉强可用来修补法衣"] = "Miễn cưỡng có thể dùng để vá pháp y."
    textfix["勿忘我花？观赏植物。"] = "Hoa forget-me-not? Thực vật quan thưởng."
    textfix["化为灰烬，正合我意。"] = "Hóa thành tro tàn, đúng ý ta."
    textfix["化形之基不足，难以维系。"] = "Nền tảng hóa hình chưa đủ, khó duy trì."
    textfix["化石书，阅读后能将敌人暂时石化。"] = "Sách hóa thạch, sau khi đọc có thể tạm thời đá hóa địch nhân."
    textfix["北方，属水，主杀伐。"] = "Phía bắc, thuộc thủy, chủ sát phạt."
    textfix["匠人之魂...正好用来淬炼法宝"] = "Hồn thợ thủ công... vừa hay dùng để tôi luyện pháp bảo."
    textfix["区区...重负...何足...挂齿..."] = "Bất quá... gánh nặng... có gì... đáng kể..."
    textfix["区区伐木工，也敢在此界行走？"] = "Tiều phu bình thường, cũng dám đi lại trong thế giới này?"
    textfix["区区傀儡，也敢拦路？"] = "Quái lỗi tầm thường, cũng dám chặn đường?"
    textfix["区区凡水，也配威胁本尊？"] = "Phàm thủy bình thường, cũng đáng đe dọa bổn tôn?"
    textfix["区区凡火……弹指可灭。"] = "Phàm hỏa bình thường... búng tay là diệt."
    textfix["区区凡火，也敢逞威？"] = "Phàm hỏa bình thường, cũng dám tác oai?"
    textfix["区区凡鱼，也配称量？"] = "Cá phàm tầm thường, cũng đáng cân đo?"
    textfix["区区包装之术...也敢称神通？"] = "Thuật đóng gói bình thường... cũng dám xưng là thần thông?"
    textfix["区区匠人，也敢对王某出手？"] = "Thợ thủ công bình thường, cũng dám ra tay với Vương Mỗ?"
    textfix["区区妖术，终究难敌本尊道行。"] = "Yêu thuật bình thường, cuối cùng cũng khó địch với đạo hành của bổn tôn."
    textfix["区区幻形之术，也敢在王某面前卖弄！"] = "Thuật huyễn hình bình thường, cũng dám trình diễn trước mặt Vương Mỗ!"
    textfix["区区海兽也敢在王某面前嬉戏？"] = "Hải thú tầm thường cũng dám nô đùa trước mặt Vương Mỗ?"
    textfix["区区火毒，也敢噬主？"] = "Hỏa độc bình thường, cũng dám cắn chủ?"
    textfix["区区猪妖，也敢放肆。"] = "Heo yêu bình thường, cũng dám phóng túng."
    textfix["区区玩物，蕴含土系法则。"] = "Đồ chơi bình thường, ẩn chứa pháp tắc thổ hệ."
    textfix["区区胡萝卜也敢成精？"] = "Cà rốt tầm thường cũng dám thành tinh?"
    textfix["区区蛛妖，何须专研对策？一剑斩之！"] = "Nhện yêu bình thường, cần gì chuyên nghiên cứu đối sách? Một kiếm chém!"
    textfix["区区诅咒，也配束缚本尊？"] = "Lời nguyền bình thường, cũng đáng ràng buộc bổn tôn?"
    textfix["区区鹿妖魂魄，连做器灵都不配"] = "Hồn phách lộc yêu bình thường, ngay cả làm khí linh cũng không xứng."
    textfix["千年...道行...岂惧...物重..."] = "Ngàn năm... đạo hành... sao ngại... vật nặng..."
    textfix["千年寒冰，可镇心魔，亦可保存灵物不腐。"] = "Thiên niên hàn băng, có thể trấn tâm ma, cũng có thể bảo tồn linh vật không thối."
    textfix["千目魔瞳？！何方妖物！"] = "Thiên mục ma đồng?! Yêu vật phương nào đây!"
    textfix["千里镜，能望得更远些。"] = "Thiên lý kính, có thể nhìn xa hơn."
    textfix["半妖之魂...倒是罕见的炼器材料"] = "Hồn nửa yêu... lại là nguyên liệu luyện khí hiếm có."
    textfix["半妖猪人，灵智初开，可交易，亦需提防其凶性。"] = "Heo người nửa yêu, linh trí mới khai mở, có thể giao dịch, cũng cần đề phòng tính hung dữ của nó."
    textfix["半妖颅骨...可炼为追踪傀儡！"] = "Đầu lâu nửa yêu... có thể luyện thành bù nhìn truy tung!"
    textfix["半透明的幽灵胡萝卜鼠，速度奇快。"] = "Chuột cà rốt ma bán trong suốt, tốc độ kỳ lạ nhanh."
    textfix["华夫饼，网格状的外形使其更容易蘸取酱汁。"] = "Bánh waffle, hình dạng lưới làm nó dễ chấm sốt hơn."
    textfix["卒子雕像，棋盘上的基础棋子。"] = "Tượng đá tốt, quân cờ cơ bản trên bàn cờ."
    textfix["单只丝织手套，做工精细。"] = "Găng tay lụa một chiếc, làm công tinh tế."
    textfix["单向传送门，有去无回。"] = "Cổng truyền tống một chiều, có đi không về."
    textfix["南方，属火，主生机。"] = "Phía nam, thuộc hỏa, chủ sinh cơ."
    textfix["南瓜派，香甜软糯。"] = "Bánh pie bí ngô, thơm ngọt dẻo mềm."
    textfix["南辕北辙，岂能抵达？"] = "Nam viên bắc triệt, sao có thể đến được?"
    textfix["卧榻之侧岂容火患？"] = "Bên giường ngủ sao chấp nhận hỏa hoạn?"
    textfix["即将功成。"] = "Sắp thành công."
    textfix["即将成丹。"] = "Sắp thành đan."
    textfix["卷心菜沙拉，口感清爽。"] = "Salad cải bắp, khẩu cảm thanh mát."
    textfix["厄运妖鱼，避之为妙。"] = "Yêu ngư vận xui, tránh đi là hay."
    textfix["厚实背心，能有效抵御寒冷。"] = "Áo ba lỗ dày, có thể chống lạnh hiệu quả."
    textfix["原木腐朽，需更换新木以续菌菇生机。"] = "Gỗ gốc đã mục, cần thay gỗ mới để tiếp tục sinh cơ nấm."
    textfix["厨修之魂...正好用来试炼新丹！"] = "Hồn bếp tu... vừa hay dùng để thử luyện đan mới!"
    textfix["厨艺之道，非我所长。"] = "Nấu nướng vốn không phải sở trường của ta."
    textfix["厨艺非我所长。"] = "Nấu ăn không phải sở trường của ta."
    textfix["去吧，莫要让我失望。"] = "Đi đi, chớ để ta thất vọng."
    textfix["又一块船体的碎片。"] = "Thêm một mảnh vỡ thân thuyền."
    textfix["又一座破败的建筑。"] = "Thêm một tòa nhà đổ nát."
    textfix["又一组发条残骸，无用之物。"] = "Lại thêm một nhóm tàn hài lên dây cót, vật vô dụng."
    textfix["友善果蝇？有助于作物。"] = "Ruồi trái cây thân thiện? Có ích cho cây trồng."
    textfix["双子魔眼雕像，双重视线带来双倍的压力。"] = "Tượng đá song nhãn ma mắt, ánh mắt đôi mang lại áp lực gấp đôi."
    textfix["双生魂体...倒是炼制分魂法器的好材料"] = "Hồn thể song sinh... lại là nguyên liệu tốt để luyện chế phân hồn pháp khí."
    textfix["反伤灵药，以牙还牙。"] = "Linh dược phản thương, lấy nanh trả nanh."
    textfix["反应训练设施被烧毁了。"] = "Cơ sở huấn luyện phản ứng bị thiêu huỷ."
    textfix["发光浆果慕斯，蕴含光灵气。"] = "Mousse quả mọng phát sáng, hàm chứa quang linh khí."
    textfix["发光灵蟹，夜明如灯。"] = "Linh giải phát sáng, ban đêm sáng như đèn."
    textfix["发光飞虫？可作光源。"] = "Côn trùng phát sáng? Có thể làm nguồn sáng."
    textfix["发条傀儡，行动有矩，攻其核心可破。"] = "Bù nhìn lên dây cót, hành động có quy tắc, tấn công lõi của nó có thể phá."
    textfix["发条石魔像，冲锋之势，有撼山之威。"] = "Phát điều thạch ma tượng, khí thế xung phong, có uy lực lay chuyển núi."
    textfix["发条骑士，一种机械构造体，攻击方式规律。"] = "Kỵ sĩ lên dây cót, một loại cấu thể cơ khí, cách tấn công có quy luật."
    textfix["发电机的电力输出不足。"] = "Đầu ra điện lực của máy phát điện không đủ."
    textfix["发电机目前没有运行。"] = "Máy phát điện hiện không vận hành."
    textfix["发电机被烧毁了。"] = "Máy phát điện bị thiêu huỷ."
    textfix["发电机起火了。"] = "Máy phát điện bốc lửa."
    textfix["发酵改良剂？效果更强。"] = "Chất cải tạo lên men? Hiệu quả mạnh hơn."
    textfix["变异怪鸟，凶性毕露。"] = "Dị điểu biến dị, hung tính bộc lộ hết."
    textfix["变异笔记，玄妙非常。"] = "Ghi chú biến dị, huyền diệu phi thường."
    textfix["古树戏服，生机盎然。"] = "Trang phục cổ thụ, sinh cơ tràn đầy."
    textfix["古树灵根，深扎海底。"] = "Linh căn cổ thụ, cắm sâu đáy biển."
    textfix["古树灵浆，可促生长。"] = "Linh tương cổ thụ, có thể thúc đẩy sinh trưởng."
    textfix["古树面具，生机勃勃。"] = "Mặt nạ cổ thụ, sinh cơ bừng bừng."
    textfix["古物斑驳，气韵犹存。"] = "Cổ vật loang lổ, khí vận vẫn còn."
    textfix["古老的壁画，记录着失落的历史。"] = "Tranh tường cổ xưa, ghi lại lịch sử đã mất."
    textfix["古鼎空空，待我使用。"] = "Cổ đỉnh rỗng không, chờ ta sử dụng."
    textfix["召唤天外之火，威力尚可。"] = "Triệu hoán thiên ngoại chi hỏa, uy lực tạm được."
    textfix["可作看守洞府的灵宠。"] = "Có thể làm linh thú canh giữ động phủ."
    textfix["可充饥肠，聊胜于无。"] = "Có thể no bụng, cũng hơn là không có."
    textfix["可惜了这妖鱼材料..."] = "Tiếc thay vật liệu yêu ngư này..."
    textfix["可惜，让那妖物逃了。"] = "Đáng tiếc, để yêu vật đó chạy thoát."
    textfix["叶肉糕？素食点心。"] = "Bánh thịt lá? Điểm tâm chay."
    textfix["吃东西时掉落的碎屑。"] = "Vụn bánh rơi ra khi ăn."
    textfix["吉祥红包，内常装有小礼物或祝福语。"] = "Bao lì xì cát tường, bên trong thường đựng quà nhỏ hoặc lời chúc phúc."
    textfix["吉祥羽扇，扇动时据说能招来好运。"] = "Quạt lông cát tường, khi quạt nghe nói có thể mang lại may mắn."
    textfix["吞天噬地，不食五谷。"] = "Nuốt trời ăn đất, không ăn ngũ cốc."
    textfix["吸食生灵之气的精怪。"] = "Tinh quái hút sinh linh chi khí."
    textfix["告密的心，使用它可以复活倒下的队友。"] = "Trái tim mách lẻo, dùng nó có thể hồi sinh đồng đội ngã xuống."
    textfix["呔...！"] = "Hì...!"
    textfix["周遭气机凶险，不可入定。"] = "Khí cơ xung quanh hung hiểm, không thể nhập định."
    textfix["呼朋引伴，不过是徒增伤亡。"] = "Gọi bằng hữu, chẳng qua là thêm thương vong mà thôi."
    textfix["咫尺天涯杖，心念所至，身即可达，然耗神甚巨。"] = "Xích Thiên Nhai trượng, tâm niệm đến đâu, thân có thể đến đó, nhưng hao thần rất lớn."
    textfix["哈奇，一种奇特的水生生物，能储存物品。"] = "Hutch, một loại sinh vật thủy sinh kỳ đặc, có thể lưu trữ vật phẩm."
    textfix["哑灵的怨气...倒是炼制阴魂法器的好材料"] = "Oán khí của câm linh... lại là nguyên liệu tốt để luyện âm hồn pháp khí."
    textfix["哨所失能，暂无威胁。"] = "Tiền đồn mất năng lực, tạm không có mối đe dọa."
    textfix["哼...此物...颇有...分量..."] = "Hừ... vật này... thực sự... nặng..."
    textfix["哼！中了妖咒的猴精，也敢放肆？"] = "Hừ! Hầu tinh trúng yêu chú, cũng dám phóng túng?"
    textfix["哼！倒是懂些起死回生的偏门术法"] = "Hừ! Lại biết vài môn thuật pháp bàng môn hoàn sinh."
    textfix["哼！凡间学者，也敢妄谈天道？"] = "Hừ! Học giả phàm trần, cũng dám bàn luận thiên đạo?"
    textfix["哼！凡间工匠，也敢在此卖弄？"] = "Hừ! Thợ thủ công phàm trần, cũng dám phô diễn ở đây?"
    textfix["哼！凡间庖厨，也敢在此界生火？"] = "Hừ! Đầu bếp phàm trần, cũng dám nhóm lửa ở thế giới này?"
    textfix["哼！半妖之躯，也敢在王某面前现身？"] = "Hừ! Thân nửa yêu, cũng dám xuất hiện trước mặt Vương Mỗ?"
    textfix["哼！地脉陷阱，也想困住王某？"] = "Hừ! Bẫy địa mạch, cũng muốn giam Vương Mỗ?"
    textfix["哼！域外心魔，也敢在此界游荡？"] = "Hừ! Tâm ma ngoài cõi, cũng dám lang thang trong thế giới này?"
    textfix["哼！影修邪术...%s你究竟师承何人？！"] = "Hừ! Ảnh tu tà thuật... %s ngươi rốt cuộc học từ ai?!"
    textfix["哼！月宫小妖，也敢在王某面前现形？"] = "Hừ! Yêu nhỏ nguyệt cung, cũng dám hiện hình trước mặt Vương Mỗ?"
    textfix["哼！机关傀儡也敢妄称生灵？"] = "Hừ! Cơ quan bù nhìn cũng dám xưng là sinh linh?"
    textfix["哼！水族小妖，也敢上岸行走？"] = "Hừ! Yêu nhỏ thủy tộc, cũng dám lên bờ đi lại?"
    textfix["哼！竟敢窥探时间法则？"] = "Hừ! Thực sự dám dòm ngó thời gian pháp tắc?"
    textfix["哼！草木成精，也敢幻化人形？"] = "Hừ! Thảo mộc thành tinh, cũng dám hóa thành người?"
    textfix["哼！蛮族武修，也敢自称战神？"] = "Hừ! Võ tu man tộc, cũng dám tự xưng chiến thần?"
    textfix["哼！装聋作哑之辈..."] = "Hừ! Loại giả điếc giả câm..."
    textfix["哼！通灵之体...倒是少见"] = "Hừ! Thể thông linh... thực ra hiếm thấy."
    textfix["哼！黄口小儿，也在此妄谈天道？"] = "Hừ! Trẻ con miệng còn hôi sữa, cũng dám bàn luận thiên đạo ở đây?"
    textfix["哼，一介凡夫，也敢窥探天机？"] = "Hừ, một gã phàm phu, cũng dám dòm ngó thiên cơ?"
    textfix["哼，勉强可作洞府摆设"] = "Hừ, miễn cưỡng có thể dùng làm đồ trang trí động phủ."
    textfix["哼，区区毒刺，也敢伤我道体！"] = "Hừ, gai độc bình thường, cũng dám làm tổn thương đạo thể của ta!"
    textfix["哼，权当喂食看门犬了。"] = "Hừ, coi như cho chó canh ăn vậy."
    textfix["哼，能入我药鼎，是你的造化。"] = "Hừ, có thể vào đỉnh dược của ta, đó là phúc duyên của ngươi."
    textfix["哼，草木枯荣，亦是天道。"] = "Hừ, thảo mộc khô nở, cũng là thiên đạo."
    textfix["哼，雕虫小技，也敢窥视王某！"] = "Hừ, trò vặt vãnh, cũng dám dòm ngó Vương Mỗ!"
    textfix["唤风妖杖，威力巨大却难以驾驭，易遭反噬。"] = "Yêu trượng gọi gió, uy lực khổng lồ nhưng khó điều khiển, dễ bị phản phệ."
    textfix["喂食游戏套装？搭建用。"] = "Bộ trò chơi cho ăn? Dùng để dựng."
    textfix["喂食游戏？需准备食物。"] = "Trò chơi cho ăn? Cần chuẩn bị thức ăn."
    textfix["喜庆傀儡，华而不实。"] = "Quái lỗi hỷ khánh, hoa mà không thực."
    textfix["喜庆的红灯笼，寓意吉祥，可照亮前路。"] = "Đèn lồng đỏ vui vẻ, mang ý nghĩa cát tường, có thể chiếu sáng con đường phía trước."
    textfix["喜庆祥瑞图样，寓意吉祥。"] = "Mẫu tường vân hỷ khánh, mang ý nghĩa cát tường."
    textfix["嗜血妖蚊，遁速极快，被其叮咬会损及元气。"] = "Yêu muỗi háo huyết, tốc độ trốn chạy cực nhanh, bị nó cắn sẽ tổn hại nguyên khí."
    textfix["嗯...此中或有可取之处..."] = "Ừm... trong này có thể có chỗ đáng học..."
    textfix["嗯...略有倦意袭来。"] = "Ừm... hơi có chút mệt mỏi ập đến."
    textfix["嗯？何方魔气降临此界？"] = "Ừm? Ma khí phương nào giáng xuống thế giới này?"
    textfix["嗯？竟是法则之火？"] = "Ừm? Thực sự là lửa pháp tắc?"
    textfix["器皿与灵食属性不合，不宜盛装。"] = "Đồ đựng và linh thực không hợp thuộc tính, không nên dùng."
    textfix["器皿已合，无需更换。"] = "Đồ đựng đã hợp rồi, không cần đổi."
    textfix["噩梦猪人雕像，煞气凝结，似有残念附着。"] = "Tượng đá heo người ác mộng, sát khí ngưng kết, dường như có tàn niệm bám víu."
    textfix["囊内自成寒冰结界，可保物品不腐。"] = "Trong túi tự thành hàn băng kết giới, có thể bảo vật phẩm không thối."
    textfix["四下无宝，空手而归。"] = "Xung quanh không có bảo vật, trắng tay trở về."
    textfix["回魂仙石，蕴含生死法则之力，乃逆天改命之宝。"] = "Hồi hồn tiên thạch, hàm chứa lực lượng sinh tử pháp tắc, là bảo vật nghịch thiên cải mệnh."
    textfix["困魔法器，囚禁灵能。"] = "Pháp khí giam ma, giam cầm linh năng."
    textfix["国王戏服，霸气凛然。"] = "Trang phục quốc vương, bá khí lẫm nhiên."
    textfix["国王雕像，颇具威仪。"] = "Tượng đá quốc vương, khá uy nghi."
    textfix["国王面具，霸气外露。"] = "Mặt nạ quốc vương, bá khí lộ ra ngoài."
    textfix["图卷所指之地，似不存于此方世界。"] = "Nơi mà đồ quyển chỉ, dường như không tồn tại trong thế giới này."
    textfix["土壤改良剂？促进生长。"] = "Chất cải tạo đất? Thúc đẩy sinh trưởng."
    textfix["土豆旋丝，凡间小吃。"] = "Xoắn khoai tây, đồ ăn vặt phàm trần."
    textfix["土豆泥，凡人之食。"] = "Khoai tây nghiền, thức ăn của phàm nhân."
    textfix["土豆煎饼，外酥里嫩。"] = "Bánh khoai tây chiên, bên ngoài giòn bên trong mềm."
    textfix["土豆种子。"] = "Hạt giống khoai tây."
    textfix["土豆舒芙蕾，做工精细。"] = "Bánh soufflé khoai tây, làm công tinh tế."
    textfix["土豆，饱腹之物。"] = "Khoai tây, vật no bụng."
    textfix["在王某神识之下，无所遁形。"] = "Dưới thần thức của Vương Mỗ, không có gì có thể ẩn mình."
    textfix["地力贫瘠，需以灵肥滋养。"] = "Địa lực cằn cỗi, cần dùng linh phân tưới dưỡng."
    textfix["地动山摇，是那沙中妖物作怪。"] = "Đất rung núi chuyển, là yêu vật trong cát quấy phá."
    textfix["地动山摇，此地不宜久留。"] = "Đất rung núi chuyển, nơi này không nên ở lâu."
    textfix["地动山摇，需稳守心神。"] = "Đất rung núi chuyển, cần vững giữ tâm thần."
    textfix["地妖洞府...待王某一探究竟！"] = "Động phủ địa yêu... để Vương Mỗ thám hiểm!"
    textfix["地妖秽气...但此物夜视之能尚可一用"] = "Khí tức ô uế địa yêu... nhưng năng lực nhìn đêm của vật này vẫn có thể dùng."
    textfix["地妖藏形...待我逼它现形。"] = "Địa yêu ẩn hình... để ta bức nó hiện hình."
    textfix["地宫禁制重启，那些傀儡又复苏了。"] = "Cấm chế địa cung khởi động lại, những bù nhìn kia lại hồi phục."
    textfix["地底妖蝠，嗜血扰神。"] = "Dơi yêu dưới đất, háo huyết quấy thần."
    textfix["地底毒瘴翻涌，妖物即将破土。"] = "Độc khí dưới đất trào lên, yêu vật sắp phá đất."
    textfix["地底魔物？哼，若敢现世，斩了便是。"] = "Ma vật dưới đất? Hừ, nếu dám xuất hiện, chém là xong."
    textfix["地火式微，熔浆渐凝，火源不稳。"] = "Địa hỏa suy vi, dung nham dần đông, hỏa nguyên không ổn định."
    textfix["地火暂熄，熔岩凝固，需待地脉能量重新汇聚。"] = "Địa hỏa tạm tắt, nham thạch đông cứng, cần đợi địa mạch năng lượng tụ hội lại."
    textfix["地火熔岩池，炽热异常，乃炼器的绝佳火源。"] = "Địa hỏa nham thạch trì, nhiệt độ dị thường, là hỏa nguyên tuyệt hảo để luyện khí."
    textfix["地火稳定，热力充沛，正合淬炼之用。"] = "Địa hỏa ổn định, nhiệt lực sung mãn, đúng hợp dùng để tôi luyện."
    textfix["地火精石...正好炼制火系法宝！"] = "Địa hỏa tinh thạch... vừa hay luyện pháp bảo hỏa hệ!"
    textfix["地火过旺，灵植被灼伤，生机断绝。"] = "Địa hỏa quá mạnh, linh thực bị bỏng, sinh cơ đứt tuyệt."
    textfix["地灵肉蓕...蕴含生机"] = "Nhục chi địa linh... ẩn chứa sinh cơ."
    textfix["地狱独眼巨猪，散发着硫磺的气息。"] = "Độc nhãn cự trư địa ngục, tỏa ra khí tức lưu huỳnh."
    textfix["地穴入口，阴气外泄。"] = "Cửa vào động phủ, âm khí rò rỉ ra ngoài."
    textfix["地穴无昼夜之分，然心绪不宁，难以安眠。"] = "Động phủ không phân ngày đêm, nhưng tâm tư bất an, khó ngủ yên."
    textfix["地穴毒蛛，獠牙带煞，需小心其毒液。"] = "Nhện độc hang hốc, nanh có sát khí, cần cẩn thận độc dịch của nó."
    textfix["地穴阴寒，岩石沁骨。"] = "Động phủ âm hàn, đá thấm vào xương."
    textfix["地穴阴气侵体，小憩反损精神。"] = "Âm khí động phủ xâm thể, nghỉ ngơi ngược lại tổn hại tinh thần."
    textfix["地精木雕，雕工粗糙，或与某些精怪有所关联。"] = "Điêu khắc gỗ địa tinh, điêu công thô ráp, hoặc có liên quan đến một số tinh quái."
    textfix["地精老妪木雕，与那地精老翁像似是一对。"] = "Điêu khắc gỗ bà lão địa tinh, với tượng ông lão địa tinh kia dường như là một đôi."
    textfix["地脉交汇处，竟生此通灵草精。"] = "Nơi địa mạch hội tụ, thực sự sinh ra thảo tinh thông linh này."
    textfix["地脉灵果...蕴含精纯土灵气"] = "Linh quả địa mạch... ẩn chứa thổ linh khí tinh thuần."
    textfix["地脉硝石，可配火药，亦能用于炼制某些爆裂符箓。"] = "Diêm thạch địa mạch, có thể phối làm thuốc súng, cũng có thể dùng để luyện chế một số phù lục bùng nổ."
    textfix["地脉被扰，需小心应对。"] = "Địa mạch bị quấy rầy, cần cẩn thận ứng phó."
    textfix["地脉阴气凝结所成的光果，蕴含微弱灵力。"] = "Quả sáng được hình thành từ địa mạch âm khí ngưng kết, ẩn chứa linh lực yếu ớt."
    textfix["地脉震动，有巨虫潜行。"] = "Địa mạch rung chuyển, có trùng khổng lồ bí mật di chuyển."
    textfix["地行妖在寻矿...正好为我所用。"] = "Địa hành yêu đang tìm khoáng... vừa hay cho ta sử dụng."
    textfix["地龙妖兽！正好取你妖丹。"] = "Địa long yêu thú! Vừa hay lấy yêu đan của ngươi."
    textfix["场地芜杂，非博弈之所。"] = "Địa điểm lộn xộn, không phải nơi để tranh tài."
    textfix["坎普斯的袋子，拥有巨大的储物空间。"] = "Túi của Krampus, có không gian lưu trữ khổng lồ."
    textfix["坎普斯，会偷取地上物品的怪物。"] = "Krampus, quái vật sẽ đánh cắp vật phẩm trên đất."
    textfix["坐骑伤重，不宜再战。"] = "Kỳ thú thương nặng, không nên tiếp tục chiến đấu."
    textfix["坐骑心性未平，暂不宜驾驭。"] = "Tâm tính của kỳ thú chưa bình ổn, chưa nên điều khiển."
    textfix["坟冢已开，阴气外泄，恐生不祥。"] = "Mộ phần đã mở, âm khí rò rỉ, e sinh bất tường."
    textfix["垂钓亦是修心，不急不躁。"] = "Câu cá cũng là tu tâm, không vội không nóng."
    textfix["基座完好，可放置物品。"] = "Đế tòa hoàn hảo, có thể đặt vật phẩm."
    textfix["基座已充能，等待插入钥匙启动。"] = "Bệ đã nạp năng, chờ cắm chìa khóa khởi động."
    textfix["基座机关已解锁，可以使用了。"] = "Cơ quan bệ đã được mở khóa, có thể sử dụng rồi."
    textfix["基座需宝石激活。"] = "Đế tòa cần đá quý kích hoạt."
    textfix["堆肥桶烧毁。"] = "Thùng ủ phân bị thiêu."
    textfix["堆肥桶？制造肥料。"] = "Thùng ủ phân? Chế tạo phân bón."
    textfix["堆肥状态良好。"] = "Trạng thái phân ủ tốt."
    textfix["堆肥过干，需加水。"] = "Phân ủ quá khô, cần thêm nước."
    textfix["堆肥过湿，需调整。"] = "Phân ủ quá ướt, cần điều chỉnh."
    textfix["堆肥？可滋养土壤。"] = "Phân ủ? Có thể bồi dưỡng đất."
    textfix["增攻灵药，战斗必备。"] = "Linh dược tăng công, cần thiết trong chiến đấu."
    textfix["墨西哥玉米粉蒸肉，用玉米叶包裹。"] = "Tamale Mexico, được bọc bằng lá ngô."
    textfix["墨鱼？其墨可制符箓。"] = "Cá mực? Mực của nó có thể chế phù lục."
    textfix["壁画上似乎刻画着某种被崇拜的存在。"] = "Trên tranh tường dường như khắc họa một sự tồn tại được tôn sùng nào đó."
    textfix["壁画描绘了远古文明的仪式场景。"] = "Tranh tường mô tả cảnh nghi lễ của văn minh viễn cổ."
    textfix["壶中已空，待我取些灵泉来。"] = "Bình đã cạn, để ta lấy thêm linh tuyền."
    textfix["壶中无水，无法使用。"] = "Trong bình không có nước, không thể sử dụng."
    textfix["夏季考拉象，性情相对温和。"] = "Koalephant mùa hè, tính tình tương đối ôn hòa."
    textfix["夏季象鼻，质地较轻薄。"] = "Vòi voi mùa hè, chất địa khá nhẹ mỏng."
    textfix["夏炎彩衫，花纹艳丽，穿着它心情似乎会轻松些。"] = "Hạ viêm thái sam, hoa văn sặc sỡ, mặc nó tâm trạng dường như sẽ nhẹ nhàng hơn."
    textfix["多枝树已被烧毁。"] = "Cây nhiều cành đã bị thiêu hủy."
    textfix["多枝树已被砍倒，主要获得树枝。"] = "Cây nhiều cành đã bị chặt hạ, chủ yếu thu được cành cây."
    textfix["多枝树正在燃烧。"] = "Cây nhiều cành đang cháy."
    textfix["多枝树的种子，可以种植。"] = "Hạt giống cây nhiều cành, có thể trồng."
    textfix["多枝树苗，生长缓慢但生命力顽强。"] = "Cây con nhiều cành, sinh trưởng chậm nhưng sức sống mãnh liệt."
    textfix["多枝树，主要产出树枝，木材较少。"] = "Cây nhiều cành, chủ yếu sản xuất cành cây, gỗ ít hơn."
    textfix["多汁浆果丛，果实更为饱满。"] = "Bụi quả mọng nhiều nước, quả thực đầy đặn hơn."
    textfix["夜明法眼，洞彻幽冥。"] = "Pháp nhãn dạ minh, thấu suốt u minh."
    textfix["夜间乃修炼佳时，岂可虚度于小憩。"] = "Đêm khuya là thời gian tu luyện tốt, sao có thể lãng phí vào giấc nghỉ."
    textfix["夜间亮片？王某夜可视物！"] = "Lame ban đêm? Vương Mỗ ban đêm có thể nhìn thấy vật!"
    textfix["夜间假饵？王某何需此物！"] = "Mồi giả ban đêm? Vương Mỗ cần gì vật này!"
    textfix["大光明咒，普照大千。"] = "Chú đại quang minh, chiếu khắp đại thiên."
    textfix["大型水晶池？灵气充裕。"] = "Ao tinh thể lớn? Linh khí sung túc."
    textfix["大漠狂沙，燥烈异常。"] = "Cát điên đại mạc, khô rát bất thường."
    textfix["大理石雕像，雕工尚可，却无灵韵。"] = "Thạch tượng đá cẩm thạch, điêu công tạm được, nhưng không có linh vận."
    textfix["大蒜种子。"] = "Hạt giống tỏi."
    textfix["大蒜，可驱虫辟邪。"] = "Tỏi, có thể đuổi trùng trừ tà."
    textfix["大道之上，又进一步。"] = "Trên đại đạo, lại tiến thêm một bước."
    textfix["大道玄妙，又窥得一丝真谛。"] = "Đại đạo huyền diệu, lại thấu được một sợi chân đế."
    textfix["大道至理，需潜心参悟。"] = "Đại đạo chí lý, cần chuyên tâm tham ngộ."
    textfix["大量奖票。"] = "Số lượng lớn vé thưởng."
    textfix["大门正在积聚开启所需的能量。"] = "Cổng đang tích tụ năng lượng cần thiết để mở."
    textfix["大门能量耗尽，暂时无法使用。"] = "Năng lượng cổng cạn kiệt, tạm thời không thể sử dụng."
    textfix["天书现世！"] = "Thiên thư xuất thế!"
    textfix["天体圣殿的守护部件，需要与其他部件组合。"] = "Bộ phận bảo vệ của thánh điện thiên thể, cần kết hợp với các bộ phận khác."
    textfix["天体圣殿的象征物。"] = "Vật tượng trưng của thánh điện thiên thể."
    textfix["天体祭坛尚未建造完成。"] = "Tế đàn thiên thể chưa xây dựng hoàn thành."
    textfix["天体英雄雕像，象征着一次艰难的胜利。"] = "Tượng đá anh hùng thiên thể, tượng trưng cho một chiến thắng gian khổ."
    textfix["天体裂隙暂时平静了下来。"] = "Thiên thể liệt khích tạm thời bình tĩnh xuống."
    textfix["天外陨星冲击所成，气息迥异。"] = "Được hình thành từ thiên thạch ngoài trời va vào, khí tức hoàn toàn khác."
    textfix["天宫仙铠碎片，华美非常。"] = "Mảnh tiên khải thiên cung, hoa mỹ phi thường."
    textfix["天寒地冻，菌菇生长停滞。"] = "Trời lạnh đất đông, nấm sinh trưởng dừng lại."
    textfix["天工织机，巧夺天工。"] = "Khung dệt thiên công, tài khéo vượt thiên công."
    textfix["天时不利，暂且退避。"] = "Thiên thời bất lợi, tạm thời rút lui."
    textfix["天时不济，灵韵受阻。"] = "Thiên thời không thuận, linh vận bị cản."
    textfix["天机不可泄露。"] = "Thiên cơ không thể tiết lộ."
    textfix["天机玄妙，不可轻言。"] = "Thiên cơ huyền diệu, không thể nói bừa."
    textfix["天机蒙昧，难窥其踪。"] = "Thiên cơ huyền bí, khó nhìn ra dấu vết."
    textfix["天罗地网阵基，需布于灵气汇聚之处。"] = "Trận cơ thiên la địa võng, cần bố trí ở nơi linh khí hội tụ."
    textfix["天罗地网，可捕海妖。"] = "Thiên la địa võng, có thể bắt hải yêu."
    textfix["天罗地网，终难逃本尊掌心。"] = "Thiên la địa võng, cuối cùng cũng khó thoát lòng bàn tay bổn tôn."
    textfix["天道无常，此等变数不足为虑。"] = "Thiên đạo vô thường, biến số như vậy không đáng lo."
    textfix["天降甘霖，却扰我淬炼气血之功。"] = "Trời ban cam lộ, nhưng lại quấy rầy công phu tôi luyện khí huyết của ta."
    textfix["天雷法咒，诛邪灭魔。"] = "Pháp chú thiên lôi, trừ tà diệt ma."
    textfix["天高海阔，任我遨游。"] = "Trời cao biển rộng, tùy ta ngao du."
    textfix["太阴炉组件，需精心组装。"] = "Cấu kiện lò thái âm, cần cẩn thận lắp ráp."
    textfix["太阴炼器炉，玄妙非常。"] = "Lò luyện khí thái âm, huyền diệu phi thường."
    textfix["太阴碎岩杵，开山裂石。"] = "Chày nghiền đá thái âm, khai sơn liệt thạch."
    textfix["太阴精华，凝结成晶。"] = "Tinh hoa thái âm, ngưng kết thành tinh."
    textfix["太阴雷珠，威力惊人。"] = "Lôi châu thái âm, uy lực kinh người."
    textfix["太阴雷珠，自行崩裂。"] = "Lôi châu thái âm, tự mình vỡ vụn."
    textfix["失衡的陀螺，旋转时散发微弱的不详波动。"] = "Con quay mất thăng bằng, khi xoay tỏa ra làn sóng bất tường vi nhược."
    textfix["奇特装置。"] = "Thiết bị kỳ lạ."
    textfix["奖票？兑换奖品。"] = "Vé thưởng? Đổi phần thưởng."
    textfix["女武神战盔，据说能获得独角兽的祝福。"] = "Chiến khôi nữ vũ thần, nghe nói có thể nhận được phước lành của kỳ lân."
    textfix["女武神！可愿做王某麾下战将？"] = "Nữ chiến thần! Có muốn làm chiến tướng dưới trướng Vương Mỗ không?"
    textfix["女王戏服，威仪万千。"] = "Trang phục nữ vương, uy nghi vạn phần."
    textfix["女王有要务在身，稍后再献。"] = "Nữ vương đang bận việc quan trọng, dâng sau cũng được."
    textfix["女王面具，威仪凛然。"] = "Mặt nạ nữ vương, uy nghi lẫm nhiên."
    textfix["好强的妖气！来者绝非善类。"] = "Yêu khí thật mạnh! Kẻ đến tuyệt không phải loại thiện."
    textfix["如坠冰窟，速速烘干法体！"] = "Như rơi vào hang băng, nhanh sấy khô pháp thể!"
    textfix["如此慢行，与散步何异？"] = "Đi chậm như vậy, khác gì tản bộ?"
    textfix["妄想逃出本尊神识范围？"] = "Vọng tưởng thoát khỏi phạm vi thần thức của bổn tôn?"
    textfix["妖兽化形？倒是有些意思"] = "Yêu thú hóa hình? Lại có chút thú vị."
    textfix["妖兽排泄之物，污秽却蕴含一丝未化灵气，可肥灵田。"] = "Vật bài tiết của yêu thú, ô uế nhưng ẩn chứa một sợi linh khí chưa hóa, có thể bón linh điền."
    textfix["妖兽肉生食？谨慎为妙。"] = "Thịt yêu thú ăn sống? Thận trọng là hay."
    textfix["妖兽？小心为上。"] = "Yêu thú? Cẩn thận là thượng sách."
    textfix["妖喙？蕴含奇异法力！"] = "Mỏ yêu? Hàm chứa pháp lực kỳ dị!"
    textfix["妖巢焚毁，污秽暂清，然此地风水已遭败坏。"] = "Tổ yêu thiêu hủy, ô uế tạm sạch, nhưng phong thủy nơi này đã bị hủy hoại."
    textfix["妖帆？不如王某御风而行！"] = "Buồm yêu? Không bằng Vương Mỗ ngự phong mà hành!"
    textfix["妖植藤蔓，凶相毕露。"] = "Dây leo yêu thực, hung tướng bộc lộ hết."
    textfix["妖植血肉，生机诡异，凡人不可妄食。"] = "Huyết nhục yêu thực, sinh cơ quái dị, phàm nhân không thể tùy tiện ăn."
    textfix["妖气临近，宝物不远。"] = "Yêu khí đang đến gần, bảo vật không xa."
    textfix["妖气汇聚之所，必有蝠王蛰伏。"] = "Nơi yêu khí tụ tập, chắc chắn có Bức Vương ẩn phục."
    textfix["妖气萦绕的木桶，内藏猴精巢穴。"] = "Thùng gỗ vây quanh yêu khí, bên trong ẩn tổ hầu tinh."
    textfix["妖熊皮毛，灵气充沛，是上好的炼器材料。"] = "Da lông gấu yêu, linh khí dồi dào, là nguyên liệu luyện khí thượng hạng."
    textfix["妖物化形，气势更盛。"] = "Yêu vật hóa hình, khí thế mạnh hơn."
    textfix["妖物巢穴，小心为妙。"] = "Sào huyệt yêu vật, cẩn thận là hay."
    textfix["妖物显形，当以法术镇之。"] = "Yêu vật hiện hình, nên dùng pháp thuật trấn áp."
    textfix["妖物狂怒，毒瘴滔天！"] = "Yêu vật cuồng nộ, độc khí tràn trời!"
    textfix["妖物被困，犹自挣扎。"] = "Yêu vật bị giam cầm, vẫn tự vùng vẫy."
    textfix["妖猴！正好取你妖丹炼制破障丹！"] = "Yêu hầu! Vừa hay lấy yêu đan của ngươi để luyện phá chướng đan!"
    textfix["妖王遁走留下的地穴，煞气弥漫。"] = "Hầm hố do yêu vương độn đi để lại, sát khí lan tràn."
    textfix["妖瞳座狼，凶光毕露。"] = "Tọa lang yêu đồng, hung quang bộc lộ hết."
    textfix["妖禽之卵，冰气缭绕，非寻常之法可烹。"] = "Trứng yêu cầm, băng khí vây quanh, không phải phương pháp thông thường có thể nấu."
    textfix["妖禽本命翎羽，内含精纯水灵之气。"] = "Bản mệnh lông yêu cầm, bên trong chứa thủy linh chi khí tinh thuần."
    textfix["妖禽羽毛？可炼飞行符！"] = "Lông yêu cầm? Có thể luyện phi hành phù!"
    textfix["妖禽风帆？勉强一试！"] = "Buồm yêu cầm? Miễn cưỡng thử một lần!"
    textfix["妖羽织布？倒有些门道..."] = "Vải dệt lông yêu? Lại có chút cơ chế..."
    textfix["妖蚊在手，其腹鼓胀，吸食的正是生灵精血。"] = "Yêu muỗi trên tay, bụng nó căng phồng, đang hút là tinh huyết của sinh linh."
    textfix["妖蝠之翼，阴气浓郁。"] = "Cánh dơi yêu, âm khí nồng nặc."
    textfix["妖蝠排泄之物，污秽不堪，却可肥地。"] = "Vật bài tiết của dơi yêu, ô uế không chịu được, nhưng có thể bón đất."
    textfix["姜饼人，是节日的传统点心。"] = "Bánh gừng người, là điểm tâm truyền thống ngày lễ."
    textfix["姜饼制成的小猪造型点心。"] = "Điểm tâm tạo hình lợn nhỏ làm từ bánh gừng."
    textfix["姜饼制成的座狼造型点心。"] = "Điểm tâm tạo hình tọa lang làm từ bánh gừng."
    textfix["孢子四散，沾染者恐心神受蚀。"] = "Bào tử tán khắp, người nhiễm phải e tâm thần bị xâm thực."
    textfix["孤阴不生，独阳不长。"] = "Cô âm không sinh, độc dương không lớn."
    textfix["孽畜，找死。"] = "Nghiệt súc, tự tìm chết."
    textfix["孽畜，还不速来拜见本尊！"] = "Nghiệt súc, không mau đến bái kiến bổn tôn!"
    textfix["孽畜，还不速速现形！"] = "Nghiệt súc, không mau hiện hình!"
    textfix["孽障！待王某拆了你这堆废铁！"] = "Nghiệt chướng! Để Vương Mỗ tháo dỡ đống sắt phế này của ngươi!"
    textfix["孽障！竟敢修炼噬魂影术？！"] = "Nghiệt chướng! Dám tu luyện thực hồn ảnh thuật?!"
    textfix["安魂仙音，箫声一起，可使百兽沉眠，妖灵止戈。"] = "Tiên âm an hồn, tiếng sáo vừa nổi, có thể khiến trăm thú ngủ sâu, yêu linh ngừng chiến."
    textfix["完全正常的树根，只是看起来有些诡异。"] = "Rễ cây hoàn toàn bình thường, chỉ là trông có vẻ kỳ quái."
    textfix["完整的姐妹魂体？这种羁绊倒是罕见。"] = "Hồn thể chị em hoàn chỉnh? Sợi dây ràng buộc này lại hiếm thấy."
    textfix["定是有人觊觎本尊藏书。"] = "Chắc chắn có kẻ dòm ngó sách vở của bổn tôn."
    textfix["定海神舵，掌控方向。"] = "Thần đà định hải, kiểm soát phương hướng."
    textfix["定空环，能锚定传送终点，防止坠入虚空。"] = "Định không hoàn, có thể neo đậu điểm đến truyền tống, ngăn chặn rơi vào hư không."
    textfix["定魂法阵，万邪不侵。"] = "Pháp trận định hồn, vạn tà không xâm."
    textfix["宝光内敛，尚需温养。"] = "Bảo quang thu liễm, còn cần ôn dưỡng thêm."
    textfix["宝石发电机的燃料（宝石）即将耗尽。"] = "Nhiên liệu (đá quý) của máy phát điện đá quý sắp cạn."
    textfix["宝石发电机目前处于关闭状态。"] = "Máy phát điện đá quý hiện đang ở trạng thái tắt."
    textfix["宝石发电机被烧毁了。"] = "Máy phát điện đá quý bị thiêu huỷ."
    textfix["宝石发电机起火了。"] = "Máy phát điện đá quý bốc lửa."
    textfix["宝箱焚毁，凶险尽除。"] = "Rương kho bị thiêu, hung hiểm tận trừ."
    textfix["宴席之上，各安其位便好。"] = "Trên tiệc yến, ai ở vị trí của mình là được."
    textfix["宵小之辈，只敢行偷袭之举。"] = "Kẻ tiểu nhân, chỉ dám hành động lén lút."
    textfix["寄居蟹？倒是懂得藏身之道。"] = "Cua ẩn sĩ? Lại biết đạo ẩn thân."
    textfix["寒冰傀儡，寒气逼人。"] = "Quái lỗi hàn băng, hàn khí bức người."
    textfix["寒冰图谱，冷冽逼人。"] = "Đồ phổ hàn băng, lạnh lẽo bức người."
    textfix["寒冰弹丸，蕴含冰系法则。"] = "Đạn hàn băng, hàm chứa pháp tắc băng hệ."
    textfix["寒暑不侵，要此何用？"] = "Hàn thử không xâm, cần vật này làm gì?"
    textfix["寒焰减弱，需添燃料以维持。"] = "Hàn diệm yếu đi, cần thêm nhiên liệu để duy trì."
    textfix["寒焰将熄，需补充燃料。"] = "Hàn diệm sắp tắt, cần bổ sung nhiên liệu."
    textfix["寒焰已彻底熄灭。"] = "Hàn diệm đã hoàn toàn tắt."
    textfix["寒焰稳定，温度适宜。"] = "Hàn diệm ổn định, nhiệt độ thích hợp."
    textfix["寒焰过旺，消耗加剧，需加控制。"] = "Hàn diệm quá mạnh, tiêu hao tăng nhanh, cần kiểm soát thêm."
    textfix["寒瓜注以玄冰之气，乃消暑辟火之小食。"] = "Dưa hấu được tiêm huyền băng chi khí, là món ăn nhẹ giải nhiệt tránh lửa."
    textfix["寒蟾毒涎，奇粘无比，蕴含冰霜与麻痹之毒。"] = "Nước bọt độc cóc hàn, cực kỳ dính, ẩn chứa độc băng sương và tê liệt."
    textfix["对方无暇回应，且等待片刻。"] = "Đối phương không rảnh, hãy đợi chút."
    textfix["寻宝鼠...已无用处，可作药引。"] = "Chuột tìm kho báu... đã không còn dùng được, có thể làm dược dẫn."
    textfix["寻常储物袋，空间尚可。"] = "Túi trữ vật thường, không gian tạm được."
    textfix["寻常工蜂，忙于采集花蜜。"] = "Ong thợ thường, bận rộn thu thập mật hoa."
    textfix["寻常泥土，生机匮乏。"] = "Đất thường, sinh cơ thiếu hụt."
    textfix["寻常碎石，或可铺路。"] = "Đá vụn tầm thường, có thể dùng lát đường."
    textfix["寻常钟乳石，或含些许矿物。"] = "Thạch nhũ thường thường, có thể chứa một ít khoáng vật."
    textfix["寻常鞋拔，无甚特别。"] = "Cái bàn nhíp giày thường, không có gì đặc biệt."
    textfix["寻得宝物，功成身退。"] = "Tìm được bảo vật, công thành thân thoái."
    textfix["寻龙分金铲？可堪一用，然非正道。"] = "Xẻng tìm long phân kim? Cũng có thể dùng được, nhưng không phải chính đạo."
    textfix["封印已解，其本体方现。"] = "Phong ấn đã giải, bản thể mới hiện ra."
    textfix["封印渐消，真容将现。"] = "Phong ấn dần tiêu, chân dung sắp hiện."
    textfix["封禁之术？待我以力破之。"] = "Phong cấm chi thuật? Để ta dùng lực phá."
    textfix["封路巨石，其上似有禁制残留，需以巧劲破之。"] = "Đá tảng chặn đường, trên đó dường như có cấm chế tàn lưu, cần dùng kỹ xảo mà phá."
    textfix["射击游戏套装？练习瞄准。"] = "Bộ trò chơi bắn súng? Luyện tập nhắm mục tiêu."
    textfix["将活蜂封入机关，触之即发，阴损的陷阱。"] = "Nhốt ong sống vào cơ quan, chạm vào là kích hoạt, bẫy âm tổn."
    textfix["将狂暴菌毒封于一处，掷出即爆，阴损。"] = "Phong kín nấm độc cuồng bạo tại một chỗ, ném ra là nổ, âm tổn."
    textfix["小乌鸦？节庆助手。"] = "Quạ nhỏ? Trợ lý lễ hội."
    textfix["小乌鸦？需要引导。"] = "Quạ nhỏ? Cần dẫn dắt."
    textfix["小兽倒有几分灵性。"] = "Tiểu thú lại có mấy phần linh tính."
    textfix["小块兽肉，蕴含微薄气血，可作饵食。"] = "Thịt thú nhỏ, hàm chứa khí huyết vi bạc, có thể dùng làm mồi ăn."
    textfix["小块熟肉，可快速补充体力。"] = "Thịt chín miếng nhỏ, có thể nhanh chóng bổ sung thể lực."
    textfix["小型水晶池？也有灵气。"] = "Ao tinh thể nhỏ? Cũng có linh khí."
    textfix["小妖怪...可愿做王某的御用灵宠？"] = "Yêu quái nhỏ... có muốn làm linh thú ngự dụng của Vương Mỗ không?"
    textfix["小妖躲藏，待我寻之。"] = "Tiểu yêu ẩn nấp, chờ ta tìm kiếm."
    textfix["小小魔头，也敢在王某面前放肆！"] = "Ma đầu nhỏ bé, cũng dám phóng túng trước mặt Vương Mỗ!"
    textfix["小巧的秤具，可称量药材。"] = "Dụng cụ cân nhỏ gọn, có thể cân dược liệu."
    textfix["小巧风符器，奔走时可生微风，仅能解片刻之暑。"] = "Phong phù khí nhỏ xinh, khi chạy có thể sinh gió nhỏ, chỉ có thể giải nóng trong chốc lát."
    textfix["小幽灵？无害之物。"] = "Ma nhỏ? Vật vô hại."
    textfix["小恩小惠，只为稳住此獠。"] = "Ân huệ nhỏ nhoi, chỉ để vỗ về tên này."
    textfix["小浣猫雕像，形态稚拙可爱。"] = "Tượng đá mèo gấu trúc nhỏ, hình thái non nớt đáng yêu."
    textfix["小海象，会跟随它的父亲。"] = "Hải mã nhỏ, sẽ đi theo cha của nó."
    textfix["小猪造型的巧克力，味道香醇。"] = "Socola tạo hình lợn nhỏ, hương vị thơm nồng."
    textfix["小船灯笼，能为夜间航行提供照明。"] = "Đèn lồng thuyền nhỏ, có thể cung cấp chiếu sáng cho hành trình ban đêm."
    textfix["小辈！你的故事里藏着多少杀孽？"] = "Hậu bối! Trong câu chuyện của ngươi ẩn chứa bao nhiêu sát nghiệt?"
    textfix["小龙蝇，虽小却已显露出火系特征。"] = "Rồng ruồi nhỏ, tuy nhỏ nhưng đã lộ ra đặc trưng hỏa hệ."
    textfix["尘沫甜点？味道奇特。"] = "Món ngọt bụi bọt? Hương vị kỳ lạ."
    textfix["尘蛾巢穴？异常整洁。"] = "Hang bướm bụi? Sạch sẽ dị thường."
    textfix["尘蛾？喜食灰尘。"] = "Bướm bụi? Thích ăn bụi."
    textfix["局未终了，静候即可。"] = "Ván chưa kết thúc, cứ yên tĩnh chờ đợi."
    textfix["屋内妖气收敛，猪妖已歇息，勿要惊扰。"] = "Trong nhà yêu khí thu liễm, heo yêu đã nghỉ ngơi, chớ quấy rầy."
    textfix["属性相克，不可妄用。"] = "Thuộc tính tương khắc, không thể tùy tiện sử dụng."
    textfix["岩浆吹箭，能造成持续的燃烧伤害。"] = "Tên thổi nham thạch, có thể gây thương thương đốt cháy liên tục."
    textfix["岩浆池，极端高温，靠近会引火烧身。"] = "Hồ dung nham, nhiệt độ cực cao, đến gần sẽ bị lửa thiêu."
    textfix["岩浆虫似乎有些饿了。"] = "Sâu dung nham dường như hơi đói."
    textfix["岩浆虫的牙齿，坚硬且带有余温。"] = "Răng của sâu dung nham, cứng và mang theo nhiệt độ dư."
    textfix["岩浆虫目前状态满足。"] = "Sâu dung nham hiện tại trạng thái thỏa mãn."
    textfix["岩浆虫，由龙蝇所产，周身环绕高温。"] = "Sâu dung nham, do rồng ruồi đẻ ra, toàn thân vây quanh nhiệt độ cao."
    textfix["岩石巢穴，似乎能孕育出奇特的小型生物。"] = "Tổ đá, dường như có thể ươm ra sinh vật nhỏ kỳ đặc."
    textfix["岩石灵猫，攀爬高手。"] = "Linh miêu đá, cao thủ leo trèo."
    textfix["巢中已空，灵鹳蛋已被取走。"] = "Tổ đã trống, trứng linh hạc đã bị lấy đi."
    textfix["巢穴已焚，妖兔或已遁走。"] = "Tổ đã thiêu, thỏ yêu có thể đã trốn."
    textfix["巢穴已空，毫无收获。"] = "Tổ đã trống, chẳng thu hoạch được gì."
    textfix["巢穴焚毁，妖物四散。"] = "Sào huyệt bị thiêu, yêu vật tứ tán."
    textfix["巧克力树根蛋糕，造型逼真，是节日的甜点。"] = "Bánh gốc cây socola, tạo hình chân thực, là món ngọt ngày lễ."
    textfix["巨兽之眼，已失其主。"] = "Nhãn của cự thú, đã mất chủ nhân."
    textfix["巨型作物腐烂。"] = "Cây trồng khổng lồ thối rữa."
    textfix["巨型南瓜？可作容器。"] = "Bí ngô khổng lồ? Có thể làm vật đựng."
    textfix["巨型土豆？淀粉丰富。"] = "Khoai tây khổng lồ? Tinh bột phong phú."
    textfix["巨型大蒜？驱虫效果好。"] = "Tỏi khổng lồ? Hiệu quả đuổi trùng tốt."
    textfix["巨型榴莲？气味浓烈。"] = "Sầu riêng khổng lồ? Mùi nồng nặc."
    textfix["巨型洋葱？辛辣刺眼。"] = "Hành tây khổng lồ? Cay nồng cay mắt."
    textfix["巨型火龙果？外形奇特。"] = "Thanh long khổng lồ? Ngoại hình kỳ lạ."
    textfix["巨型玉米？个头惊人。"] = "Bắp ngô khổng lồ? Kích thước kinh người."
    textfix["巨型番茄？红色饱满。"] = "Cà chua khổng lồ? Đỏ căng đầy."
    textfix["巨型石榴？籽粒饱满。"] = "Lựu khổng lồ? Hạt căng đầy."
    textfix["巨型胡萝卜？长得异常。"] = "Cà rốt khổng lồ? Lớn dị thường."
    textfix["巨型芦笋？清脆可口。"] = "Măng tây khổng lồ? Giòn ngon."
    textfix["巨型茄子？紫色品种。"] = "Cà tím khổng lồ? Giống màu tím."
    textfix["巨型西瓜？水分充足。"] = "Dưa hấu khổng lồ? Nước đủ đầy."
    textfix["巨型辣椒？辣度更强。"] = "Ớt khổng lồ? Độ cay mạnh hơn."
    textfix["巨石悬于穹顶，禁制完整，不可力敌。"] = "Đá tảng treo trên vòm, cấm chế hoàn chỉnh, không thể đối địch bằng sức."
    textfix["巨鹿的眼球，仍残留着强大的冰寒之力。"] = "Mắt của nai khổng lồ, vẫn còn sót lại sức mạnh băng hàn mạnh mẽ."
    textfix["已无毛可刮，不必白费功夫。"] = "Không còn lông để cạo, không cần tốn công vô ích."
    textfix["已有他人就坐。"] = "Đã có người khác ngồi."
    textfix["已有少许蜂蜜，尚未满箱。"] = "Đã có ít mật ong, chưa đầy tổ."
    textfix["已有灵兽相伴，不必再多。"] = "Đã có linh thú bên cạnh, không cần thêm nữa."
    textfix["布偶之形，徒具其表。"] = "Hình thức bố ngẫu, chỉ có bề ngoài."
    textfix["布偶傀儡，难成大器。"] = "Quái lỗi bố ngẫu, khó thành đại khí."
    textfix["布偶图谱，过于柔弱。"] = "Đồ phổ bố ngẫu, quá mềm yếu."
    textfix["布网已毕，静待收获。"] = "Giăng lưới đã xong, tĩnh chờ thu hoạch."
    textfix["帐毁心难静，需另寻他处调息。"] = "Trướng bị phá tâm khó tĩnh, cần tìm nơi khác để điều tức."
    textfix["帝王蟹雕像，甲壳峥嵘，颇具威势。"] = "Tượng đá cua vua, vỏ giáp sừng sừng, khá uy thế."
    textfix["带电的羊奶，饮用它可能会受到电击。"] = "Sữa cừu có điện, uống nó có thể bị điện giật."
    textfix["常春藤？攀附植物。"] = "Cây thường xuân? Thực vật leo."
    textfix["常青树已被烧毁。"] = "Cây thường xanh đã bị thiêu hủy."
    textfix["常青树已被砍伐。"] = "Cây thường xanh đã bị chặt phá."
    textfix["常青树正在燃烧。"] = "Cây thường xanh đang cháy."
    textfix["干枯的猴爪，散发着不祥的诅咒气息。"] = "Móng vuốt khỉ khô héo, tỏa ra khí tức nguyền rủa bất tường."
    textfix["年轻的座狼，虽未长成，但已显凶性。"] = "Tọa lang trẻ tuổi, tuy chưa trưởng thành, nhưng đã hiển lộ hung tính."
    textfix["幻境舞台，暗藏杀机。"] = "Sân khấu ảo cảnh, ẩn sát cơ."
    textfix["幻梦琉璃灯构件..."] = "Cấu kiện đèn lưu ly huyễn mộng..."
    textfix["幻象将散，如同梦道轮回。"] = "Huyễn tượng sắp tan, như là mộng đạo luân hồi."
    textfix["幼兽灵性未足，懵懂无知。"] = "Thú non linh tính chưa đủ, ngây thơ vô tri."
    textfix["幼兽酣眠，不宜惊扰。"] = "Thú non đang ngủ say, không nên làm kinh động."
    textfix["幼虫？乌鸦食物。"] = "Ấu trùng? Thức ăn của quạ."
    textfix["幼雀饥火攻心，再不得食恐伤其根基。"] = "Ấu tước đói lửa công tâm, không được ăn nữa e sẽ tổn thương căn cơ."
    textfix["幼鹳元气大伤，若再不得食恐有性命之虞。"] = "Hạc non nguyên khí tổn thương nặng, nếu không được ăn nữa e có lo sợ về tính mệnh."
    textfix["幼鹳沉睡，正于梦中锤炼妖骨。"] = "Hạc non chìm vào giấc ngủ, đang trong giấc mơ tôi luyện yêu cốt."
    textfix["幼鹳饥鸣，需喂食以助其成长。"] = "Hạc non kêu đói, cần cho ăn để giúp nó trưởng thành."
    textfix["幽冥之力，隐而未发。"] = "Lực u minh, ẩn mà chưa phát."
    textfix["幽冥之地，且去一探。"] = "Đất u minh, cứ đi thám hiểm một chút."
    textfix["幽冥之花，也配近本尊法身？"] = "Hoa u minh, cũng đáng gần pháp thân của bổn tôn?"
    textfix["幽冥伞，可挡酸雨。"] = "Ô u minh, có thể chắn mưa axit."
    textfix["幽冥战甲残图，可炼阴兵。"] = "Tàn đồ chiến giáp u minh, có thể luyện âm binh."
    textfix["幽冥无光，难辨虚实。"] = "U minh không sáng, khó phân hư thực."
    textfix["幽冥棘丛，暗藏毒刺，触之则损精元。"] = "Gai tùng u minh, ẩn chứa gai độc, chạm vào sẽ tổn thương tinh nguyên."
    textfix["幽冥炉组件，需谨慎处理。"] = "Cấu kiện lò u minh, cần thận trọng xử lý."
    textfix["幽冥爆裂，毁天灭地。"] = "U minh bùng nổ, hủy thiên diệt địa."
    textfix["幽冥玄甲，轻如鸿毛，坚如磐石。"] = "Huyền giáp u minh, nhẹ như lông hồng, cứng như bàn thạch."
    textfix["幽冥玄石，可吸光华。"] = "Huyền thạch u minh, có thể hút quang hoa."
    textfix["幽冥玄石，自深渊来。"] = "Huyền thạch u minh, từ thâm uyên đến."
    textfix["幽冥紫晶，蕴含虚空之力，是构筑传送阵法的核心。"] = "Tử tinh u minh, ẩn chứa hư không chi lực, là cốt lõi để xây dựng trận pháp truyền tống."
    textfix["幽冥裂隙，阴气森森。"] = "Liệt khích u minh, âm khí rợn rùng."
    textfix["幽冥鬼手，所求必凶。"] = "Ma thủ u minh, những gì cầu tất hung."
    textfix["幽森之音，煞气逼人。"] = "Âm thanh u rừng, sát khí bức người."
    textfix["幽灵形状的棒棒糖，是节日的应景零食。"] = "Kẹo que hình ma, là đồ ăn vặt ứng cảnh ngày lễ."
    textfix["幽灵形状的节日装饰。"] = "Đồ trang trí ngày lễ hình ma."
    textfix["幽灵花？蕴含阴灵气。"] = "Hoa ma? Hàm chứa âm linh khí."
    textfix["幽灵，没有实体，需要用特定方式安抚或驱散。"] = "Bóng ma, không có thực thể, cần dùng cách đặc định để xoa dịu hoặc xua tan."
    textfix["庆典傀儡，热闹有余。"] = "Quái lỗi kỷ niệm, ồn ào có thừa."
    textfix["庆典图谱，华美有余。"] = "Đồ phổ kỷ niệm, hoa mỹ có thừa."
    textfix["庆典礼炮？可发祥瑞。"] = "Lễ pháo kỷ niệm? Có thể phát tường vân."
    textfix["废弃机关，或可再利用。"] = "Cơ quan bỏ đi, hoặc có thể tái sử dụng."
    textfix["座狼幼崽，已有猎食者的眼神。"] = "Chó sói bờm non, đã có ánh mắt của kẻ săn mồi."
    textfix["座狼祭坛，供奉着狼形图腾。"] = "Tế đàn tọa lang, thờ phụng đồ án hình lang."
    textfix["座狼，一种凶猛的大型犬科动物，常成群出没。"] = "Tọa lang, một loài chó lớn hung dữ, thường xuất hiện thành đàn."
    textfix["开启克劳斯礼物袋所需的鹿角钥匙。"] = "Chìa khoá gạc hươu cần để mở túi quà Klaus."
    textfix["开山镐，采掘灵石矿脉的必备工具。"] = "Cuốc khai sơn, công cụ thiết yếu để khai thác linh thạch khoáng mạch."
    textfix["异变熊獾，恐生事端。"] = "Lửng gấu dị biến, e sẽ sinh chuyện."
    textfix["异域傀儡，风格独特。"] = "Quái lỗi ngoại quốc, phong cách độc đáo."
    textfix["异域音律，别有风味。"] = "Âm luật ngoại quốc, hương vị riêng biệt."
    textfix["异种灵木，似松非松。"] = "Linh mộc dị chủng, giống thông mà không phải thông."
    textfix["异象频生，恐有变故。 "] = "Dị tượng liên tiếp xuất hiện, e có biến cố."
    textfix["引动太阴之力，此杖不凡。"] = "Dẫn động thái âm chi lực, chiếc gậy này phi thường."
    textfix["引航罗盘，可指方位。"] = "La bàn dẫn hàng, có thể chỉ phương vị."
    textfix["弯曲的银叉，或是某种仪式的法器。"] = "Cái nĩa bạc bị uốn cong, hoặc là pháp khí của nghi lễ nào đó."
    textfix["弹弓？倒是件奇门法宝。"] = "Súng cao su? Lại là pháp bảo kỳ môn."
    textfix["弹药就位，随时可发。"] = "Đạn dược đã vào vị trí, bất cứ lúc nào có thể phóng."
    textfix["弹药已尽，需速补充。"] = "Đạn dược đã hết, cần bổ sung ngay."
    textfix["强光信号弹，能照亮更大范围，但也会吸引注意。"] = "Pháo hiệu cường quang, có thể chiếu sáng phạm vi rộng hơn, nhưng cũng sẽ thu hút chú ý."
    textfix["强化熔岩吹箭，威力更为强大。"] = "Tên thổi nham thạch cường hóa, uy lực mạnh mẽ hơn."
    textfix["强心剂，可以临时提升生命力的上限。"] = "Thuốc cường tâm, có thể tạm thời nâng cao giới hạn máu."
    textfix["强敌当前，需谨慎应对。"] = "Kẻ địch mạnh, cần cẩn thận ứng phó."
    textfix["强行拘束星核之力，稍有不慎便会反噬。"] = "Cưỡng bức ràng buộc tinh hạch chi lực, chỉ cần sơ ý là bị phản phệ."
    textfix["形似兔，性却凶戾，非善类。"] = "Hình như thỏ, tính lại hung dữ, không phải loại thiện."
    textfix["形骸有误，魂难附体。"] = "Hình hài có lỗi, hồn khó nhập thể."
    textfix["待你事了，再议不迟。"] = "Đợi ngươi xong việc, bàn sau cũng chưa muộn."
    textfix["待你成熟，便是你价值所在。"] = "Đợi ngươi chín, đó là giá trị của ngươi."
    textfix["待其心服，再召不迟。"] = "Đợi nó tâm phục rồi triệu cũng chưa muộn."
    textfix["待其沉睡再动手不迟。"] = "Đợi nó ngủ rồi ra tay cũng chưa muộn."
    textfix["待平息此事，再寻它算账。"] = "Đợi bình định xong, rồi tính sổ với nó."
    textfix["待我...调息...片刻..."] = "Đợi ta... điều tức... chút đã..."
    textfix["待我下了坐骑再行事。"] = "Đợi ta xuống lưng kỳ thú đã."
    textfix["待我抽空处置。"] = "Chờ ta rảnh rỗi xử lý."
    textfix["待本尊收了这花中怨魂。"] = "Để bổn tôn thu phục oán hồn trong hoa này."
    textfix["待本尊祭出噬魂幡再战。"] = "Đợi bổn tôn tế xuất Thực Hồn Phan rồi chiến."
    textfix["待燃香火，方现真容。"] = "Chờ đốt hương lửa, mới hiện chân dung."
    textfix["待王某为你重聚魂魄...说说你的研究"] = "Để Vương Mỗ giúp ngươi tụ lại hồn phách... hãy nói về nghiên cứu của ngươi."
    textfix["待王某将你炼成一鼎血肉大药！"] = "Để Vương Mỗ luyện ngươi thành một đỉnh đại dược bằng huyết nhục!"
    textfix["待王某收了这地行妖作寻宝灵宠。"] = "Để Vương Mỗ thu phục địa hành yêu này làm linh thú tìm kho báu."
    textfix["待王某注入灵力激活..."] = "Để Vương Mỗ rót linh lực kích hoạt..."
    textfix["待王某运功烘干..."] = "Để Vương Mỗ vận công sấy khô..."
    textfix["待王某雕个石儡看守洞府。"] = "Đợi Vương Mỗ chạm khắc một quái lỗi đá để trấn thủ động phủ."
    textfix["徒具其形，未得其神。"] = "Chỉ có hình, chưa đạt được thần."
    textfix["御兽铃，可通灵兽心意。"] = "Linh ngự thú, có thể thông tâm ý linh thú."
    textfix["御兽鞍，刻有简易驯兽符文，可助骑乘。"] = "Ngự thú an, khắc có phù văn thuần thú đơn giản, có thể giúp cưỡi."
    textfix["御火音律，还算实用。"] = "Âm luật ngự hỏa, còn tạm thực dụng."
    textfix["御虫哨？控制妖兽的法器。"] = "Tiêu ngự trùng? Pháp khí kiểm soát yêu thú."
    textfix["心神微震，是何物扰我清静？"] = "Tâm thần khẽ rung, vật gì quấy rầy sự thanh tĩnh của ta?"
    textfix["心若冰清，何惧妖邪。"] = "Tâm như băng thanh, ngại gì yêu tà."
    textfix["快速疗伤药，尚可。"] = "Thuốc trị thương nhanh, tạm được."
    textfix["急于邀功，可笑至极。"] = "Hấp tấp lập công, đáng cười cực độ."
    textfix["怨气在凝聚，这灵体在变强。"] = "Oán khí đang ngưng tụ, linh thể này đang mạnh hơn."
    textfix["怨气缠身，沾染不祥。"] = "Oán khí quấn thân, vướng vào bất tường."
    textfix["怨灵现形，当以雷法镇之。"] = "Oán linh hiện hình, nên dùng lôi pháp trấn áp."
    textfix["怨煞精华，炼器上品。"] = "Tinh hoa oán sát, thượng phẩm luyện khí."
    textfix["恐怖之眼雕像，凝视之深感不适。"] = "Tượng đá mắt kinh hoàng, nhìn vào thấy rất bất an."
    textfix["恐怖猎犬正在睡觉。"] = "Liệp khuyển khủng khiếp đang ngủ."
    textfix["恐怖猎犬死了。"] = "Liệp khuyển khủng khiếp chết rồi."
    textfix["恐怖猎犬，一种被月岛能量扭曲的变异生物。"] = "Liệp khuyển khủng khiếp, một loại sinh vật biến dị bị năng lượng đảo nguyệt xuyên tạc."
    textfix["恐怖魔眼，邪气凛然。"] = "Ma nhãn khủng khiếp, tà khí lẫm nhiên."
    textfix["恶魔花，靠近会侵蚀理智。"] = "Hoa ác ma, đến gần sẽ xâm thực lý trí."
    textfix["悟道石被毁，道韵尽失。"] = "Ngộ đạo thạch bị phá huỷ, đạo vận tận mất."
    textfix["悟道石，触摸其上符文可启迪心智，解锁炼制法门。"] = "Ngộ đạo thạch, chạm vào phù văn trên đó có thể khai mở tâm trí, mở khoá pháp môn luyện chế."
    textfix["悬蛛形状的节日装饰。"] = "Đồ trang trí ngày lễ hình nhện hang."
    textfix["惑心之术，也敢班门弄斧？"] = "Thuật mê hoặc tâm, cũng dám múa rìu qua mắt thợ?"
    textfix["意大利圣诞面包，果干丰富。"] = "Bánh mì Giáng sinh Ý, trái khô phong phú."
    textfix["愚者戏服，暗藏玄机。"] = "Trang phục kẻ ngu, ẩn huyền cơ."
    textfix["愚者面具，大智若愚。"] = "Mặt nạ kẻ ngu, đại trí nhược ngu."
    textfix["戏台傀儡手？其上附有操控咒法，会阻碍前行。"] = "Quái lỗi tay sân khấu? Trên đó gắn có chú pháp thao túng, sẽ cản trở tiền hành."
    textfix["戏文剧本，操纵人心。"] = "Kịch bản kịch văn, thao túng lòng người."
    textfix["成熟的沙拉蝾螈，散发着果香。"] = "Kỳ nhông salad chín, tỏa ra hương trái cây."
    textfix["成熟的石果，外壳已经软化。"] = "Thạch quả chín, vỏ ngoài đã mềm đi."
    textfix["我的胡萝卜鼠赢得了比赛。"] = "Chuột cà rốt của ta đã thắng cuộc đua."
    textfix["我辈修士，何惧劳顿。"] = "Tu sĩ chúng ta, sao lại sợ lao nhọc."
    textfix["战偶傀儡，杀气不足。"] = "Quái lỗi chiến ngẫu, sát khí không đủ."
    textfix["战意傀儡，尚缺灵性。"] = "Quái lỗi chiến ý, vẫn thiếu linh tính."
    textfix["战意升腾，锋芒毕露。"] = "Chiến ý dâng trào, phong mang lộ hết."
    textfix["战意正酣，此时上鞍非明智之举。"] = "Chiến ý đang nồng, lúc này lên yên không phải quyết định sáng suốt."
    textfix["战意音律，略有助益。"] = "Âm luật chiến ý, có chút trợ ích."
    textfix["战猪，冲锋时势不可挡。"] = "Chiến trư, khi xung phong thế không thể cản."
    textfix["战甲图谱，杀气凛然。"] = "Đồ phổ chiến giáp, sát khí lẫm nhiên."
    textfix["战车雕像，造型稳重。"] = "Tượng đá chiến xa, tạo hình ổn trọng."
    textfix["战阵金钟，静待敲响。"] = "Kim chung trận chiến, tĩnh chờ gõ vang."
    textfix["战魂不灭...正好炼为护法战傀！"] = "Chiến hồn bất diệt... vừa hay luyện thành hộ pháp chiến bù nhìn!"
    textfix["戾气凝于干肉，虽经风干，凶险未减分毫。"] = "Lệ khí ngưng tụ trong thịt khô, dù đã phơi gió, nguy hiểm không giảm một chút."
    textfix["扁毛畜生，安敢欺近！"] = "Con vật lông bẹt, dám đến gần!"
    textfix["扇中风灵之力已竭。"] = "Sức mạnh phong linh trong quạt đã cạn kiệt."
    textfix["手中抓着一只海鹦鹉。"] = "Tay cầm một con vẹt biển."
    textfix["手中抓着一只胡萝卜鼠。"] = "Tay cầm một con chuột cà rốt."
    textfix["手中握着一只月蛾。"] = "Tay cầm một con nguyệt nga."
    textfix["手中无枕，如何参与？"] = "Tay không có gối, sao có thể tham gia?"
    textfix["手持杀人蜂，需格外小心。"] = "Cầm ong sát thủ trên tay, cần hết sức cẩn thận."
    textfix["手持金丝雀，需小心对待。"] = "Cầm chim hoàng yến trên tay, cần cẩn thận đối đãi."
    textfix["手滑了，此物竟脱手而出。"] = "Tay trượt, vật này thực sự rơi mất."
    textfix["打坐修行，何需帐篷。"] = "Ngồi thiền tu hành, cần gì lều."
    textfix["投石机目前处于关闭状态。"] = "Máy bắn đá hiện đang ở trạng thái tắt."
    textfix["投石机被烧毁了。"] = "Máy bắn đá bị thiêu huỷ."
    textfix["投石机起火了。"] = "Máy bắn đá bốc lửa."
    textfix["护体法阵，可增气血。"] = "Pháp trận hộ thể, có thể tăng khí huyết."
    textfix["护体灵光？尚欠火候。"] = "Linh quang hộ thể? Vẫn còn thiếu lửa luyện."
    textfix["护体灵药，保命之用。"] = "Linh dược hộ thể, dùng bảo mệnh."
    textfix["护体罡气，已然散去。"] = "Cương khí hộ thể, đã tản đi."
    textfix["护目镜，可保护眼睛免受风沙强光刺激。"] = "Kính bảo hộ, có thể bảo vệ mắt tránh gió cát và ánh sáng mạnh."
    textfix["报废的灵纹导线，其上符文已失效。"] = "Dây dẫn linh văn phế bỏ, phù văn trên đó đã thất hiệu."
    textfix["报春灵雀，其鸣可驱散冬日沉寂。"] = "Báo xuân linh tước, tiếng kêu của nó có thể xua tan sự im lặng ngày đông."
    textfix["抽魂法器，玄妙非常。"] = "Pháp khí trích hồn, huyền diệu phi thường."
    textfix["拐杖糖，红白条纹相间，是节日的象征之一。"] = "Kẹo cây gậy, sọc đỏ trắng xen kẽ, là một trong những biểu tượng ngày lễ."
    textfix["招财猫雕像，据说能带来些许财运。"] = "Tượng mèo chiêu tài, nghe nói có thể mang lại chút vận may tài lộc."
    textfix["持剑武士像，姿态威严，可作装饰。"] = "Tượng võ sĩ cầm kiếm, tư thái uy nghiêm, có thể làm trang trí."
    textfix["持桨战猴，可笑可叹。"] = "Chiến hầu cầm mái chèo, đáng cười đáng than."
    textfix["挑战手套，用于向兔人发起枕头大战的邀请。"] = "Găng tay thách đấu, dùng để mời người thỏ bắt đầu cuộc chiến gối."
    textfix["挑衅音律，低劣手段。"] = "Âm luật khiêu khích, thủ đoạn thấp kém."
    textfix["挖出的小树苗，需要找地方种下。"] = "Cây con được đào lên, cần tìm chỗ trồng xuống."
    textfix["挖出的尖刺灌木，需小心处理。"] = "Bụi gai được đào lên, cần cẩn thận xử lý."
    textfix["挖空的废物！"] = "Đồ phế vật bị đào rỗng!"
    textfix["挡本尊者，死。"] = "Kẻ cản bổn tôn, chết."
    textfix["捕虫网，可捕捉飞行昆虫，而不伤其性命。"] = "Lưới bắt sâu, có thể bắt côn trùng bay mà không hại tính mạng."
    textfix["捕鸟陷阱，以丝线机关困缚飞禽。"] = "Bẫy bắt chim, dùng cơ quan tơ dây trói buộc chim bay."
    textfix["损坏的发条零件，或许能回收些材料。"] = "Linh kiện lên dây cót hỏng, có thể thu hồi chút nguyên liệu."
    textfix["损坏的搅拌法器，其内灵阵已破损。"] = "Pháp khí khuấy trộn bị hỏng, linh trận bên trong đã phá hỏng."
    textfix["损坏的鼓风法器，已无法产生气流。"] = "Pháp khí thổi gió bị hỏng, đã không thể tạo ra khí lưu."
    textfix["据说能给人带来勇气的药水。"] = "Thuốc nghe nói có thể mang lại can đảm cho người."
    textfix["掘地三尺，正好找寻炼器材料"] = "Đào đất ba thước, đúng lúc tìm kiếm vật liệu luyện khí."
    textfix["探查万物，解析天机。"] = "Thăm dò vạn vật, giải tích thiên cơ."
    textfix["探测仪器，或有用处。"] = "Dụng cụ thăm dò, hoặc có ích."
    textfix["探测杖传来微弱感应，方向正确。"] = "Gậy thăm dò truyền đến cảm ứng yếu ớt, hướng đúng."
    textfix["探测杖反应剧烈，目标近在咫尺。"] = "Gậy thăm dò phản ứng mạnh mẽ, mục tiêu ngay trước mắt."
    textfix["探测杖感应强烈，已非常接近目标。"] = "Gậy thăm dò cảm ứng mạnh mẽ, đã rất gần mục tiêu."
    textfix["探测杖毫无反应，目标尚远。"] = "Gậy thăm dò không có phản ứng gì, mục tiêu còn xa."
    textfix["探测杖，能感应并指引方向。"] = "Gậy thăm dò, có thể cảm ứng và chỉ dẫn phương hướng."
    textfix["提速灵药，逃遁有用。"] = "Linh dược tăng tốc, hữu dụng khi trốn chạy."
    textfix["摇摆木马玩具，孩童的玩物。"] = "Đồ chơi ngựa gỗ lắc, đồ chơi của trẻ em."
    textfix["撕裂虚空，需积蓄力量。"] = "Xé rách hư không, cần tích tụ lực lượng."
    textfix["撼地战鞍，符文闪耀，可激发坐骑战意，冲锋陷阵。"] = "Hám Địa chiến an, phù văn sáng chói, có thể kích phát chiến ý của tọa kỵ, xung phong hãm trận."
    textfix["擅于伪装，伏于暗处，阴险。"] = "Giỏi ngụy trang, ẩn nấp trong bóng tối, âm hiểm."
    textfix["擎天水木，支撑天地。"] = "Thủy mộc kình thiên, chống đỡ thiên địa."
    textfix["改良剂已变质。"] = "Chất cải tạo đã biến chất."
    textfix["改良剂效果减弱。"] = "Hiệu quả chất cải tạo giảm yếu."
    textfix["效果强劲的万灵药水。"] = "Thuốc vạn linh hiệu quả mạnh mẽ."
    textfix["效果微弱的万灵药水。"] = "Thuốc vạn linh hiệu quả vi nhược."
    textfix["散发异味的装置，内藏腐毒之气。"] = "Thiết bị tỏa mùi lạ, bên trong ẩn tàng hủ độc chi khí."
    textfix["数量不足，游戏无法进行。"] = "Số lượng không đủ, trò chơi không thể tiến hành."
    textfix["斑纹妖鱼，中看不中用。"] = "Yêu ngư sọc vằn, trông đẹp mà không dùng được."
    textfix["斗雨笠，编织时掺入避水灵丝。"] = "Nón đấu mưa, khi đan có thêm linh tơ tị thủy."
    textfix["断角海兽？废物一个！"] = "Hải thú gãy sừng? Đồ phế vật!"
    textfix["断角还跟着？自取其辱！"] = "Gãy sừng còn theo? Tự mình chịu nhục!"
    textfix["新不新不重要，能炼器就行。"] = "Mới hay cũ không quan trọng, miễn luyện được khí là được."
    textfix["方位不定..."] = "Phương vị không xác định..."
    textfix["方向有误，速速回头。"] = "Hướng đi sai rồi, nhanh quay đầu lại."
    textfix["方向训练设施被烧毁了。"] = "Cơ sở huấn luyện phương hướng bị thiêu huỷ."
    textfix["无主哨塔，或可利用。"] = "Tháp canh vô chủ, hoặc có thể lợi dụng."
    textfix["无图可临，如何下笔？"] = "Không có hình để vẽ, sao có thể cầm bút?"
    textfix["无头竖琴雕像，造型诡异，似有未散执念。"] = "Thạch tượng đàn hạc không đầu, tạo hình quái dị, dường như có chấp niệm chưa tan."
    textfix["无法抵御高温，已然枯萎。"] = "Không thể chịu được nhiệt độ cao, đã khô héo."
    textfix["无眼鹿的角似乎快要脱落了。"] = "Sừng của nai không mắt dường như sắp rụng."
    textfix["无眼鹿，虽无目却能感知周围，颇为奇特。"] = "Nai không mắt, tuy không có mắt nhưng có thể cảm nhận xung quanh, khá kỳ đặc."
    textfix["无花之果，暗结灵实。"] = "Quả không hoa, ngầm kết linh thực."
    textfix["无魂之物也配化鬼？可笑！"] = "Vật không hồn cũng đáng hóa quỷ? Buồn cười!"
    textfix["既无胆魄，何谈机缘。"] = "Đã không có can đảm, nói gì đến cơ duyên."
    textfix["既是入定，不便叨扰。"] = "Đã nhập định rồi, không tiện làm phiền."
    textfix["既知逃无可逃，还算识相。"] = "Đã biết trốn không thoát, còn biết điều."
    textfix["日出亮片？骗骗凡鱼罢了！"] = "Lame bình minh? Chỉ để lừa cá phàm mà thôi!"
    textfix["日出假饵？连小鱼都骗不过！"] = "Mồi giả bình minh? Ngay cả cá nhỏ cũng lừa không qua!"
    textfix["时之魂魄...正是炼制时空法器的至宝！"] = "Hồn phách của thời gian... chính là chí bảo để luyện thời không pháp khí!"
    textfix["时修！你可知扰乱因果要承受何等天劫？"] = "Thời tu! Ngươi có biết quấy rầy nhân quả phải chịu thiên kiếp như thế nào không?"
    textfix["时机已至，当可采摘。"] = "Thời cơ đã đến, có thể hái rồi."
    textfix["时机已过，强求无益。"] = "Thời cơ đã qua, cưỡng cầu vô ích."
    textfix["时机未到，还需准备。"] = "Thời cơ chưa đến, cần chuẩn bị thêm."
    textfix["时机未至，强求无益。"] = "Thời cơ chưa đến, cưỡng cầu vô ích."
    textfix["时机稍纵，下次再试。"] = "Thời cơ vừa qua, lần sau thử lại."
    textfix["时空倒流仪，玄奥非常。"] = "Thiết bị thời không đảo lưu, huyền áo phi thường."
    textfix["时空裂缝，通往未知之境。"] = "Liệt phùng thời không, dẫn đến cõi chưa biết."
    textfix["时空裂隙仪，可穿梭位面。"] = "Thiết bị liệt khích thời không, có thể xuyên thoi vị diện."
    textfix["时空隧道出口，重返现世。"] = "Cửa ra đường hầm thời không, trở lại thế giới hiện tại."
    textfix["时轮拆解器，专破时空禁制。"] = "Dụng cụ tháo dỡ thời luân, chuyên phá cấm chế thời không."
    textfix["时辰丧钟，敲响必见血光。"] = "Đại hồng chung giờ tử, gõ lên tất thấy huyết quang."
    textfix["时辰将尽……莫非想遁入虚空？"] = "Thời khắc sắp hết... hay muốn trốn vào hư không?"
    textfix["时辰已过，明日请早。"] = "Thời khắc đã qua, ngày mai hãy đến sớm."
    textfix["时间碎片，蕴含时空法则。"] = "Mảnh vỡ thời gian, hàm chứa pháp tắc thời không."
    textfix["时限将至，速速现身。"] = "Thời hạn sắp đến, mau mau hiện thân."
    textfix["明灯失辉，暗淡无光。"] = "Đèn sáng mất huy, tối tăm vô quang."
    textfix["昔日巍峨，今成废墟。"] = "Xưa kia hiên ngang, nay thành phế tích."
    textfix["星冠碎片，光华流转。"] = "Mảnh tinh quan, quang hoa lưu chuyển."
    textfix["星妖伏诛，天地清明。"] = "Yêu sao bị phục chú, thiên địa thanh minh."
    textfix["星妖狂怒，正合我意。"] = "Yêu sao cuồng nộ, đúng ý ta."
    textfix["星核残骸，尚存余温。"] = "Tàn tích hạch tâm sao, vẫn còn dư ôn."
    textfix["星核破碎，灵气四散。"] = "Hạch tâm sao vỡ vụn, linh khí tứ tán."
    textfix["星象仪已定位。"] = "Tinh tượng nghi đã định vị."
    textfix["星象仪？可探测方位。"] = "Tinh tượng nghi? Có thể thăm dò phương vị."
    textfix["星象护目，可窥天机。"] = "Kính hộ mục tinh tượng, có thể nhòm thiên cơ."
    textfix["星辉冠冕，可聚星辰之力。"] = "Vương miện tinh huy, có thể tụ lực sao."
    textfix["星辰之力，充盈其中。"] = "Lực sao, đầy ắp trong đó."
    textfix["星辰雷煞，威力惊人。"] = "Lôi sát tinh thần, uy lực kinh người."
    textfix["星陨石妖，也敢挡我去路！"] = "Yêu thiên thạch sao, cũng dám chặn đường ta!"
    textfix["春回大地，兔妖洞府生机勃发。"] = "Xuân về mặt đất, động phủ thỏ yêu sinh cơ bừng dậy."
    textfix["是该离开了。"] = "Đến lúc rời đi rồi."
    textfix["是这个蛋篮吗？"] = "Có phải giỏ trứng này không?"
    textfix["昼光刺目，扰人清静。"] = "Ánh ban ngày chói mắt, quấy rầy sự thanh tĩnh."
    textfix["昼行妖物，凶煞逼人。"] = "Yêu vật đi ban ngày, hung sát bức người."
    textfix["显眼宝箱，或藏凶险。"] = "Rương kho lộ liễu, hoặc ẩn hung hiểm."
    textfix["晒干的海带叶，易于保存。"] = "Lá tảo biển phơi khô, dễ bảo quản."
    textfix["晕头转向，不堪大用。"] = "Chóng mặt quay cuồng, không đủ dùng vào việc lớn."
    textfix["晨露沾衣，微感湿意。"] = "Sương sớm thấm áo, hơi cảm thấy ẩm ướt."
    textfix["普通作物。"] = "Cây trồng thông thường."
    textfix["普通吹箭，射程有限，仅能扰敌。"] = "Tên thổi thường, tầm bắn hạn chế, chỉ có thể quấy rầy địch."
    textfix["普通灵偶，聊胜于无。"] = "Linh ngẫu thông thường, còn hơn không có gì."
    textfix["普通的橡胶塞，可密封某些药瓶。"] = "Nút cao su thường, có thể niêm phong một số bình thuốc."
    textfix["普通石子，不堪大用。"] = "Sỏi thường, không đủ dùng việc lớn."
    textfix["晶体巨兽，眼中藏玄。"] = "Cự thú tinh thể, trong mắt ẩn huyền."
    textfix["晶体独眼巨鹿雕像，异化的身躯闪烁着不祥的光芒。"] = "Tượng đá nai một mắt tinh thể, thân thể dị biến lấp lánh ánh sáng bất tường."
    textfix["晶石将出，再加把力。"] = "Thạch tinh sắp ra, thêm chút sức lực nào."
    textfix["晶莹剔透的果冻甜点，口感清爽。"] = "Món ngọt thạch trong suốt như pha lê, khẩu cảm thanh mát."
    textfix["晾肉架？可保存食物。"] = "Giá phơi thịt? Có thể bảo quản thức ăn."
    textfix["暂且予它些好处，免生事端。"] = "Tạm thời cho nó chút lợi ích, tránh sinh sự."
    textfix["暂留你内丹几日。"] = "Tạm giữ nội đan của ngươi vài ngày."
    textfix["暖石是凉的。"] = "Đá ấm hơi mát."
    textfix["暖石是温的。"] = "Đá ấm hơi ấm."
    textfix["暖石现在很冰冷。"] = "Đá ấm bây giờ rất lạnh giá."
    textfix["暖石现在很烫。"] = "Đá ấm bây giờ rất nóng."
    textfix["暖石，会与环境温度保持一致。"] = "Đá ấm, sẽ duy trì nhiệt độ đồng nhất với môi trường."
    textfix["暖阳哑铃，可活血通络。"] = "Tạ noãn dương, có thể hoạt huyết thông lạc."
    textfix["暗器回旋，雕虫小技。"] = "Ám khí xoay về, chỉ là vặt vãnh."
    textfix["暗夜魔剑，剑出无声，专伤神魂，煞气极重。"] = "Ma kiếm đêm tối, kiếm ra vô thanh, chuyên làm tổn thương thần hồn, sát khí cực nặng."
    textfix["暗影之心，蕴含着强大的暗影能量。"] = "Ám ảnh chi tâm, hàm chứa năng lượng ám ảnh mạnh mẽ."
    textfix["暗影凝聚的舞者，形态不定，似有惑心之能。"] = "Người nhảy múa được bóng tối ngưng tụ, hình thái không cố định, dường như có khả năng mê hoặc tâm."
    textfix["暗影所化的挖掘者，行为诡异。"] = "Người đào hố được hóa thành từ bóng tối, hành vi quái dị."
    textfix["暗影爬行者，是织影者的仆从。"] = "Kẻ bò bóng tối, là tùy tùng của kẻ dệt bóng."
    textfix["暗影祭坛，沟通九幽，驾驭影魅之力，然风险难测。"] = "Ám ảnh tế đàn, thông suốt cửu u, điều khiển lực lượng ảnh mị, nhưng rủi ro khó đoán."
    textfix["暗影编织者，由骨头和暗影构成的强大生物。"] = "Kẻ dệt bóng tối, sinh vật mạnh mẽ được cấu thành từ xương và bóng tối."
    textfix["暗影香炉，它的光芒能安抚暗影生物。"] = "Lư hương bóng tối, ánh sáng của nó có thể xoa dịu sinh vật bóng tối."
    textfix["暗影魔爪，凶戾非常。"] = "Ma trảo ám ảnh, hung lệ phi thường."
    textfix["暗影魔翼，徒具其形。"] = "Ma dực ám ảnh, chỉ có hình thức."
    textfix["暗影魔角，煞气逼人。"] = "Ma giác ám ảnh, sát khí bức người."
    textfix["暴食祭坛，用于供奉特定的祭品。"] = "Tế đàn bạo thực, dùng để thờ phụng tế phẩm đặc định."
    textfix["更衣之处有人，且待。"] = "Chỗ thay y phục có người, hãy đợi."
    textfix["曼德拉草精，其啼摄魂，速速封禁！"] = "Tinh Mandrake, tiếng kêu của nó thu hồn, nhanh phong ấn!"
    textfix["曼德拉草，蕴含极阴之气，可入药亦可炼魂。"] = "Mandrake, ẩn chứa cực âm chi khí, có thể làm thuốc cũng có thể luyện hồn."
    textfix["替死傀儡，以血肉为引，可挡一次死劫，然有伤天和。"] = "Thế tử quái lỗi, dùng huyết nhục làm dẫn, có thể đỡ một lần tử kiếp, nhưng có hại thiên hòa."
    textfix["月亮孢子？小心感染。"] = "Bào tử mặt trăng? Cẩn thận bị lây nhiễm."
    textfix["月亮祭坛连接？能量流动。"] = "Kết nối tế đàn mặt trăng? Năng lượng lưu động."
    textfix["月亮蘑菇树？散发微光。"] = "Cây nấm mặt trăng? Tỏa vi quang."
    textfix["月亮蘑菇？未知品种。"] = "Nấm mặt trăng? Chủng loài chưa biết."
    textfix["月亮雕像，试图捕捉太阴之形，野心不小。"] = "Tượng đá mặt trăng, cố gắng nắm bắt hình dạng thái âm, tham vọng không nhỏ."
    textfix["月亮雕像？蕴含月华之力。"] = "Tượng mặt trăng? Hàm chứa nguyệt hoa chi lực."
    textfix["月华之力不足，未能成丹。"] = "Lực lượng nguyệt hoa không đủ, không thể thành đan."
    textfix["月华之力构筑的传送阵。"] = "Trận truyền tống được xây dựng từ nguyệt hoa chi lực."
    textfix["月华之精，果然不凡。"] = "Tinh hoa nguyệt hoa, quả nhiên không tầm thường."
    textfix["月华入眠...倒是修炼的好时机"] = "Nguyệt hoa nhập định... lại là thời cơ tu luyện tốt."
    textfix["月华凝晶，光华内蕴。"] = "Nguyệt hoa ngưng kết thành tinh, quang hoa ẩn chứa bên trong."
    textfix["月华凝聚...正好采来炼丹"] = "Nguyệt hoa ngưng tụ... vừa hay thu hoạch để luyện đan."
    textfix["月华凝聚的妖巢..."] = "Sào yêu ngưng tụ nguyệt hoa..."
    textfix["月华变异物，或有用处。"] = "Vật biến dị nguyệt hoa, hoặc có ích."
    textfix["月华妖植，也敢猖狂。"] = "Yêu thực nguyệt hoa, cũng dám hoành hành."
    textfix["月华妖蛙，莫与对视。"] = "Yêu ếch nguyệt hoa, đừng nhìn thẳng vào mắt."
    textfix["月华尖刺，暗藏杀机。"] = "Gai nhọn nguyệt hoa, ẩn sát cơ."
    textfix["月华异动……莫非有先天灵宝现世？"] = "Nguyệt hoa dị động... hay chăng có tiên thiên linh bảo xuất thế?"
    textfix["月华战甲修补材料。"] = "Vật liệu tu bổ chiến giáp nguyệt hoa."
    textfix["月华战甲，光华流转。"] = "Chiến giáp nguyệt hoa, quang hoa lưu chuyển."
    textfix["月华灵兽，自裂隙出。"] = "Linh thú nguyệt hoa, từ liệt khích ra."
    textfix["月华灵猫，灵气充盈。"] = "Linh miêu nguyệt hoa, linh khí đầy ắp."
    textfix["月华琉璃，非比寻常。"] = "Lưu ly nguyệt hoa, phi thường."
    textfix["月华甲壳，可炼法宝。"] = "Giáp vỏ nguyệt hoa, có thể luyện pháp bảo."
    textfix["月华精粹，稀世珍宝。"] = "Tinh túy nguyệt hoa, trân bảo hi thế."
    textfix["月华虹吸大阵，果然玄妙。"] = "Đại trận hút nguyệt hoa, quả nhiên huyền diệu."
    textfix["月华虾妖？倒是罕见。"] = "Tôm yêu nguyệt hoa? Lại hiếm thấy."
    textfix["月华裂隙被封印了。"] = "Liệt khích nguyệt hoa bị phong ấn."
    textfix["月华裂隙，近在咫尺却难入。"] = "Liệt khích nguyệt hoa, gần trong gang tấc mà khó vào."
    textfix["月华过盛，反损菌灵。"] = "Nguyệt hoa quá thịnh, ngược lại tổn hại nấm linh."
    textfix["月华锄铲，翻土如云。"] = "Cuốc xẻng nguyệt hoa, lật đất như mây."
    textfix["月坛阵眼...暗合星象"] = "Trận nhãn nguyệt đàn... ngầm hợp với tinh tượng."
    textfix["月宫图腾...暗藏玄机"] = "Đồ totem nguyệt cung... ẩn chứa huyền cơ."
    textfix["月宫天眼？！竟能窥探四方"] = "Thiên nhãn nguyệt cung?! Thực sự có thể dò xét tứ phương."
    textfix["月宫玉兔的后裔？灵性十足，擅寻灵植。"] = "Hậu duệ của Ngọc Thỏ nguyệt cung? Linh tính đầy đủ, giỏi tìm linh thực."
    textfix["月宫琼浆...虽臭却是炼药良材."] = "Ngọc tương nguyệt cung... dù hôi nhưng là nguyên liệu luyện dược tốt."
    textfix["月宫碎玉...可炼护身法器"] = "Ngọc vỡ nguyệt cung... có thể luyện pháp khí hộ thân."
    textfix["月宫秘力涌现！大道可期"] = "Bí lực nguyệt cung trào dâng! Đại đạo đáng trông đợi."
    textfix["月宫秘术...正合参悟！"] = "Bí thuật nguyệt cung... vừa hay để tham ngộ!"
    textfix["月岩企鹅正在睡觉。"] = "Chim cánh cụt đá nguyệt đang ngủ."
    textfix["月岩企鹅死了。"] = "Chim cánh cụt đá nguyệt chết rồi."
    textfix["月岩企鹅，一种生活在月岛的奇特企鹅。"] = "Chim cánh cụt đá nguyệt, một loài chim cánh cụt kỳ lạ sống ở đảo nguyệt."
    textfix["月岩塑形，内含太阴精华。"] = "Nguyệt thạch tạo hình, bên trong chứa tinh hoa thái âm."
    textfix["月岩墙，散发着微弱的月光能量。"] = "Tường đá nguyệt, tỏa ra năng lượng nguyệt quang vi nhược."
    textfix["月曜玻璃斧，非常锋利但也很易碎。"] = "Rìu thủy tinh nguyệt diệu, rất sắc bén nhưng cũng dễ vỡ."
    textfix["月树已被烧毁。"] = "Nguyệt thụ đã bị thiêu huỷ."
    textfix["月树已被砍伐。"] = "Nguyệt thụ đã bị chặt."
    textfix["月树正在燃烧。"] = "Nguyệt thụ đang cháy."
    textfix["月树的花朵，散发着柔和的光芒。"] = "Hoa của nguyệt thụ, tỏa ra ánh sáng nhu hòa."
    textfix["月树苗，似乎是由月蛾转化而来。"] = "Cây nguyệt thụ con, dường như được chuyển hóa từ nguyệt nga."
    textfix["月桂枝法杖，御敌千里。"] = "Pháp trượng cành nguyệt quế, chế địch nghìn dặm."
    textfix["月满之夜，常生异象。"] = "Đêm trăng tròn, thường sinh dị tượng."
    textfix["月煞入体，猪人狂化！凶性暴涨，速退！"] = "Nguyệt sát nhập thể, heo người cuồng hóa! Tính hung bùng phát, lui nhanh!"
    textfix["月盈则亏，此乃天道。"] = "Trăng đầy thì khuyết, đó là thiên đạo."
    textfix["月相之变，与王某何干。"] = "Sự thay đổi nguyệt tướng, có liên quan gì đến Vương Mỗ."
    textfix["月缺，亦如人生，总有残缺。"] = "Trăng khuyết, cũng như nhân sinh, luôn có khiếm khuyết."
    textfix["月蚀乌鸦，形态诡异。"] = "Quạ nguyệt thực, hình thái quái dị."
    textfix["月蛾幼体，在暗处会发出微光。"] = "Bướm đêm nguyệt non, trong bóng tối sẽ phát ra ánh sáng nhỏ."
    textfix["月蛾的翅膀，薄如蝉翼，泛着微光。"] = "Cánh của nguyệt nga, mỏng như cánh ve, phản chiếu vi quang."
    textfix["月蛾雕像，翅翼纹路精巧。"] = "Tượng đá bướm đêm nguyệt, vân đường cánh tinh xảo."
    textfix["月蛾，翅膀上有着月亮般的纹路。"] = "Nguyệt nga, trên cánh có hoa văn như mặt trăng."
    textfix["月魄头盔，可御灾劫。"] = "Mũ trụ nguyệt phách, có thể ngự tai kiếp."
    textfix["月魄流萤，灵气逼人。"] = "Lưu huỳnh nguyệt phách, linh khí bức người."
    textfix["有人正在使用，且待片刻。"] = "Có người đang dùng, hãy chờ chút."
    textfix["有人正在使用，稍候片刻。"] = "Có người đang dùng, xin đợi chút."
    textfix["有人正在使用，稍后再来。"] = "Có người đang dùng, lát nữa hãy lại."
    textfix["有妖气逼近，是巡山犬类。"] = "Có yêu khí tiến gần, là loài chó tuần sơn."
    textfix["有杀气潜伏，匿于暗处。"] = "Có sát khí ẩn phục, nấp trong bóng tối."
    textfix["有灵物在指引方向……"] = "Có linh vật đang chỉ dẫn phương hướng..."
    textfix["有裂痕的茶杯，已不堪使用。"] = "Tách trà có vết nứt, đã không còn dùng được."
    textfix["朔月之夜，阴死之气最浓..."] = "Đêm sóc nguyệt, âm tử chi khí nồng nhất..."
    textfix["木制短剑，聊胜于无。"] = "Đoản kiếm gỗ, còn hơn không có gì."
    textfix["木坊焚毁，不堪再用。"] = "Xưởng mộc bị thiêu, không dùng được nữa."
    textfix["木墙被烧毁了。"] = "Tường gỗ bị thiêu huỷ."
    textfix["木墙，带有尖刺，能造成一些伤害。"] = "Tường gỗ, có gai nhọn, có thể gây ra một số thương thương."
    textfix["木头在燃烧。"] = "Gỗ đang cháy."
    textfix["木头，基础的建筑和燃料材料。"] = "Gỗ, nguyên liệu xây dựng và nhiên liệu cơ bản."
    textfix["木属性灵气充沛，可作炼器之用。"] = "Linh khí mộc thuộc tính dồi dào, có thể dùng để luyện khí."
    textfix["木工坊，可制凡间家具。"] = "Xưởng mộc, có thể chế đồ nội thất phàm trần."
    textfix["木板？连造艘像样的船都不够！"] = "Ván gỗ? Ngay cả đóng một chiếc thuyền tử tế cũng không đủ!"
    textfix["木栅栏，可以圈定一片区域。"] = "Hàng rào gỗ, có thể khoanh định một vùng."
    textfix["木椅凡品，勉强可坐。"] = "Ghế gỗ phàm phẩm, miễn cưỡng có thể ngồi."
    textfix["木灵之魂...正是炼制长生丹的主材！"] = "Hồn mộc linh... chính là nguyên liệu chính để luyện trường sinh đan!"
    textfix["木炭，燃烧持久，是良好的燃料。"] = "Than gỗ, cháy lâu dài, là nhiên liệu tốt."
    textfix["木煞之气已被禁锢，或可一用。"] = "Mộc sát chi khí đã bị giam cầm, có thể dùng được."
    textfix["木牌被烧毁了。"] = "Tấm biển gỗ đã bị thiêu hủy."
    textfix["木球浮标？凡人才需此物！"] = "Phao gỗ tròn? Phàm nhân mới cần vật này!"
    textfix["木质地板，寻常凡物。"] = "Sàn gỗ, vật tầm thường."
    textfix["木质灵甲，轻便坚韧，堪堪一用。"] = "Linh giáp gỗ, nhẹ nhàng bền bỉ, cũng đủ dùng."
    textfix["木雕帽，工艺尚可。"] = "Mũ chạm gỗ, công nghệ tạm được."
    textfix["未开灵智的小妖。"] = "Tiểu yêu chưa khai linh trí."
    textfix["未成之曲，尚待完善。"] = "Khúc chưa hoàn thành, vẫn chờ hoàn thiện."
    textfix["未成熟的沙拉蝾螈，颜色青绿。"] = "Kỳ nhông salad chưa chín, màu xanh lục."
    textfix["未雕琢的木料，尚需加工。"] = "Gỗ chưa được chạm khắc, cần gia công thêm."
    textfix["本尊亲自出手便是。"] = "Bổn tôn đích thân ra tay vậy."
    textfix["本尊道念中又添一道造化。"] = "Trong đạo niệm của bổn tôn lại thêm một đạo tạo hóa."
    textfix["机关人偶，构造精巧，似有驱动核心。"] = "Người máy cơ quan, cấu trúc tinh xảo, dường như có hạch tâm vận hành."
    textfix["机关人儡，动作僵硬，似被无形丝线操控。"] = "Cơ quan nhân lỗi, hành động cứng nhắc, dường như bị sợi chỉ vô hình thao túng."
    textfix["机关傀儡，不知裁判如何评判。"] = "Quái lỗi cơ quan, không biết trọng tài đánh giá thế nào."
    textfix["机关傀儡，竟有分神之能？"] = "Quái lỗi cơ quan, lại có khả năng phân thần?"
    textfix["机关图谱，巧夺天工。"] = "Đồ phổ cơ quan, tài khéo vượt thiên công."
    textfix["机关枢纽..."] = "Trung khu cơ quan..."
    textfix["机关重启之术...有点意思..."] = "Thuật khởi động lại cơ quan... có chút thú vị..."
    textfix["机关鼠玩，可戏灵猫。"] = "Chuột cơ quan đồ chơi, có thể đùa linh miêu."
    textfix["机械战甲，似非凡品。"] = "Chiến giáp cơ giới, dường như phi phàm phẩm."
    textfix["机械残件，尚需雕琢。"] = "Phụ kiện cơ giới, vẫn cần điêu khắc."
    textfix["机缘兑换阵..."] = "Trận đổi chác cơ duyên..."
    textfix["机缘已至，秘法自现。"] = "Cơ duyên đã đến, bí pháp tự hiện."
    textfix["机缘未至，待你醒转再予不迟。"] = "Cơ duyên chưa đến, đợi ngươi tỉnh lại rồi trao cũng chưa muộn."
    textfix["机缘轮盘？测我气运。"] = "Luân bàn cơ duyên? Đo khí vận của ta."
    textfix["杀人蜂的巢穴，靠近会遭到蜂群攻击。"] = "Tổ ong sát nhân, tiếp cận sẽ bị đàn ong tấn công."
    textfix["杀人蜂，攻击性极强。"] = "Ong sát thủ, tính tấn công cực mạnh."
    textfix["杀你污手。"] = "Giết ngươi bẩn tay ta."
    textfix["杀气萦绕，岂能安憩？"] = "Sát khí vây quanh, sao có thể nghỉ ngơi?"
    textfix["杀鸡焉用牛刀。"] = "Giết gà sao cần dùng dao mổ trâu."
    textfix["杂芜并存，徒损灵机。"] = "Tạp nham lẫn lộn, chỉ hao tổn linh cơ."
    textfix["杂草丛生。"] = "Cỏ dại mọc um tùm."
    textfix["杂草丛生，当以剑气除之..."] = "Cỏ dại mọc um tùm, nên dùng kiếm khí trừ đi..."
    textfix["材料不全，巧妇难为无米之炊。"] = "Vật liệu chưa đủ, khéo tay cũng khó nấu cơm không gạo."
    textfix["材料不符，需另寻他物。"] = "Vật liệu không phù hợp, cần tìm thứ khác."
    textfix["材料不足，还需搜集。"] = "Vật liệu chưa đủ, cần thu thập thêm."
    textfix["材料已备，可施工艺。"] = "Vật liệu đã chuẩn bị, có thể thi công kỹ thuật."
    textfix["材质凡劣，难承道韵。"] = "Chất liệu tầm thường kém cỏi, khó chứa đựng đạo vận."
