    textfix["此物，与你无用。"] = "Vật này, chẳng có ích gì cho ngươi."
    textfix["此猪人愿追随于我，或可利用其蛮力。"] = "Heo người này muốn đi theo ta, có thể lợi dụng sức mạnh thô thiển của nó."
    textfix["此猫有主，不为我用。"] = "Con mèo này có chủ, không phục vụ ta."
    textfix["此獠当真伏诛了？"] = "Tên này thật sự bị phục chú rồi?"
    textfix["此獠狂性大发，正可试我锋芒。"] = "Tên này cuồng tính phát tác, vừa hay thử thách phong mang của ta."
    textfix["此甲不凡，可作保命之用。"] = "Giáp này phi thường, có thể dùng để bảo toàn tính mạng."
    textfix["此甲厚重，防御尚可，但过于笨拙。"] = "Giáp này dày nặng, phòng thủ tạm được, nhưng quá vụng về."
    textfix["此界镇守者？气息诡谲，似人非人。"] = "Người trấn giữ thế giới này? Khí tức quái dị, giống người mà không phải người."
    textfix["此盔可护元神，避邪祟。"] = "Khôi này có thể hộ nguyên thần, tránh tà chú."
    textfix["此石笋汇聚地脉灵气，已非凡品。"] = "Thạch nhũ này tụ linh khí địa mạch, đã không phải phàm phẩm."
    textfix["此碑竟能扰乱心神？倒是件邪门法宝"] = "Bia này mà có thể nhiễu loạn tâm thần? Thật là thứ pháp bảo tà môn."
    textfix["此穴直通幽冥，煞气冲天。"] = "Hốc này thông thẳng đến u minh, sát khí xung thiên."
    textfix["此笔...竟封印着真火？"] = "Chiếc bút này... thực sự phong ấn chân hỏa?"
    textfix["此等仙种，正合我用。"] = "Tiên chủng như vậy, vừa hay hợp với ta."
    textfix["此等俗物，不换也罢。"] = "Vật tục như vậy, không đổi cũng được."
    textfix["此等凡物，不入王某法眼。"] = "Vật tầm thường như vậy, không lọt được mắt xanh của ta."
    textfix["此等变化之术，早已掌握。"] = "Thuật biến hóa như vậy, ta đã nắm rõ từ lâu."
    textfix["此等法器，可会通灵？"] = "Pháp khí loại này, có thể thông linh không?"
    textfix["此等浊物，无益于灵植辨析。"] = "Vật trọc như vậy, vô ích cho việc phân tích linh thực."
    textfix["此等符文，非比寻常。"] = "Phù văn loại này, phi thường."
    textfix["此等距离，神念亦可及。"] = "Khoảng cách này, thần niệm cũng có thể với tới."
    textfix["此箱有禁制守护。"] = "Hòm này có cấm chế thủ hộ."
    textfix["此箱灵气异常，非同寻常。"] = "Linh khí rương này dị thường, phi thường."
    textfix["此罐似有保鲜禁制？"] = "Hũ này dường như có cấm chế bảo tươi?"
    textfix["此花妖种，可植于洞府之外以御外敌。"] = "Hạt giống hoa yêu này, có thể trồng ngoài động phủ để chống ngoại địch."
    textfix["此花禁制，尚需时日破解。"] = "Cấm chế hoa này, vẫn cần thời gian phá giải."
    textfix["此草木特性，已记录在案。"] = "Đặc tính thảo mộc này đã được ghi lại."
    textfix["此菇竟能自行吐纳发光，奇妙。"] = "Con nấm này thực sự có thể tự tổ nạp phát sáng, kỳ diệu."
    textfix["此菌通体幽蓝，阴寒之气逼人。"] = "Nấm này toàn thân màu xanh u ám, âm hàn chi khí bức người."
    textfix["此蝶已受制，可取其翅或放生。"] = "Con bướm này đã bị khống chế, có thể lấy cánh hoặc thả."
    textfix["此袋可保食材新鲜，尚可一用。"] = "Túi này có thể giữ nguyên liệu tươi, tạm có thể dùng."
    textfix["此路已绝，非我之道。"] = "Con đường này đã tuyệt, không phải đạo của ta."
    textfix["此钓具图谱，我已参详过了。"] = "Đồ quyển ngư cụ này, ta đã tham khảo qua rồi."
    textfix["此钥非此锁所用。"] = "Chìa này không phải dùng cho ổ khóa này."
    textfix["此铃...竟能沟通月华之力？"] = "Chiếc chuông này... thực sự có thể giao tiếp nguyệt hoa chi lực?"
    textfix["此铃已与它兽结下灵契。"] = "Chiếc chuông này đã kết linh khế với thú khác."
    textfix["此阵，尚缺一味菌引。"] = "Trận này vẫn thiếu một vị nấm dẫn."
    textfix["此雀通体冰寒，却无恶意。"] = "Con tước này toàn thân lạnh băng, nhưng không có ác ý."
    textfix["此雀饥鸣索食，灵性初显。"] = "Con tước này kêu đói đòi ăn, linh tính mới hiển lộ."
    textfix["此非可食之物。"] = "Đây không phải vật có thể ăn."
    textfix["此非可驯化之灵兽，铃对其无效。"] = "Đây không phải linh thú có thể thuần hóa, chuông không có tác dụng."
    textfix["此非阵眼所需之物。"] = "Đây không phải vật mà trận nhãn cần."
    textfix["此靶暗合九宫方位。"] = "Bia này ngầm hợp cửu cung phương vị."
    textfix["此音律可加固法宝。"] = "Âm luật này có thể củng cố pháp bảo."
    textfix["此鱼尚未通灵，不入品阶。"] = "Con cá này chưa thông linh, không đủ phẩm cấp."
    textfix["此鸟濒临饿毙，需立即喂食。"] = "Con chim này gần chết đói, cần cho ăn ngay."
    textfix["此黏液滑腻，似有腐蚀之性。"] = "Chất nhớt này trơn nhờn, dường như có tính ăn mòn."
    textfix["此鼎炼化需时，耐心等待。"] = "Đỉnh này luyện hóa cần thời gian, kiên nhẫn chờ đợi."
    textfix["此鼠气血孱弱，难当大任。"] = "Con chuột này khí huyết yếu ớt, khó đảm đương việc lớn."
    textfix["死虾材料，可制低阶丹药。"] = "Vật liệu tôm chết, có thể chế đan dược hạ giai."
    textfix["残存一丝月精...尚可一用"] = "Còn sót một sợi nguyệt tinh... vẫn có thể dùng được."
    textfix["残破机关，似曾相识。"] = "Cơ quan tàn phá, dường như đã từng quen biết."
    textfix["残魂依附的铠甲，徒具其型。"] = "Khải giáp có tàn hồn bám víu, chỉ có hình mà thôi."
    textfix["残魂执念，何苦强留人间。"] = "Tàn hồn chấp niệm, hà tất phải lưu luyến cõi người."
    textfix["毒刺已除，此木可为我所用。"] = "Gai độc đã loại bỏ, gỗ này có thể cho ta sử dụng."
    textfix["毒孢混于生机之中，更为隐秘。"] = "Bào tử độc lẫn vào sinh cơ, càng thêm ẩn tàng."
    textfix["毒棘已焚，煞气暂消。"] = "Gai độc đã thiêu, sát khí tạm tiêu."
    textfix["毒涎妖鱼，污秽之物。"] = "Yêu ngư nước dãi độc, vật ô uế."
    textfix["毒液变异物，阴损。"] = "Vật biến dị độc dịch, âm độc."
    textfix["毒穴已空，妖物离巢。"] = "Hốc độc đã trống, yêu vật rời tổ."
    textfix["毒菇经真火炼化，转为大补之物，可壮气血。"] = "Độc cô qua chân hỏa luyện hóa, chuyển thành đại bổ chi vật, có thể tráng khí huyết."
    textfix["毒菌化形，修为不浅，需小心应对。"] = "Nấm độc hóa hình, tu vi không nông, cần cẩn thận ứng phó."
    textfix["毒菌成精，化为此座，当诛。"] = "Nấm độc thành tinh, hóa thành vật này, đáng giết."
    textfix["毒菌蟾蜍雕像，形态介于菌类与动物之间，颇为奇特。"] = "Tượng đá cóc nấm độc, hình thái giữa nấm và động vật, khá kỳ đặc."
    textfix["毒蛛蛰伏，此时正是采集毒液的好时机。"] = "Nhện độc đang nằm im, đây chính là thời cơ tốt để thu thập độc dịch."
    textfix["毒蜂尾针，尖锐无比，是制作暗器的好材料。"] = "Đuôi kim của ong độc, sắc bén vô cùng, là vật liệu tốt để chế tác ám khí."
    textfix["气息已锁定……"] = "Khí tức đã bị khóa định..."
    textfix["气息有异，莫非是调虎离山？"] = "Khí tức có dị biệt, hay chăng là điệu hổ ly sơn?"
    textfix["气息消散，暂且作罢。"] = "Khí tức tiêu tán, tạm thời thôi."
    textfix["气血有亏，强施此术恐伤及本源。"] = "Khí huyết chưa đủ, cưỡng ép thi triển thuật này e tổn thương bản nguyên."
    textfix["气贯...周身..."] = "Khí quán... toàn thân..."
    textfix["水不在深，有龙则灵。"] = "Nước không cần sâu, có rồng là linh."
    textfix["水域已固，浴丹难融。"] = "Thủy vực đã đông đặc, đan dược khó tan."
    textfix["水壶已空，需加水。"] = "Bình nước đã cạn, cần thêm nước."
    textfix["水妖！正好取你妖丹炼制避水珠！"] = "Thủy yêu! Vừa hay lấy yêu đan của ngươi để luyện tị thủy châu!"
    textfix["水府青丝...勉强可入药"] = "Thanh ty thủy phủ... gượng có thể làm thuốc."
    textfix["水族精怪，听吾号令！"] = "Thủy tộc tinh quái, hãy nghe lệnh ta!"
    textfix["水果拼盘，由多种水果制成。"] = "Đĩa trái cây, được làm từ nhiều loại trái cây."
    textfix["水果蛋糕，用料扎实，可以保存很久。"] = "Bánh trái cây, nguyên liệu chắc chắn, có thể bảo quản rất lâu."
    textfix["水汽不侵，片叶不沾。"] = "Thủy khí không xâm, mảnh lá không thấm."
    textfix["水汽充沛，金石之气混杂。"] = "Thủy khí dồi dào, kim thạch chi khí lẫn lộn."
    textfix["水泵？取水工具。"] = "Máy bơm nước? Công cụ lấy nước."
    textfix["水球，投掷后可泼洒液体，常用于灭火或娱乐。"] = "Bóng nước, sau khi ném có thể vẩy chất lỏng, thường dùng để dập lửa hoặc vui chơi."
    textfix["水畔灵苇，是制作符纸的上佳材料。"] = "Linh vĩ bên nước, là vật liệu thượng hảo để chế tác phù chỉ."
    textfix["水黾变异丹，可化形为妖。"] = "Đan biến dị bọ nước, có thể hóa hình thành yêu."
    textfix["水黾妖物，踏波而行。"] = "Yêu vật bọ nước, bước sóng mà đi."
    textfix["永恒之枪，投掷后会自动返回手中。"] = "Thương vĩnh hằng, sau khi ném sẽ tự động trở lại tay."
    textfix["污秽之物，有损道心。"] = "Vật ô uế, có hại đạo tâm."
    textfix["污秽糖浆，不堪入口。"] = "Xi rô ô uế, không thể vào miệng."
    textfix["沉思学者像，或许能带来一丝宁静。"] = "Tượng học giả trầm tư, hoặc có thể mang lại chút yên tĩnh."
    textfix["沉睡时倒有几分可爱。"] = "Lúc ngủ say lại có mấy phần đáng yêu."
    textfix["沉睡蟹王，小心为妙。"] = "Vua cua đang ngủ, cẩn thận là hay."
    textfix["沐浴球，放入温泉中会产生特殊效果。"] = "Bóng tắm, thả vào suối nóng sẽ tạo ra hiệu ứng đặc biệt."
    textfix["沙凝成刃，雕虫小技。"] = "Cát ngưng thành lưỡi, chỉ là trò vặt."
    textfix["沙土烧制的杯盏，工艺原始。"] = "Chén bát nung cát đất, kỹ nghệ nguyên thủy."
    textfix["沙地贫瘠，金气涣散。"] = "Đất cát cằn cỗi, kim khí tản mát."
    textfix["沙地隐有异香，似与妖猴相关。"] = "Trong cát ẩn chứa hương kỳ, dường như liên quan đến yêu hầu."
    textfix["沙妖竟敢觊觎本尊宝物？"] = "Sa yêu thực sự dám dòm ngó bảo vật của bổn tôn?"
    textfix["沙拉蝾螈睡着了。"] = "Kỳ nhông salad ngủ rồi."
    textfix["沙漠灵猫，耐旱耐热。"] = "Linh miêu sa mạc, chịu hạn chịu nóng."
    textfix["沙漠风镜，于沙暴环境中不可或缺。"] = "Kính sa mạc, trong môi trường bão cát không thể thiếu."
    textfix["治疗法杖，能释放治愈能量。"] = "Trị liệu pháp trượng, có thể giải phóng năng lượng chữa lành."
    textfix["治疗药膏，能快速治愈伤口。"] = "Thuốc mỡ chữa trị, có thể nhanh chóng chữa lành vết thương."
    textfix["沼底鱼妖，灵智未开，只知凭本能袭扰过客。"] = "Ngư yêu đáy đầm, linh trí chưa khai mở, chỉ biết dựa vào bản năng tấn công khách qua đường."
    textfix["沼泽灵猫，善于隐匿。"] = "Linh miêu đầm lầy, giỏi ẩn nấp."
    textfix["沼泽猪长老正在休息。"] = "Trưởng lão lợn đầm lầy đang nghỉ ngơi."
    textfix["沼泽猪长老，负责管理猪人村庄的事务。"] = "Trưởng lão lợn đầm lầy, phụ trách quản lý sự vụ làng người lợn."
    textfix["沼泽触手妖物，擅于潜伏突袭，需留意脚下。"] = "Yêu vật xúc tu đầm lầy, giỏi ẩn nấp đột kích, cần chú ý dưới chân."
    textfix["沼生凡草，阴气滋养，可作低阶毒媒。"] = "Cỏ đầm lầy thường, được âm khí nuôi dưỡng, có thể làm môi chất độc cấp thấp."
    textfix["法器充能中..."] = "Pháp khí đang nạp năng lượng..."
    textfix["法器损毁，尚可修复。"] = "Pháp khí bị hủy, vẫn có thể tu phục."
    textfix["法坛初成，灵气稀薄。"] = "Pháp đàn mới thành, linh khí thưa thớt."
    textfix["法坛升级，灵气渐浓。"] = "Pháp đàn nâng cấp, linh khí dần nồng."
    textfix["法坛圆满，可聚天地元气！"] = "Pháp đàn viên mãn, có thể tụ thiên địa nguyên khí!"
    textfix["法坛基座，需精心搭建。"] = "Đế tòa pháp đàn, cần cẩn thận dựng xây."
    textfix["法坛焚毁，前功尽弃。"] = "Pháp đàn bị thiêu, công trước uổng phí."
    textfix["法宝妙用，我已洞悉。"] = "Diệu dụng pháp bảo, ta đã thấu suốt."
    textfix["法式肉馅饼，馅料扎实。"] = "Bánh pie nhân thịt Pháp, nhân chắc."
    textfix["法网修复，可再用之。"] = "Pháp võng tu phục, có thể dùng lại."
    textfix["法阵核心残缺，需集齐所有部件方能运转。"] = "Hạch tâm pháp trận tàn khuyết, cần tập hợp đủ tất cả bộ phận mới có thể vận hành."
    textfix["法阵核心过载，已然崩坏。"] = "Hạch tâm pháp trận quá tải, đã sụp đổ."
    textfix["法阵部件已集齐大半，空间波动渐显。"] = "Bộ phận pháp trận đã tập hợp được phần lớn, không gian ba động dần hiển lộ."
    textfix["波兰传统饼干，通常装饰精美。"] = "Bánh quy truyền thống Ba Lan, thường trang trí tinh xảo."
    textfix["泥泞不堪，污秽陷足。"] = "Bùn lầy không chịu được, ô uế lún chân."
    textfix["泥泞陷坑，污秽不堪。"] = "Hố bùn lầy, ô uế không chịu được."
    textfix["泥潭妖鱼，腥臭难闻。"] = "Yêu ngư đầm lầy, tanh thối khó ngửi."
    textfix["洋葱种子。"] = "Hạt giống hành tây."
    textfix["洋葱，辛辣刺眼。"] = "Hành tây, cay nồng cay mắt."
    textfix["洞中妖猴，狡黠善窃，扰人清修。"] = "Yêu hầu trong hang, xảo quyệt giỏi trộm, quấy rầy tu hành."
    textfix["洞穴变异物，谨慎使用。"] = "Vật biến dị hang động, cẩn thận sử dụng."
    textfix["洞穴蕨类，适应幽暗环境而生。"] = "Dương xỉ hang động, thích nghi với môi trường u ám mà sống."
    textfix["洞穴香蕉已被焚毁。"] = "Chuối hang động đã bị thiêu hủy."
    textfix["洞窟不稳，恐有坍塌之危。"] = "Động phủ không ổn, e có nguy cơ sụp đổ."
    textfix["活木，蕴含生命能量的木头。"] = "Cây sống, gỗ ẩn chứa năng lượng sinh mệnh."
    textfix["流云披肩，轻若无物。"] = "Khăn choàng lưu vân, nhẹ như không có gì."
    textfix["流光摄魂幡材料..."] = "Vật liệu phướn thu hồn lưu quang..."
