    textfix["灵根离土，生机渐失。"] = "Linh căn rời đất, sinh cơ dần mất."
    textfix["灵根袋，可储土系灵物。"] = "Túi linh căn, có thể chứa linh vật thổ hệ."
    textfix["灵植已成熟，灵气内蕴，正是采摘之时。"] = "Linh thực đã chín, linh khí ẩn chứa, đúng là lúc thu hoạch."
    textfix["灵植所制的符纸，是书写基础符箓的载体。"] = "Phù giấy được chế từ linh thực, là vật mang để viết phù lục cơ bản."
    textfix["灵植正在汲取地脉灵气，缓慢生长。"] = "Linh thực đang hút linh khí địa mạch, chậm rãi sinh trưởng."
    textfix["灵植过密，灵气难聚。"] = "Linh thực quá dày, linh khí khó tụ."
    textfix["灵植长势旺盛，灵气盎然。"] = "Linh thực sinh trưởng mạnh mẽ, linh khí tràn trề."
    textfix["灵气尚可，未辱没王某栽培。"] = "Linh khí tạm được, chưa hổ thẹn với sự bồi dưỡng của Vương Mỗ."
    textfix["灵气已失，味同嚼蜡。"] = "Linh khí đã mất, vô vị như nhai sáp."
    textfix["灵气已散，废物一件。"] = "Linh khí đã tán, một món phế vật."
    textfix["灵气未复，需待时日。"] = "Linh khí chưa phục, cần chờ thời gian."
    textfix["灵气未满，尚需温养。"] = "Linh khí chưa đầy, vẫn cần ôn dưỡng."
    textfix["灵泉之眼？水汽氤氲，似有鱼龙潜藏。"] = "Mắt linh tuyền? Thủy khí mờ ảo, dường như có cá rồng ẩn phục."
    textfix["灵猫引路，随之前行。"] = "Linh miêu dẫn đường, theo đó tiến lên."
    textfix["灵猫离去，独自寻宝。"] = "Linh miêu rời đi, một mình tìm kiếm bảo vật."
    textfix["灵猫项圈，需赐名号。"] = "Vòng cổ linh miêu, cần ban tên hiệu."
    textfix["灵猴巢穴，喧闹不堪。"] = "Sào huyệt linh hầu, ồn ào không chịu nổi."
    textfix["灵玉哑铃，蕴含天地之力。"] = "Tạ linh ngọc, hàm chứa thiên địa chi lực."
    textfix["灵禽蛋膳，尚需火候。"] = "Trứng linh cầm, vẫn cần thêm lửa."
    textfix["灵种生机勃勃，非同凡响。"] = "Linh chủng sinh cơ dạt dào, phi thường mãnh liệt."
    textfix["灵肉干，气血凝而不散，乃闭关辟谷之上品。"] = "Linh nhục khô, khí huyết ngưng mà không tán, là thượng phẩm để bế quan tịch cốc."
    textfix["灵花初绽，光华流转。"] = "Linh hoa mới nở, quang hoa lưu chuyển."
    textfix["灵花焚尽，芳魂已逝。"] = "Linh hoa thiêu hết, phương hồn đã qua."
    textfix["灵苇已收，待其重新汲取水灵之气生长。"] = "Linh vĩ đã thu hoạch, đợi nó hút lại thủy linh chi khí mà sinh trưởng."
    textfix["灵茄镶宝（肉），虽是素食，却也滋味丰富。"] = "Linh già khảm bảo (nhân thịt), tuy là ăn chay, nhưng hương vị cũng phong phú."
    textfix["灵草离土，药性渐失。"] = "Linh thảo rời đất, dược tính dần mất."
    textfix["灵菌已死，精华尽散。"] = "Linh nấm đã chết, tinh hoa tản hết."
    textfix["灵蔬蛋羹，晨修佳品。"] = "Canh trứng linh thảo, sản phẩm tốt cho buổi sáng tu luyện."
    textfix["灵蕴不合，徒劳无功。"] = "Linh uẩn không hợp, uổng công vô ích."
    textfix["灵蕴内敛，光华不显。"] = "Linh uẩn thu liễm, quang hoa không hiển."
    textfix["灵蕴已布，过犹不及。"] = "Linh uẩn đã đủ, quá mức cũng không tốt."
    textfix["灵蚕丝线，可惜已磨损，灵力尽失。"] = "Tơ linh tằm, tiếc là đã mài mòn, linh lực tận mất."
    textfix["灵雀在手，能感到其体内微弱的生机流转。"] = "Linh tước trong tay, có thể cảm nhận sinh cơ vi nhược lưu chuyển trong thân nó."
    textfix["灵雀幼雏，羽翼未丰，需小心看护。"] = "Linh tước ấu chú, cánh chưa đủ lông, cần cẩn thận chăm sóc."
    textfix["灵雀蛰眠，正在蓄养元气。"] = "Linh tước đang ngủ đông, đang tích lũy nguyên khí."
    textfix["灵面裹仙肴，食之可快速恢复元气，疗愈暗伤。"] = "Linh diện bọc tiên hào, ăn vào có thể nhanh chóng phục hồi nguyên khí, chữa lành ám thương."
    textfix["灵韵已失，与枯枝何异。"] = "Linh vận đã mất, khác gì với cành khô."
    textfix["灵鱼机关部件，易如反掌。"] = "Bộ phận cơ quan linh ngư, dễ như trở bàn tay."
    textfix["灵鱼焦黑，再无用处。"] = "Linh ngư đen thui, không còn ích dụng."
    textfix["灵鳄梨所制酱料，口感奇特，略有滋补之效。"] = "Sốt được làm từ bơ linh, khẩu cảm kỳ đặc, có chút bổ dưỡng."
    textfix["灵鸟羽冠，可通鸟语。"] = "Vũ quan linh điểu, có thể thông điểu ngữ."
    textfix["灵鸦食饵，可诱仙禽。"] = "Mồi ăn linh nha, có thể dụ tiên cầm."
    textfix["灵鹳孵化需汲取天地灵气，急不得。"] = "Linh hạc ấp nở cần hút thiên địa linh khí, không thể vội."
    textfix["灵鹳巢，一枚蕴含生命精华的蛋静置其中。"] = "Tổ linh hạc, một quả trứng hàm chứa tinh hoa sinh mệnh đặt yên trong đó."
    textfix["灵鹳幼雏，虽腿脚未长开，已显峥嵘。"] = "Ấu chú linh hạc, tuy chân chưa dài ra, đã hiển lộ khí phách."
    textfix["灵鹳蛋内生机活跃，即将破壳。"] = "Sinh cơ bên trong trứng linh hạc năng động, sắp vỡ vỏ."
    textfix["灵鹳蛋，蛋壳坚硬如铁，内蕴生命精华。"] = "Trứng linh hạc, vỏ trứng cứng như sắt, bên trong hàm chứa tinh hoa sinh mệnh."
    textfix["灶火之技，何足道哉。"] = "Nghề bếp núc, có gì đáng nói."
    textfix["炉鼎有主，退下。"] = "Lò đỉnh đã có chủ, lui ra."
    textfix["炎热干旱，草木难存。"] = "Nóng nực khô hạn, thảo mộc khó tồn tại."
    textfix["炎阳真火，焚尽八荒。"] = "Chân hỏa viêm dương, thiêu hết bát hoang."
    textfix["炙烤灵果，香气四溢。"] = "Linh quả nướng nóng, hương thơm tỏa khắp."
    textfix["炸鱼排，能有效恢复饥饿值。"] = "Miếng cá chiên, có thể phục hồi no bụng hiệu quả."
    textfix["炼体法坛，可锻筋骨。"] = "Pháp đàn luyện thể, có thể rèn gân cốt."
    textfix["炼制完成。"] = "Luyện chế hoàn thành."
    textfix["炼器鼎炸炉，毁于一旦。"] = "Luyện khí đỉnh nổ lò, huỷ trong một thoáng."
    textfix["炼器鼎，内蕴乾坤，可推演更精妙的法宝图谱。"] = "Luyện khí đỉnh, bên trong chứa đựng càn khôn, có thể suy diễn đồ phổ pháp bảo tinh diệu hơn."
    textfix["烈焰椒烹制的炖肉，食之如吞火，可暂驱寒毒。"] = "Thịt hầm được nấu với tiêu liệt diệm, ăn như nuốt lửa, có thể tạm thời xua đuổi hàn độc."
    textfix["烈阳宝石，内蕴纯阳火精，是炼制火系法宝的绝佳材料。"] = "Liệt Dương bảo thạch, bên trong hàm chứa thuần dương hỏa tinh, là vật liệu tuyệt hảo để luyện chế pháp bảo hỏa hệ."
    textfix["烟斗雕像，做工寻常。"] = "Tượng đá tẩu thuốc, làm thủ công thường."
    textfix["烤制后汁液未失，风味尚可。"] = "Sau khi nướng nước chưa mất, hương vị tạm được."
    textfix["烤土豆，香气扑鼻。"] = "Khoai tây nướng, hương thơm ngát mũi."
    textfix["烤大蒜，香气更浓。"] = "Tỏi nướng, hương thơm đậm hơn."
    textfix["烤榴莲，气味依旧，但口感有所变化。"] = "Sầu riêng nướng, mùi vẫn còn, nhưng cảm giác miệng có thay đổi."
    textfix["烤洋葱，甜味显现。"] = "Hành tây nướng, vị ngọt hiện ra."
    textfix["烤火鸡大餐，是节日的传统食物。"] = "Bữa đại tiệc gà lôi nướng, là thực phẩm truyền thống ngày lễ."
    textfix["烤火鸡，是节庆大餐的主菜。"] = "Gà lôi nướng, là món chính của bữa đại tiệc lễ hội."
    textfix["烤灵瓜，土灵之气更为温和。"] = "Linh dưa nướng, thổ linh chi khí ôn hòa hơn."
    textfix["烤炉正在工作中，食物正在烹制。"] = "Lò nướng đang hoạt động, thức ăn đang được chế biến."
    textfix["烤熟的仙人掌肉，清爽解渴。"] = "Thịt xương rồng nướng chín, mát mẻ giải khát."
    textfix["烤熟的桦栗果，可以食用。"] = "Quả dẻ bạch nướng chín, có thể ăn."
    textfix["烤熟的浆果，更易入口，利于消化。"] = "Quả mọng nướng chín, dễ ăn hơn, lợi tiêu hóa."
    textfix["烤熟的种子...连喂灵宠都不配"] = "Hạt giống nướng chín... cho linh thú ăn còn không xứng."
    textfix["烤熟的绿蘑菇，食用可恢复理智。"] = "Nấm xanh nướng chín, ăn có thể phục hồi lý trí."
    textfix["烤熟的肉块，是猪人喜爱的贡品。"] = "Thịt nướng chín, là cống phẩm người lợn ưa thích."
    textfix["烤熟的蓝蘑菇，药性转为温和，可恢复理智。"] = "Nấm xanh nướng chín, dược tính chuyển thành ôn hòa, có thể phục hồi lý trí."
    textfix["烤熟的象鼻，是一种食材。"] = "Vòi voi nướng chín, là một loại nguyên liệu."
    textfix["烤番茄，风味更佳。"] = "Cà chua nướng, hương vị tốt hơn."
    textfix["烤胡萝卜，味道更甜，易于消化。"] = "Cà rốt nướng, vị ngọt hơn, dễ tiêu hóa."
    textfix["烤芦笋，脆嫩可口。"] = "Măng tây nướng, giòn mềm ngon."
    textfix["烤茄子，是道简单的菜肴。"] = "Cà tím nướng, là món ăn đơn giản."
    textfix["烤萝卜，味道尚可。"] = "Củ cải nướng, hương vị tạm được."
    textfix["烤蝙蝠鼻？味道怪异。"] = "Mũi dơi nướng? Hương vị kỳ quái."
    textfix["烤西瓜，风味独特，但汁水较少。"] = "Dưa hấu nướng, hương vị độc đáo, nhưng nước ít hơn."
    textfix["烤辣椒，辣度更甚。"] = "Ớt nướng, độ cay hơn."
    textfix["烤过的火龙果，风味更佳。"] = "Thanh long đã nướng, hương vị tốt hơn."
    textfix["烤鱼？勉强果腹。"] = "Cá nướng? Miễn cưỡng lấp đầy bụng."
    textfix["烤鸟腿，是恢复体力的可靠食物。"] = "Chân chim nướng, là thức ăn đáng tin cậy để phục hồi thể lực."
    textfix["烧吧，正好给王某炼点怨火。"] = "Cứ cháy đi, đúng lúc cho Vương Mỗ luyện chút oán hỏa."
    textfix["烧毁殆尽，省我出手。"] = "Bị thiêu rụi, đỡ ta phải ra tay."
    textfix["烧焦的王座，徒留残骸。"] = "Ngai vàng bị thiêu, chỉ còn lại tàn tích."
    textfix["烧过的石材正好炼制阵基"] = "Thạch tài đã nung qua đúng lúc để luyện chế trận cơ."
    textfix["热可可，在寒冷天气里能带来温暖。"] = "Cacao nóng, trong thời tiết lạnh có thể mang lại sự ấm áp."
    textfix["烹饪完成，可以取用了。"] = "Nấu ăn hoàn thành, có thể lấy rồi."
    textfix["烹饪指南，记录了各种食物的制作方法。"] = "Hướng dẫn nấu ăn, ghi lại cách làm các loại thức ăn."
    textfix["烹饪锅因过度加热而损毁。"] = "Nồi nấu bị hỏng vì quá nóng."
    textfix["烹饪需要时间，耐心等待。"] = "Nấu ăn cần thời gian, hãy kiên nhẫn chờ đợi."
    textfix["焗烤红薯，味道甘甜。"] = "Khoai lang nướng phủ phô mai, vị ngọt bùi."
    textfix["焚天秘典？倒要看看有何玄机。"] = "Bí điển thiêu trời? Muốn xem có huyền cơ gì."
    textfix["焚尸灭迹，方为上策。"] = "Thiêu xác diệt tung tích, mới là thượng sách."
    textfix["焦木残椅，已无用处。"] = "Ghế gỗ cháy còn lại, đã không có ích."
    textfix["焦枯阴木，再无威胁。"] = "Âm mộc cháy khô, không còn mối đe dọa."
    textfix["焦黑残茧，灵气尽失。"] = "Kén thiêu đen tàn, linh khí tận mất."
    textfix["焦黑玩物，似有残魂依附。"] = "Đồ chơi cháy đen, dường như có tàn hồn bám víu."
    textfix["煎灵鹳蛋，香气扑鼻，营养丰富。"] = "Chiên trứng linh hạc, hương thơm ngát mũi, dinh dưỡng phong phú."
    textfix["煞气冲天，威势骇人。"] = "Sát khí xung thiên, uy thế hãi người."
    textfix["煞气隐现，不宜戏耍。"] = "Sát khí ẩn hiện, không nên nô đùa."
    textfix["照明火把，火光摇曳，仅能驱散方寸黑暗。"] = "Đuốc chiếu sáng, ánh lửa lắc lư, chỉ có thể xua tan bóng tối một vùng nhỏ."
    textfix["煮熟的人形生物的肉。"] = "Thịt sinh vật hình người nấu chín."
    textfix["煮熟的曼德拉草，药性已变，可安全食用。"] = "Cây Mandrake đã nấu chín, dược tính đã thay đổi, có thể an toàn ăn."
    textfix["煮熟的海带叶。"] = "Lá tảo biển nấu chín."
    textfix["煮熟的石果，可以食用了。"] = "Thạch quả nấu chín, có thể ăn rồi."
    textfix["熊獾雕像，栩栩如生，威势迫人。"] = "Tượng đá gấu lửng, sinh động như thật, uy thế bức người."
    textfix["熔岩竞技场的传送门已经开启。"] = "Cổng truyền tống đấu trường nham thạch đã mở."
    textfix["熔融的琉璃珠，内蕴一丝火灵，可作探宝之用。"] = "Hạt thủy tinh tan chảy, bên trong hàm chứa một tia hỏa linh, có thể dùng để thăm dò bảo vật."
    textfix["熟怪物肉，毒性稍减，但仍需谨慎食用。"] = "Thịt quái vật chín, độc tính hơi giảm, nhưng vẫn cần cẩn thận ăn."
    textfix["熟月亮蘑菇？谨慎食用。"] = "Nấm mặt trăng nấu chín? Cẩn thận ăn."
    textfix["熟肉，基本的食物来源。"] = "Thịt chín, nguồn thức ăn cơ bản."
    textfix["熟藤壶，可食用。"] = "Hà nấu chín, có thể ăn."
    textfix["熟虾，稍具灵气。"] = "Tôm chín, có chút linh khí."
    textfix["熟蛙腿，可以安全食用。"] = "Đùi ếch chín, có thể an toàn ăn."
    textfix["熟鱼屑，聊胜于无。"] = "Vụn cá chín, còn hơn không có gì."
    textfix["熟鱼，比生鱼更安全可口。"] = "Cá chín, an toàn và ngon hơn cá sống."
    textfix["熟鸟蛋，更易保存与食用。"] = "Trứng chim chín, dễ bảo quản và ăn hơn."
    textfix["燥热平原，火土之气旺盛。"] = "Thảo nguyên khô nóng, hỏa thổ chi khí hưng vượng."
    textfix["燧石，是制作工具和武器的基本材料。"] = "Đá lửa, là nguyên liệu cơ bản để làm công cụ và vũ khí."
    textfix["爆米花，是玉米受热后的产物。"] = "Bỏng ngô, là sản phẩm của ngô khi bị nung nóng."
    textfix["爆裂属性的妖鱼？有点意思。"] = "Yêu ngư thuộc tính bùng nổ? Có chút thú vị."
    textfix["爆裂海草？小心为上。"] = "Cỏ biển bùng nổ? Cẩn thận là thượng sách."
    textfix["爪落空了，水下暗流颇急。"] = "Vuốt quào hụt, dòng chảy ngầm dưới nước khá mạnh."
    textfix["牛已酣睡，此时不宜惊扰。"] = "Bò đang ngủ say, lúc này không nên quấy rầy."
    textfix["牛毛厚实，可纺线织布，御寒之物。"] = "Lông bò dày thực, có thể kéo sợi dệt vải, vật chống lạnh."
    textfix["牛毛尽失，需待其重新生长。"] = "Lông bò đã mất hết, cần đợi mọc lại."
    textfix["牛角帽，可避风寒，亦可混淆牛群感知。"] = "Mũ sừng bò, có thể tránh gió lạnh, cũng có thể gây nhầm lẫn cảm nhận đàn bò."
    textfix["牛角，吹响它可以召唤皮弗娄牛。"] = "Sừng bò, thổi lên có thể triệu hoán bò Beefalo."
    textfix["物品已干，保存完成。"] = "Vật phẩm đã khô, bảo quản hoàn thành."
    textfix["物品正在风干。"] = "Vật phẩm đang phơi khô."
    textfix["特制灵肥，能加速灵植生长，滋养地力。"] = "Linh phân đặc chế, có thể tăng tốc sinh trưởng linh thực, tưới dưỡng địa lực."
    textfix["犁地草？田间杂草。"] = "Cỏ cày? Cỏ dại trên đồng."
    textfix["犬牙皮袄，保暖效果尚可，样式古朴。"] = "Áo da răng chó, hiệu quả giữ ấm tạm được, kiểu dáng cổ phác."
    textfix["犬齿锋锐，带有一丝污秽之气，可淬炼阴毒法器。"] = "Răng chó sắc bén, mang theo khí ô uế, có thể tôi luyện âm độc pháp khí."
    textfix["狡兔三窟，此洞府灵气充裕，乃修炼宝地。"] = "Thỏ ranh ba hang, động phủ này linh khí dồi dào, là bảo địa tu luyện."
    textfix["独眼巨鹿雕像，散发着不祥的气息。"] = "Tượng đá nai một mắt khổng lồ, tỏa ra khí tức bất tường."
    textfix["独眼巨鹿，寒冬的灾厄化身，力量惊人。"] = "Nai khổng lồ một mắt, hiện thân tai họa mùa đông, sức mạnh kinh ngạc."
    textfix["独食方能细品其中灵蕴。"] = "Ăn một mình mới có thể cảm nhận linh uẩn bên trong."
    textfix["猎物脱网，功亏一篑。"] = "Con mồi thoát lưới, công thiếu một sàng."
    textfix["猎犬的尸体在燃烧。"] = "Xác chó săn đang cháy."
    textfix["猎犬的尸体正在发生异变！"] = "Xác chó săn đang xảy ra dị biến!"
    textfix["猎犬的巢穴，会不断生出新的猎犬。"] = "Tổ chó săn, sẽ liên tục sinh ra chó săn mới."
    textfix["猎犬的骨头。"] = "Xương của chó săn."
    textfix["猎犬，会主动攻击，常成群出现。"] = "Chó săn, sẽ chủ động tấn công, thường xuất hiện theo đàn."
    textfix["猪人信物，是与其进行交易的凭证。"] = "Tín vật người lợn, là bằng chứng để giao dịch với họ."
    textfix["猪人勇士，身穿熔岩铠甲，非常强大。"] = "Dũng sĩ người lợn, mặc giáp nham thạch, rất mạnh mẽ."
    textfix["猪人护卫，妖气外放，警惕性极高。"] = "Vệ binh heo người, yêu khí phóng ra ngoài, cảnh giác cực cao."
    textfix["猪人毙命，妖气散尽。"] = "Heo người mất mạng, yêu khí tản hết."
    textfix["猪人祭坛，供奉着象征富足的图腾。"] = "Tế đàn người lợn, thờ phụng đồ án tượng trưng cho giàu có."
    textfix["猪人铸币，可在猪村流通使用。"] = "Tiền đúc người lợn, có thể lưu thông sử dụng ở làng lợn."
    textfix["猪妖之王？气息浑浊，似被禁锢于此，靠贡品维系存在。"] = "Vương của heo yêu? Khí tức hỗn trọc, dường như bị giam cầm ở đây, dựa vào cống phẩm để duy trì sự tồn tại."
    textfix["猪妖之皮，坚韧异常，可制甲胄。"] = "Da heo yêu, kiên cường khác thường, có thể làm giáp trụ."
    textfix["猪妖图腾火柱，火光中似有低语，扰人心神。"] = "Cột lửa đồ tô tem heo yêu, trong ánh lửa dường như có tiếng thì thầm, quấy rầy tâm thần."
    textfix["猪妖守卫，煞气颇重，修为不弱。"] = "Vệ binh heo yêu, sát khí khá nặng, tu vi không yếu."
    textfix["猪妖居于屋内，气息平稳。"] = "Heo yêu ở trong nhà, khí tức bình ổn."
    textfix["猪妖巢穴被焚，只余残垣断壁。"] = "Tổ heo yêu bị thiêu, chỉ còn tường gạch đổ nát."
    textfix["猪妖巢穴，以灵木搭建，结构粗陋却蕴含一丝妖力。"] = "Tổ heo yêu, được xây bằng linh mộc, cấu trúc thô sơ nhưng ẩn chứa một sợi yêu lực."
    textfix["猪妖皮炼制的行囊，容量巨大，但背负时会阻滞灵气运转。"] = "Túi đựng được luyện từ da heo yêu, dung lượng khổng lồ, nhưng khi đeo sẽ cản trở linh khí vận hành."
    textfix["猪妖祭坛？血肉供奉，腥气扑鼻，定非善地。"] = "Tế đàn heo yêu? Cúng bái huyết nhục, mùi tanh xông mũi, chắc chắn không phải nơi lành."
    textfix["猪妖，下次必取你妖核。"] = "Heo yêu, lần sau chắc chắn lấy yêu hạch của ngươi."
    textfix["猪首法器已毁，其上怨念亦随之消散。"] = "Pháp khí đầu heo đã hủy, oán niệm trên đó cũng tiêu tán theo."
    textfix["猴妖诅咒，也敢沾染本尊仙体？"] = "Lời nguyền hầu yêu, cũng dám nhiễm lên tiên thể của bổn tôn?"
    textfix["猴尾灵草，可入丹药。"] = "Linh thảo đuôi khỉ, có thể vào đan dược."
    textfix["猴族图腾，供奉先祖。"] = "Đồ án tộc khỉ, thờ phụng tổ tiên."
    textfix["猴窝焚毁，清净许多。"] = "Tổ khỉ bị thiêu, yên tĩnh nhiều hơn."
    textfix["猴群大副，头戴华冠。"] = "Đại phó đàn khỉ, đầu đội hoa quan."
    textfix["猴群女王，统御一方。"] = "Nữ vương đàn khỉ, thống trị một phương."
    textfix["玄冰寒气，冻结虚空。"] = "Hàn khí huyền băng, đông kết hư không."
    textfix["玄冰消融，灵气散逸，已不堪大用。"] = "Huyền băng tan chảy, linh khí tán đi, đã không đủ dùng cho việc lớn."
    textfix["玄冰灵酪，甘甜沁腑，然寒性过重，不可多食。"] = "Pho mát linh huyền băng, ngọt thanh thấm vào phủ tạng, nhưng hàn tính quá nặng, không thể ăn nhiều."
    textfix["玄冰矿脉，寒气刺骨，是炼制冰系法器的材料。"] = "Huyền băng khoáng mạch, hàn khí thấu xương, là vật liệu luyện chế pháp khí băng hệ."
    textfix["玄妙音律，非比寻常。"] = "Âm luật huyền diệu, phi thường."
    textfix["玄玉柱，上接清气，下镇地脉，可作山门之基。"] = "Trụ huyền ngọc, trên tiếp thanh khí, dưới trấn địa mạch, có thể làm nền tảng cổng núi."
    textfix["玄玉树苗，灵气内敛，待其成林。"] = "Cây con huyền ngọc, linh khí thu liễm, đợi nó thành rừng."
    textfix["玄玉灌木，金刚不坏，可挡灾劫。"] = "Bụi huyền ngọc, kim cương bất hoại, có thể chặn tai kiếp."
    textfix["玄玉石，乃炼制防御法器的上佳材料。"] = "Huyền ngọc thạch, là nguyên liệu thượng hạng để luyện pháp khí phòng thủ."
    textfix["玄玉神木，万载不朽，非仙剑不可伤其分毫。"] = "Thần mộc huyền ngọc, vạn năm không mục, không có tiên kiếm không thể tổn thương dù một phân."
    textfix["玄石哑铃，重若千钧。"] = "Tạ huyền thạch, nặng như ngàn cân."
    textfix["玄石重铠，防御惊人，但行动不便。"] = "Giáp nặng huyền thạch, phòng thủ kinh ngạc, nhưng hành động bất tiện."
    textfix["玄铁现世，幽冥显形。"] = "Huyền sắt hiện thế, u minh hiển hình."
    textfix["玄铁矿石？不，只是凡石，内含杂质颇多。"] = "Huyền sắt khoáng thạch? Không, chỉ là phàm thạch, bên trong chứa nhiều tạp chất."
    textfix["玄阴之气，竟能透我护体罡风。"] = "Huyền âm chi khí, thực sự có thể xuyên qua cương phong hộ thể của ta."
    textfix["玉兔灯盏，灵气充盈。"] = "Đèn ngọc thỏ, linh khí đầy ắp."
    textfix["玉兔灯组件，需妥善安置。"] = "Cấu kiện đèn ngọc thỏ, cần đặt ổn thỏa."
    textfix["玉盆肉芝...可作观赏之用"] = "Nhục chi trong chậu ngọc... có thể dùng để thưởng lãm."
    textfix["玉石弹丸，尚可一用。"] = "Đạn đá ngọc, tạm có thể dùng một lần."
    textfix["玉米硬糖，甜味较淡。"] = "Kẹo cứng bắp ngô, vị ngọt tương đối nhạt."
    textfix["玉米种子，需种于农田。"] = "Hạt giống ngô, cần trồng trên ruộng nương."
    textfix["玉米软糖，有着独特的甜味。"] = "Kẹo dẻo bắp ngô, có vị ngọt đặc trưng."
    textfix["玉米，可作主食或加工。"] = "Ngô, có thể làm lương thực chính hoặc chế biến."
    textfix["玉粟灵汤，饮之清心。"] = "Linh thang ngọc túc, uống vào thanh tâm."
    textfix["玩具蛇，形似某种毒蟒。"] = "Rắn đồ chơi, hình dạng giống loài trăn độc nào đó."
    textfix["玩火的小丫头，莫要引火烧身"] = "Tiểu cô nương chơi lửa, chớ kéo lửa tự đốt."
    textfix["环境过热，蛋内水分流失，恐伤及雏鸟根基。"] = "Môi trường quá nóng, nước bên trong trứng mất đi, e sẽ tổn thương căn cơ của chim non."
    textfix["现在不是摆放这种食物的时节。"] = "Bây giờ không phải mùa bày loại thức ăn này."
    textfix["玻璃刀，专门用于切割玻璃类材料。"] = "Dao thủy tinh, chuyên dùng để cắt vật liệu loại kính."
    textfix["珍珠开裂，灵气外泄。"] = "Ngọc trai nứt vỡ, linh khí ngoại tiết."
    textfix["珍珠？蕴含水灵气。"] = "Ngọc trai? Hàm chứa thủy linh khí."
    textfix["琉璃化刃，尚可一观。"] = "Lưu ly hóa thành lưỡi, còn đáng một nhìn."
    textfix["瓶中信？或有机密。"] = "Thư trong chai? Hoặc có cơ mật."
    textfix["甘露已尽，需再汲取。"] = "Cam lộ đã cạn, cần lấy thêm."
    textfix["甜腻之物，凡人所好。"] = "Vật ngọt béo, phàm nhân ưa thích."
    textfix["甜茶？解渴饮品。"] = "Trà ngọt? Đồ uống giải khát."
    textfix["生机已断，化为焦炭。"] = "Sinh cơ đã đứt, hóa thành than."
    textfix["生蛙腿，需要烹饪。"] = "Đùi ếch sống, cần nấu chín."
    textfix["生长中的胡萝卜。"] = "Cà rốt đang sinh trưởng."
    textfix["生鱼肉，连妖兽都不屑一顾。"] = "Thịt cá sống, ngay cả yêu thú cũng không thèm nhìn."
    textfix["生鸟腿，需要烹饪后才能安全食用。"] = "Chân chim sống, cần nấu chín mới có thể an toàn ăn."
    textfix["用于搭建反应训练设施的组件。"] = "Linh kiện để dựng cơ sở huấn luyện phản ứng."
    textfix["用于搭建方向训练设施的组件。"] = "Linh kiện để dựng cơ sở huấn luyện phương hướng."
    textfix["用于搭建称量胡萝卜鼠体重装置的组件。"] = "Linh kiện để dựng thiết bị cân cân nặng chuột cà rốt."
    textfix["用于搭建耐力训练设施的组件。"] = "Linh kiện để dựng cơ sở huấn luyện sức bền."
    textfix["用于搭建速度训练设施的组件。"] = "Linh kiện để dựng cơ sở huấn luyện tốc độ."
    textfix["用于训练胡萝卜鼠反应能力的设施。"] = "Cơ sở để huấn luyện khả năng phản ứng của chuột cà rốt."
    textfix["用于训练胡萝卜鼠方向感的设施。"] = "Cơ sở để huấn luyện cảm giác phương hướng của chuột cà rốt."
    textfix["用于训练胡萝卜鼠耐力的设施。"] = "Cơ sở để huấn luyện sức bền của chuột cà rốt."
    textfix["用于训练胡萝卜鼠速度的设施。"] = "Cơ sở để huấn luyện tốc độ của chuột cà rốt."
    textfix["用姜饼搭建的可食用小屋。"] = "Nhà nhỏ có thể ăn được xây từ bánh gừng."
    textfix["用饼干切割机外壳制成的帽子，能提供一些防护。"] = "Mũ làm từ vỏ máy cắt bánh quy, có thể cung cấp một số phòng hộ."
    textfix["甲壳坚若玄铁，力大无穷，小心应对。"] = "Vỏ giáp cứng như huyền thiết, sức mạnh vô cùng, cẩn thận ứng phó."
    textfix["甲壳碎片，质地坚硬，可作炼器辅材。"] = "Mảnh vỡ vỏ giáp, chất liệu cứng, có thể làm phụ liệu luyện khí."
    textfix["甲壳龟，背上的尖刺是它的武器。"] = "Rùa giáp, gai nhọn trên lưng là vũ khí của nó."
    textfix["电鳗？其电力可淬炼法宝。"] = "Lươn điện? Điện lực của nó có thể tôi luyện pháp bảo."
    textfix["画框精美，可裱丹青。"] = "Khung tranh tinh xảo, có thể bọc tranh."
    textfix["界域法则不同，此图在此界无效。"] = "Pháp tắc giới vực khác nhau, bản đồ này vô hiệu tại giới này."
    textfix["番茄种子。"] = "Hạt giống cà chua."
    textfix["番茄，酸甜可口。"] = "Cà chua, chua ngọt ngon miệng."
    textfix["疗伤变异物，效果存疑。"] = "Vật biến dị trị thương, hiệu quả còn nghi."
    textfix["疗伤蜘蛛？倒是罕见。"] = "Nhện trị thương? Lại hiếm thấy."
    textfix["疗伤音律？效果有限。"] = "Âm luật trị thương? Hiệu quả hữu hạn."
    textfix["病弱草木，也配污王某法眼？"] = "Cây cỏ ốm yếu, cũng đáng làm bẩn pháp nhãn của Vương Mỗ?"
    textfix["白日阳气正盛，非休眠之时。"] = "Ban ngày dương khí đang thịnh, không phải lúc ngủ nghỉ."
    textfix["白色玉石战车棋子。"] = "Quân cờ chiến xa ngọc trắng."
    textfix["白色玉石棋子，是某种棋局的一部分。"] = "Quân cờ ngọc trắng, là một phần của ván cờ nào đó."
    textfix["白色玉石骑士棋子。"] = "Quân cờ kỵ sĩ ngọc trắng."
    textfix["白袍猪人战士，眼神锐利。"] = "Chiến sĩ người lợn áo trắng, mắt sắc bén."
    textfix["白骨成甲，死气缭绕。"] = "Bạch cốt thành giáp, tử khí vây quanh."
    textfix["百果灵籽混杂，可快速补充元气，利于长途跋涉。"] = "Linh tử trăm quả lẫn lộn, có thể nhanh chóng bổ sung nguyên khí, có lợi cho đường dài."
    textfix["百灵蔬烩，虽无肉腥，却别有一番清韵，可涤荡肠胃浊气。"] = "Trăm linh sơ hội, tuy không tanh thịt, nhưng thanh tao riêng biệt, có thể tẩy trừ trọc khí trong ruột."
    textfix["百炼草绳，坚韧异常，可缚低阶妖兽。"] = "Thảo thằng bách luyện, cứng chắc dị thường, có thể trói buộc yêu thú hạ giai."
    textfix["百炼钢绒，质地特殊，或可用于打磨法器。"] = "Thép nhung bách luyện, chất địa đặc biệt, hoặc có thể dùng để mài pháp khí."
    textfix["百花清拌，蕴含一丝草木精粹，可清心明目。"] = "Trộn thanh trăm hoa, ẩn chứa một sợi tinh túy thảo mộc, có thể thanh tâm sáng mắt."
    textfix["百花灵气所凝，可制香囊，亦可作为低阶丹药的引子。"] = "Linh khí trăm hoa ngưng tụ, có thể làm túi thơm, cũng có thể làm dẫn tử cho đan dược cấp thấp."
    textfix["百音傀儡戏，乐声杂乱，闻之令人心神不宁。"] = "Kịch rối trăm âm, tiếng nhạc hỗn loạn, nghe vào khiến tâm thần bất an."
    textfix["皓月剑锋，斩妖除魔。"] = "Kiếm phong hạo nguyệt, chém yêu trừ ma."
    textfix["皮上残存着吞噬之力。"] = "Trên da còn sót sức mạnh hút nuốt."
    textfix["皮弗娄牛毛制成的抱枕，保暖性好。"] = "Gối ôm làm từ lông bò Beefalo, độ giữ ấm tốt."
