    textfix["虚惊一场，并无陷阱。"] = "Sợ hão thôi, không có bẫy."
    textfix["虚空法袍，防御惊人。"] = "Pháp bào hư không, phòng thủ kinh người."
    textfix["虚空玄丝，幽冥织就。"] = "Huyền ty hư không, u minh dệt nên."
    textfix["虚空织补材料。"] = "Vật liệu vá víu hư không."
    textfix["虚空镰刀，收割生灵。"] = "Lưỡi hái hư không, thu hoạch sinh linh."
    textfix["虚空风帽，可蔽天机。"] = "Phong mạo hư không, có thể che thiên cơ."
    textfix["虫卵处于适宜的孵化温度，正在活跃变化。"] = "Trứng sâu đang ở nhiệt độ ấp nở thích hợp, đang thay đổi tích cực."
    textfix["虫形软糖，口感Q弹。"] = "Kẹo dẻo hình giun, khẩu cảm dai dẻo."
    textfix["虫洞已经激活，可以通行了。"] = "Lỗ sâu đã kích hoạt, có thể thông hành rồi."
    textfix["虫豸之辈，也配本尊出手？！"] = "Loại trùng bọ, cũng xứng để bổn tôn ra tay?!"
    textfix["虾妖？可取甲炼器。"] = "Tôm yêu? Có thể lấy giáp luyện khí."
    textfix["虾汤，勉强算药膳。"] = "Canh tôm, miễn cưỡng tính là dược thiện."
    textfix["虾餐，尚可入口。"] = "Bữa tôm, tạm được vào miệng."
    textfix["蚁狮甲壳制成的头盔，似乎能影响大地。"] = "Mũ giáp được chế từ vỏ Antlion, dường như có thể ảnh hưởng đến đại địa."
    textfix["蚁狮雕像，沙地中的潜伏者。"] = "Tượng đá Antlion, kẻ ẩn phục trong cát."
    textfix["蛋壳灵光流转，破壳在即。"] = "Linh quang vỏ trứng lưu chuyển, sắp vỡ vỏ."
    textfix["蛋奶酒，一种口感浓郁的节日特饮。"] = "Rượu sữa trứng, một loại đặc sản uống ngày lễ hương vị nồng đậm."
    textfix["蛋白糖霜蛋糕，口感轻盈。"] = "Bánh kem lòng trắng trứng, khẩu cảm nhẹ nhàng."
    textfix["蛋篮？游戏道具。"] = "Giỏ trứng? Đạo cụ trò chơi."
    textfix["蛙腿三明治，能提供不错的饱食度。"] = "Bánh mì kẹp đùi ếch, có thể cung cấp no bụng không tệ."
    textfix["蛛卵囊，生机勃勃，若处置不当恐生祸端。"] = "Túi trứng nhện, sinh cơ sung mãn, nếu xử lý không đúng e sẽ sinh họa."
    textfix["蛛后降临！此妖已修炼成精，统御万千蛛子蛛孙。"] = "Nhện hậu giáng lâm! Yêu vật này đã tu luyện thành tinh, thống trị vạn nghìn nhện con cháu."
    textfix["蛛妖精丝？倒是炼制捆仙索的好材料"] = "Tơ tinh của nhện yêu? Lại là vật liệu tốt để luyện chế Côn Tiên Sách."
    textfix["蛛将已毙，其毒囊尚可一用。"] = "Nhện tướng đã chết, độc nang của nó vẫn có thể dùng một lần."
    textfix["蛛将蛰伏，气息内敛，此时不宜惊动。"] = "Nhện tướng đang nằm im, khí tức nội liễm, lúc này không nên kinh động."
    textfix["蛛巢装饰，无聊之举。"] = "Trang trí sào nhện, hành động vô liêu."
    textfix["蛛毒变异物，危险。"] = "Vật biến dị độc nhện, nguy hiểm."
    textfix["蛛秽缠石，妖气弥漫。"] = "Nhện bẩn quấn đá, yêu khí tràn ngập."
    textfix["蛛网密布，内藏杀机。"] = "Màng nhện dày đặc, bên trong ẩn chứa sát cơ."
    textfix["蛛魔巢穴，阴煞之气汇聚，内藏蛛卵无数。"] = "Sào huyệt của nhện ma, âm sát chi khí hội tụ, bên trong chứa vô số trứng nhện."
    textfix["蛛魔战将，甲壳坚硬，獠牙淬毒，需谨慎应对。"] = "Chiến tướng nhện ma, giáp cứng, nanh có độc tôi, cần thận trọng ứng phó."
    textfix["蛟龙幼体...食之大补！"] = "Long giao ấu thể... ăn vào đại bổ!"
    textfix["蛮力尚可...可炼为护法傀儡"] = "Sức mạnh cũng được... có thể luyện thành hộ pháp bù nhìn."
    textfix["蛰伏休憩中。"] = "Đang ẩn nấp nghỉ ngơi."
    textfix["蜂后气息凝于冠冕，可号令蜂群？"] = "Khí tức ong chúa ngưng tụ tại mũ, có thể hô lệnh đàn ong?"
    textfix["蜂妖亲卫，獠牙带毒，攻势凌厉。"] = "Thân vệ ong yêu, nanh độc mang theo, tấn công mãnh liệt."
    textfix["蜂妖听令！为吾而战！"] = "Phong yêu nghe lệnh! Chiến đấu vì ta!"
    textfix["蜂妖王庭，煞气冲天，内蕴凶险。"] = "Triều đình của ong yêu, sát khí xung thiên, bên trong ẩn chứa hung hiểm."
    textfix["蜂巢汲取地脉生机，正在壮大。"] = "Tổ ong hút sinh cơ địa mạch, đang lớn mạnh."
    textfix["蜂巢，里面可能还残留着蜂蜜。"] = "Tổ ong, bên trong có thể còn sót lại mật ong."
    textfix["蜂毒虽微，扰人清修。"] = "Độc ong tuy nhỏ, nhưng quấy rầy tu luyện."
    textfix["蜂王灵浆，一滴可延年益寿，乃疗伤圣药。"] = "Phong vương linh tương, một giọt có thể kéo dài tuổi thọ, là thánh dược trị thương."
    textfix["蜂王雕像，统御蜂群的王者之姿。"] = "Tượng đá ong chúa, tư thế vương giả cai quản đàn ong."
    textfix["蜂箱已毁，可惜了这些蜂群。"] = "Tổ ong đã hủy, tiếc cho đàn ong này."
    textfix["蜂箱已满，蜜露尚可，取之用之。"] = "Tổ ong đã đầy, mật lộ tạm được, lấy mà dùng."
    textfix["蜂箱被焚，可惜。"] = "Tổ ong bị thiêu, tiếc thay."
    textfix["蜂箱运作如常，无需过多关注。"] = "Tổ ong vận hành bình thường, không cần chú ý quá nhiều."
    textfix["蜂箱？且看能产何蜜。"] = "Tổ ong? Hãy xem có thể sản xuất mật gì."
    textfix["蜂群化妖，其主修为深不可测，当慎之。"] = "Đàn ong hóa yêu, tu vi của chúa của nó sâu không thể đo lường, cần thận trọng."
    textfix["蜂群法咒，扰敌心神。"] = "Pháp chú bầy ong, quấy rối tâm thần địch."
    textfix["蜂胶积聚，已成妖巢之基。"] = "Keo ong tích tụ, đã thành nền tảng tổ yêu."
    textfix["蜂蜜 nuggets，是道不错的点心。"] = "Nuggets mật ong, là món điểm tâm không tệ."
    textfix["蜂蜜已满，可取之用。"] = "Mật ong đã đầy, có thể lấy dùng."
    textfix["蜂蜜，是种多用途的甜味剂和食材。"] = "Mật ong, là loại chất làm ngọt và thực phẩm đa dụng."
    textfix["蜂蜡灵纸，可保药材灵性不失，常用于包裹丹丸。"] = "Giấy linh sáp ong, có thể bảo linh tính dược liệu không mất, thường dùng để gói viên đan."
    textfix["蜂蜡，性稳，可防腐，亦可用于制作烛火。"] = "Sáp ong, tính ổn định, có thể phòng mục, cũng có thể dùng để làm nến."
    textfix["蜂针含毒，需以灵力禁锢。"] = "Kim ong chứa độc, cần dùng linh lực giam cầm."
    textfix["蜈蚣空壳？已无价值。"] = "Vỏ rỗng rết? Đã không còn giá trị."
    textfix["蜘蛛分泌物，可入药。"] = "Chất tiết của nhện, có thể làm thuốc."
    textfix["蜘蛛尸身，毒腺尚存，可入药。"] = "Tử thi nhện, độc tuyến vẫn còn, có thể làm thuốc."
    textfix["蜘蛛形态的戒指，或与蛛妖有所感应。"] = "Nhẫn hình dạng nhện, hoặc có cảm ứng với nhện yêu."
    textfix["蜘蛛形状的节日装饰。"] = "Đồ trang trí ngày lễ hình nhện."
    textfix["蜘蛛形状的软糖，造型有趣。"] = "Kẹo dẻo hình nhện, tạo hình thú vị."
    textfix["蜘蛛毒囊，是炼制解毒丹或剧毒的重要材料。"] = "Độc nang nhện, là vật liệu quan trọng để luyện chế giải độc đan hoặc kịch độc."
    textfix["蜜已盈箱，当及时收取，以免浪费。"] = "Mật đã đầy hộp, nên thu hoạch kịp thời, tránh lãng phí."
    textfix["蜜汁火腿，能提供大量的饱食度。"] = "Thịt muối mật ong, có thể cung cấp no bụng nhiều."
    textfix["蜜满蜂箱，收获之时。"] = "Tổ ong đầy mật, đến lúc thu hoạch."
    textfix["蜜量渐增，尚未可取。"] = "Lượng mật dần tăng, chưa thể lấy."
    textfix["蝎子，尾部的钩刺含有剧毒。"] = "Bọ cạp, gai móc đuôi chứa kịch độc."
    textfix["蝙蝠丘穴？小心有兽。"] = "Hang gò dơi? Cẩn thận có thú."
    textfix["蝙蝠形状的节日装饰。"] = "Đồ trang trí ngày lễ hình dơi."
    textfix["蝙蝠鼻帽？防寒之用。"] = "Mũ mũi dơi? Dùng để chống lạnh."
    textfix["蝙蝠鼻？奇特材料。"] = "Mũi dơi? Vật liệu kỳ lạ."
    textfix["蝴蝶，翅翼蕴含生机，可提炼精华。"] = "Bướm, cánh ẩn chứa sinh cơ, có thể chiết xuất tinh hoa."
    textfix["蝶翼轻薄，是炼制某些药剂的材料。"] = "Cánh bướm mỏng nhẹ, là nguyên liệu luyện một số dược phẩm."
    textfix["融合暗影，凶煞异常。"] = "Ám ảnh dung hợp, hung sát dị thường."
    textfix["蟠龙杖，踏遍幽冥。"] = "Trượng bàn long, bước khắp u minh."
    textfix["蟹王？体型倒是不小。"] = "Vua cua? Thân hình lại không nhỏ."
    textfix["蟹钳？可作材料。"] = "Càng cua? Có thể làm vật liệu."
    textfix["血光笼罩，凶兆显现。"] = "Huyết quang bao phủ, hung triệu hiển hiện."
    textfix["血囊之内，精血混杂妖气，是炼制邪门丹药的材料。"] = "Bên trong túi máu, tinh huyết lẫn yêu khí, là nguyên liệu để luyện đan dược tà môn."
    textfix["血肉精华，可补气血，然杂质颇多。"] = "Tinh hoa huyết nhục, có thể bổ khí huyết, nhưng tạp chất khá nhiều."
    textfix["血蚊扰人，不堪其烦。"] = "Muỗi máu quấy rầy, không chịu nổi."
    textfix["衣架傀儡，毫无灵性。"] = "Quái lỗi giá áo, hoàn toàn không có linh tính."
    textfix["衣柜被烧毁了。"] = "Tủ quần áo bị thiêu huỷ."
    textfix["衣柜起火了。"] = "Tủ quần áo bốc lửa."
    textfix["衣柜，可以用来更换衣物和装扮。"] = "Tủ quần áo, có thể dùng để thay đổi trang phục và trang điểm."
    textfix["衣橱起火，需先灭火。"] = "Tủ quần áo bốc lửa, cần dập lửa trước."
    textfix["衣衫尽湿，有碍观瞻。"] = "Áo quần ướt hết, ảnh hưởng đến diện mạo."
    textfix["袖中藏光，倒也有趣。"] = "Ẩn ánh sáng trong tay áo, cũng khá thú vị."
    textfix["被主教的能量光束击中了。"] = "Bị chùm tia năng lượng của giám mục đánh trúng."
    textfix["被封印的石像，灵气内敛"] = "Thạch tượng bị phong ấn, linh khí nội liễm."
    textfix["被诅咒的战车，怨念不散。"] = "Chiến xa bị nguyền, oán niệm chẳng tan."
    textfix["装哑的刺客...倒是适合做暗子"] = "Thích khách giả câm... lại thích hợp làm ám tử."
    textfix["装甲熊獾雕像，厚重的甲壳下是狂暴的力量。"] = "Tượng đá gấu lửng giáp, dưới vỏ giáp dày nặng là sức mạnh cuồng bạo."
    textfix["装神弄鬼的石雕。"] = "Thạch điêu giả vờ thần thánh."
    textfix["裹糖的葡萄干，甜中带酸。"] = "Nho khô bọc đường, ngọt xen chua."
    textfix["西北方，乾金之位。"] = "Tây bắc, vị trí Kiền Kim."
    textfix["西南方，坤土之向。"] = "Tây nam, hướng Khôn Thổ."
    textfix["西方战神的黄金矛？其上附有破甲真言。"] = "Mâu vàng của chiến thần phương Tây? Trên đó gắn phá giáp chân ngôn."
    textfix["西方，属金，主肃降。"] = "Phía tây, thuộc kim, chủ túc giáng."
    textfix["西洋傀儡，异域风情。"] = "Quái lỗi tây dương, phong tình ngoại quốc."
    textfix["西洋图谱，异域风情。"] = "Đồ phổ tây dương, phong tình ngoại quốc."
    textfix["西瓜皮帽子，戴起来有清凉感，但容易弄脏。"] = "Mũ vỏ dưa hấu, đội lên có cảm giác mát, nhưng dễ bẩn."
    textfix["西瓜种子，需种于温暖之地。"] = "Hạt giống dưa hấu, cần trồng ở nơi ấm áp."
    textfix["西瓜，多汁解渴的夏季水果。"] = "Dưa hấu, trái cây mùa hè nhiều nước giải khát."
    textfix["见冠如见其主。"] = "Thấy mũ như thấy chủ."
    textfix["观天仪遭雷火焚毁，天机难测。"] = "Quan thiên nghi bị lôi hỏa thiêu hủy, thiên cơ khó đoán."
    textfix["观天仪，可预判天象变化，水灵之气汇聚则指针偏转。"] = "Quan thiên nghi, có thể dự đoán biến đổi thiên tượng, thủy linh chi khí tụ tập thì kim chỉ lệch."
    textfix["解离法杖...竟含空间法则"] = "Giải ly pháp trượng... thực sự chứa không gian pháp tắc."
    textfix["解鞍角，轻轻一触便可卸下鞍具符文。"] = "Giải an giác, nhẹ nhàng một chạm là có thể tháo phù văn an cụ."
    textfix["触动了机关，需多加小心。"] = "Đã kích động cơ quan, cần cẩn thận hơn."
    textfix["触手吸盘皮，质地柔韧，可炼制防水符箓。"] = "Da miệng hút xúc tu, chất địa dẻo dai, có thể luyện chế phù lục chống nước."
    textfix["触手妖王的子体，除之不尽，烦不胜烦。"] = "Tử thể của yêu vương xúc tu, trừ không hết, phiền không thể nói."
    textfix["触手妖王？其本体深藏地下，难以根除。"] = "Yêu vương xúc tu? Bản thể của nó ẩn sâu dưới đất, khó mà nhổ tận gốc."
    textfix["触手妖群栖之地，步步杀机。"] = "Đất ở của đám yêu xúc tu, mỗi bước đều có sát cơ."
    textfix["触手形状的棒棒糖，造型有些怪异。"] = "Kẹo que hình xúc tu, tạo hình hơi kỳ quái."
    textfix["触手形状的节日装饰。"] = "Đồ trang trí ngày lễ hình xúc tu."
    textfix["触手毒刺，蕴含麻痹剧毒，可淬于兵器之上。"] = "Gai xúc tu, hàm chứa kịch độc tê liệt, có thể tôi lên binh khí."
    textfix["警戒脉冲？避开为妙。"] = "Xung cảnh giới? Tránh đi là hay."
    textfix["让王某为你重燃命魂之火"] = "Để Vương Mỗ giúp ngươi tái thiêu mệnh hồn chi hỏa."
    textfix["记忆游戏套装？考验记性。"] = "Bộ trò chơi ghi nhớ? Kiểm tra trí nhớ."
    textfix["记忆游戏？需集中精神。"] = "Trò chơi ghi nhớ? Cần tập trung tinh thần."
    textfix["论道法坛，群贤毕至。"] = "Pháp đàn luận đạo, anh tài tề tựu."
    textfix["诅咒弹丸？小心反噬。"] = "Đạn nguyền rủa? Cẩn thận phản thực."
    textfix["诅咒猴符，暗藏凶险。"] = "Phù khỉ nguyền rủa, ẩn hung hiểm."
    textfix["识时务者为俊杰。"] = "Kẻ biết thời thế là hào kiệt."
    textfix["试炼箭阵？待我破之。"] = "Trận tên thử luyện? Để ta phá."
    textfix["试炼靶心..."] = "Tâm bia thử luyện..."
    textfix["诱妖花，以幻饵惑心，吞食生灵。"] = "Hoa dụ yêu, dùng mồi ảo mê hoặc tâm, nuốt sống sinh linh."
    textfix["诱妖草...倒是布置陷阱的好材料。"] = "Dụ yêu thảo... lại là nguyên liệu tốt để bày bẫy."
    textfix["调味法器，可增药效。"] = "Pháp khí gia vị, có thể tăng hiệu dược."
    textfix["象鼻酿果，滋味独特。"] = "Linh quả nhồi vòi voi, hương vị độc đáo."
