    textfix["连白骨成精的资质都没有"] = "Ngay cả tư chất để bạch cốt thành tinh cũng không có."
    textfix["连这点小事都办不好？"] = "Ngay việc nhỏ như thế này cũng không làm được?"
    textfix["连这点旱魃之气都承受不住，废物。"] = "Ngay cả chút hạn bạt chi khí này cũng chịu không nổi, đồ phế vật."
    textfix["迟缓弹丸，可制敌速度。"] = "Đạn làm chậm, có thể kiềm chế tốc độ địch."
    textfix["迷魂阵法，扰人心神。"] = "Pháp trận mê hồn, quấy rối tâm thần."
    textfix["追风宝鞍，镌刻疾风阵纹，能大幅提升灵兽脚力。"] = "Truy Phong bảo an, khắc trận văn tật phong, có thể đại phúc nâng cao cước lực của linh thú."
    textfix["逆转乾坤，需蓄力良久。"] = "Đảo ngược càn khôn, cần tích lực lâu dài."
    textfix["透气背心，适合在炎热天气穿着。"] = "Áo ba lỗ thoáng khí, phù hợp mặc trong thời tiết nóng."
    textfix["逗猫灵鱼，扰人心神。"] = "Linh ngư đùa mèo, quấy rối tâm thần."
    textfix["通天之法，岂是此书可载？"] = "Thông thiên chi pháp, sao là cuốn sách này có thể chứa?"
    textfix["通往熔岩竞技场的传送门。"] = "Cổng truyền tống dẫn đến đấu trường nham thạch."
    textfix["通灵鬃刷，梳理灵兽毛发，可增亲昵，助其褪毛。"] = "Thông linh kỳ bàn chải, chải lông linh thú, có thể tăng thân mật, giúp nó lột lông."
    textfix["通灵鹦鹉，能言善辩。"] = "Anh vũ thông linh, tài ăn nói biện thuyết."
    textfix["通道不稳，容不得多人同时进入。"] = "Thông đạo không ổn, không chứa được nhiều người vào cùng lúc."
    textfix["速度训练设施被烧毁了。"] = "Cơ sở huấn luyện tốc độ bị thiêu huỷ."
    textfix["速速生长，莫要误我时辰。"] = "Nhanh sinh trưởng, chớ lãng phí thời gian của ta."
    textfix["道友先处理要务，此物可暂存于我处。"] = "Đạo hữu xử lý việc quan trọng trước, vật này tạm gửi ta."
    textfix["道友正忙，稍后再议。"] = "Đạo hữu đang bận, bàn sau vậy."
    textfix["道友的储物袋，似乎已无余地。"] = "Túi trữ vật của đạo hữu hình như đã không còn chỗ."
    textfix["道友，幸会。"] = "Đạo hữu, hân hạnh gặp mặt."
    textfix["道友，感觉如何？"] = "Đạo hữu, cảm thấy thế nào?"
    textfix["道法相悖，习之无益。"] = "Đạo pháp tương phản, học cũng vô ích."
    textfix["道法粗浅，无甚可悟。"] = "Đạo pháp nông cạn, chẳng có gì đáng ngộ."
    textfix["遭火焚毁，已无用处。"] = "Bị lửa thiêu, đã không có ích."
    textfix["遮风避雨之物，凡人所用。"] = "Vật che gió tránh mưa, phàm nhân dùng."
    textfix["避水之效，已然消失。"] = "Hiệu quả tránh nước đã biến mất."
    textfix["避水法衣，符文流转，风雨不侵。"] = "Pháp y tị thủy, phù văn lưu chuyển, mưa gió không xâm."
    textfix["避雷针已充满电荷，闪闪发光。"] = "Cột thu lôi đã nạp đầy điện tích, lấp lánh."
    textfix["避雷针，能吸引闪电保护周围的建筑。"] = "Cột thu lôi, có thể thu hút sét để bảo vệ công trình xung quanh."
    textfix["避雷针？防雷击必备。"] = "Cột thu lôi? Cần thiết để phòng sét đánh."
    textfix["那朵花是其魂器？有点意思。"] = "Bông hoa đó là hồn khí của nó? Có chút thú vị."
    textfix["那根法杖似乎是启动基座的关键。"] = "Chiếc gậy pháp đó dường như là chìa khóa để khởi động bệ."
    textfix["那蟾蜍要遁走！"] = "Con cóc đó muốn chạy trốn!"
    textfix["邪天翁羽？勉强可入王某法眼！"] = "Lông hải âu tà? Miễn cưỡng có thể lọt vào pháp nhãn của Vương Mỗ!"
    textfix["邪天翁雕像，展翅姿态带着不详。"] = "Tượng đá hải âu tà, tư thế xòe cánh mang theo bất tường."
    textfix["邪天翁？待王某斩了这妖禽！"] = "Hải âu tà? Để Vương Mỗ chém con yêu cầm này!"
    textfix["酸橘汁腌鱼，异域风味。"] = "Cá ướp nước cam chua, hương vị ngoại quốc."
    textfix["酿鱼头，烹饪精细。"] = "Đầu cá nhồi, nấu nướng tinh tế."
    textfix["重{weight}斤...尚可。"] = "Nặng {weight} cân... cũng được."
    textfix["重{weight}斤！\\n此物不凡，内蕴灵机。"] = "Nặng {weight} cân!\nVật này phi thường, ẩn chứa linh cơ."
    textfix["重{weight}斤，收获第{day}天。"] = "Nặng {weight} cân, thu hoạch ngày thứ {day}."
    textfix["重{weight}斤，收获第{day}天，长得不小。"] = "Nặng {weight} cân, thu hoạch ngày thứ {day}, lớn không nhỏ."
    textfix["重{weight}斤，渔者{owner}。"] = "Nặng {weight} cân, ngư giả {owner}."
    textfix["重{weight}斤，渔者{owner}，尚可。"] = "Nặng {weight} cân, ngư giả {owner}, tạm được."
    textfix["重量过轻，价值不大。"] = "Trọng lượng quá nhẹ, giá trị không lớn."
    textfix["重饵？连条龙都钓不起来！"] = "Mồi nặng? Ngay cả rồng cũng câu không lên!"
    textfix["野兽傀儡，野性未驯。"] = "Quái lỗi dã thú, dã tính chưa thuần."
    textfix["野浆果，可暂缓饥渴。"] = "Quả mọng hoang, có thể tạm giảm đói khát."
    textfix["野猪战士，双臂力量惊人。"] = "Chiến sĩ lợn rừng, sức mạnh hai tay kinh người."
    textfix["野生蜂巢，蜂蜜虽好，取之需防蜂群反击。"] = "Tổ ong hoang, mật ong tuy ngon, lấy cần đề phòng đàn ong phản công."
    textfix["金丝雀已中毒，这是危险的信号。"] = "Chim hoàng yến đã trúng độc, đây là tín hiệu nguy hiểm."
    textfix["金丝雀的黄色羽毛。"] = "Lông vàng của chim hoàng yến."
    textfix["金丝雀，羽色鲜亮，对毒气敏感。"] = "Chim hoàng yến, lông màu rực rỡ, nhạy cảm với khí độc."
    textfix["金乌西坠，正是吐纳调息之时。"] = "Kim ô lặn xuống phía tây, chính là lúc tổ nạp điều tức."
    textfix["金叉，可以用来移植草皮和灌木。"] = "Nĩa vàng, có thể dùng để di chuyển thảm cỏ và bụi cây."
    textfix["金块，是珍贵的制作材料。"] = "Thỏi vàng, là nguyên liệu chế tạo quý giá."
    textfix["金属丝衣架，可悬挂衣物。"] = "Giá áo dây kim loại, có thể treo quần áo."
    textfix["金弹奢侈，华而不实。"] = "Đạn vàng xa xỉ, hoa mà không thực."
    textfix["金斧头，比普通斧头更耐用。"] = "Rìu vàng, bền hơn rìu thường."
    textfix["金砖铺地，过于奢靡。"] = "Gạch vàng lót nền, quá xa hoa."
    textfix["金精哑铃，可锻体魄。"] = "Tạ kim tinh, có thể rèn thể phách."
    textfix["金纹灵瓜，蕴含丰沛土灵之气。"] = "Linh dưa văn vàng, ẩn chứa thổ linh chi khí dồi dào."
    textfix["金纹瓜种，需广阔之地生长。"] = "Hạt giống dưa văn vàng, cần đất rộng rãi để sinh trưởng."
    textfix["金铲，挖掘次数更多。"] = "Xẻng vàng, số lần đào nhiều hơn."
    textfix["金锄？奢侈农具。"] = "Cuốc vàng? Nông cụ xa xỉ."
    textfix["金镐，耐久度更高。"] = "Cuốc vàng, độ bền cao hơn."
    textfix["金阙宝匣，必非凡品。"] = "Bảo hộp kim khuyết, tất không phải phàm phẩm."
    textfix["金鳞妖鱼，或许有些用处。"] = "Yêu ngư vảy vàng, có lẽ có chút dùng được."
    textfix["钓具匣？可笑，我王林何需此物。"] = "Hộp dụng cụ câu? Buồn cười, Vương Lâm ta cần gì vật này."
    textfix["钓具？王某徒手便可捉鱼！"] = "Dụng cụ câu? Vương Mỗ tay không cũng có thể bắt cá!"
    textfix["钓竿，用来从水域中钓鱼。"] = "Cần câu, dùng để câu cá từ vùng nước."
    textfix["钓竿？王某徒手便可捉鱼！"] = "Cần câu? Vương Mỗ tay không cũng có thể bắt cá!"
    textfix["钟声震耳，扰人清静。"] = "Tiếng chuông điếc tai, quấy rối yên tĩnh."
    textfix["钢丝绵制成的抱枕，防御性较强。"] = "Gối ôm làm từ len thép, tính phòng thủ khá mạnh."
    textfix["钢丝绵填充的手枕，质地坚硬。"] = "Gối tay nhồi len thép, chất địa cứng."
    textfix["钢甲岩羊？此兽吞吐金石之气，甲壳坚不可摧。"] = "Thép giáp nham dương? Linh thú này hít vào kim thạch chi khí, giáp cứng không thể phá."
    textfix["钢羊幼崽，体表覆盖着特殊的黏液。"] = "Cừu thép non, bề mặt cơ thể bao phủ chất nhớt đặc biệt."
    textfix["钥匙不对，需另寻他法。"] = "Chìa khóa không đúng, cần tìm cách khác."
    textfix["钻角犀牛，它的角能钻开地面。"] = "Tê giác khoan sừng, sừng của nó có thể khoan mở mặt đất."
    textfix["铁匠戏服，匠魂附体。"] = "Trang phục thợ rèn, hồn thợ nhập thân."
    textfix["铁匠面具，匠气十足。"] = "Mặt nạ thợ rèn, thợ khí mười phần."
    textfix["铁甲傀儡，机关之术。"] = "Quái lỗi thiết giáp, thuật cơ quan."
    textfix["锁定目标，速速擒拿。"] = "Khóa định mục tiêu, mau mau bắt lấy."
    textfix["锁窍暗合九幽阵纹，非寻常钥匙可开。"] = "Ổ khóa ngầm hợp với trận văn Cửu U, không phải chìa khóa thường có thể mở."
    textfix["锄头？翻土工具。"] = "Cái cuốc? Công cụ lật đất."
    textfix["锋利的假獠牙，似是某种妖物的牙齿。"] = "Nanh giả sắc bén, dường như là răng của yêu vật nào đó."
    textfix["锋芒内敛，归于平常。"] = "Phong mang thu liễm, trở về bình thường."
    textfix["锤子，用于拆解建筑和装置。"] = "Búa, dùng để tháo dỡ công trình và thiết bị."
    textfix["锦鲤？倒是有些灵气。"] = "Cá chép gấm? Lại có chút linh khí."
    textfix["镜面戏服，虚实难辨。"] = "Trang phục gương, hư thực khó phân."
    textfix["镜面面具，反射虚妄。"] = "Mặt nạ gương, phản chiếu ảo vọng."
    textfix["长出巨型作物。"] = "Mọc ra cây trồng khổng lồ."
    textfix["长脚灵鹳，领地意识极强，其喙锋利可穿金石。"] = "Linh hạc chân dài, ý thức lãnh thổ cực mạnh, mỏ của nó sắc bén có thể xuyên kim thạch."
    textfix["问心棋局？考验道心。"] = "Cờ hỏi tâm? Kiểm nghiệm đạo tâm."
    textfix["阴木遇火，其焰幽蓝。"] = "Âm mộc gặp lửa, ngọn lửa màu xanh u ám."
    textfix["阴气不足，还需更多魂力..."] = "Âm khí không đủ, còn cần thêm hồn lực..."
    textfix["阴气凝聚，可作养魂之地。"] = "Âm khí ngưng tụ, có thể làm nơi dưỡng hồn."
    textfix["阴气凝聚，已具灵性。"] = "Âm khí ngưng tụ, đã có linh tính."
    textfix["阴气稍减，聊胜于无。"] = "Âm khí hơi giảm, cũng hơn là không có."
    textfix["阴火焚棘，噼啪作响。"] = "Âm hỏa thiêu gai, lách tách vang."
    textfix["阴阳两界都困不住你这通灵之体？"] = "Hai cõi âm dương đều không giam được thể thông linh của ngươi?"
    textfix["阴阳未调，生机未复。"] = "Âm dương chưa điều hòa, sinh cơ chưa phục."
    textfix["阴阳轮回，岂能困我？"] = "Âm dương luân hồi, sao có thể giam cầm ta?"
    textfix["阴险妖物，擅袭天灵。"] = "Yêu vật âm hiểm, giỏi tập kích thiên linh."
    textfix["阴魂不散，不如重入轮回。"] = "Âm hồn chẳng tan, chi bằng đầu thai trở lại."
    textfix["阵中无灵，术法难施。"] = "Trong trận không có linh lực, thuật pháp khó thi triển."
    textfix["阵基稳固，只待启动。"] = "Trận cơ ổn cố, chỉ chờ khởi động."
    textfix["阵毁坛崩！何人所致？"] = "Trận hủy đàn đổ! Ai gây ra vậy?"
    textfix["阵法初成，灵气渐聚。"] = "Pháp trận mới thành, linh khí dần tụ."
    textfix["阵法基石尚缺，需以灵石充能。"] = "Nền tảng trận pháp còn thiếu, cần dùng linh thạch nạp năng."
    textfix["阵法扳手，用以校准和启动空间坐标。"] = "Pháp trận bản thủ, dùng để hiệu chỉnh và khởi động tọa tiêu không gian."
    textfix["阵法未复，强启无益。"] = "Trận pháp chưa hồi phục, cưỡng mở cũng vô ích."
    textfix["阵眼已稳固，灵气流转通畅。"] = "Trận nhãn đã vững chắc, linh khí lưu chuyển thông suốt."
    textfix["阵眼已足，不可再添。"] = "Trận nhãn đã đủ, không thể thêm nữa."
    textfix["阵眼显形，破！"] = "Trận nhãn hiện hình, phá!"
    textfix["阵眼空虚，需嵌入灵石方可激发。"] = "Trận nhãn trống rỗng, cần nhúng linh thạch mới có thể kích hoạt."
    textfix["附身座狼雕像，形态狰狞，野性十足。"] = "Tượng đá chó sói phụ thể, hình thái hung tàn, man dã mười phần."
    textfix["附近有强大气血波动，是头不错的猎物。"] = "Gần đây có khí huyết mạnh mẽ dao động, là con mồi không tệ."
    textfix["险些着了道。"] = "Suýt nữa mắc bẫy."
    textfix["险境未除，不宜分心他顾。"] = "Hiểm cảnh chưa qua, không nên phân tâm việc khác."
    textfix["陶土座狼棋盘雕像。"] = "Tượng bàn cờ tọa lang đất sét."
    textfix["陶土烧制的座狼雕像，被仪式赋予了活性。"] = "Tượng tọa lang nung đất sét, được nghi lễ ban cho hoạt tính."
    textfix["陶土猎犬棋盘雕像。"] = "Tượng bàn cờ liệp khuyển đất sét."
    textfix["陶土猎犬，动作略显僵硬。"] = "Liệp khuyển đất sét, động tác hơi cứng nhắc."
    textfix["随波逐流，竟至此地。"] = "Theo dòng trôi giạt, thực sự đến nơi này."
    textfix["隔空取物，算是不错的小神通。"] = "Lấy vật cách không gian, cũng là thần thông nhỏ không tệ."
    textfix["难解的死结，其上似有微弱的诅咒气息。"] = "Nút chết khó gỡ, trên đó dường như có khí tức nguyền rủa vi nhược."
    textfix["集地底阴华而生，微光可照亮幽暗。"] = "Tụ âm hoa dưới đất mà sinh, ánh sáng nhỏ có thể soi sáng u ám."
    textfix["雕像似被某种力量牵引。"] = "Tượng đá dường như bị một loại lực lượng kéo dắt."
    textfix["雕像内部似有能量异动。"] = "Bên trong tượng đá dường như có năng lượng dị động."
    textfix["雕像的构造图，需在特定地点方能建造。"] = "Bản vẽ cấu trúc tượng đá, cần ở địa điểm đặc định mới có thể xây dựng."
    textfix["雕像蕴含的能量开始活跃。"] = "Năng lượng ẩn chứa trong tượng đá bắt đầu hoạt bát."
    textfix["雕虫小技，也配称为隐匿之法？"] = "Trò vặt vãnh, cũng đáng gọi là ẩn thân chi pháp?"
    textfix["雨伞，可以遮挡雨水。"] = "Ô, có thể che mưa."
    textfix["雨天影响风干效率。"] = "Ngày mưa ảnh hưởng hiệu suất phơi khô."
    textfix["雨天潮湿，风干缓慢。"] = "Ngày mưa ẩm ướt, phơi khô chậm."
    textfix["雨水冲刷，痕迹难寻。"] = "Mưa rửa trôi, dấu vết khó tìm."
    textfix["雨露虽含生机，此刻却碍我淬药。"] = "Mưa sương tuy chứa sinh cơ, lúc này lại cản trở ta tôi luyện thuốc."
    textfix["雨饵？弄湿法体实属不敬！"] = "Mồi mưa? Làm ướt pháp thể thực sự bất kính!"
    textfix["雪球发射器正在运行，自动扑灭周围的火。"] = "Máy phóng bóng tuyết đang chạy, tự động dập tắt lửa xung quanh."
    textfix["雪球发射器的燃料不足了。"] = "Nhiên liệu máy phóng bóng tuyết không đủ rồi."
    textfix["雪球发射器目前处于关闭状态。"] = "Máy phóng bóng tuyết hiện đang trong trạng thái tắt."
    textfix["雪精化雀，翎羽如冰晶，不惧严寒。"] = "Tuyết tinh hóa tước, lông vũ như băng tinh, không sợ giá lạnh."
    textfix["雪饵？鱼儿岂会中计！"] = "Mồi tuyết? Cá sao mà mắc kế!"
    textfix["雪鸟浮标？华而不实！"] = "Phao chim tuyết? Hoa mà không thực!"
    textfix["雷光掠身而过，幸未击中。"] = "Lôi quang lướt qua thân, may chưa trúng."
    textfix["雷击枯骨...正好炼制阴雷符"] = "Cốt khô bị sét đánh... đúng lúc luyện chế âm lôi phù."
    textfix["雷灵之力，渐渐消散。"] = "Sức mạnh lôi linh, dần dần tiêu tán."
    textfix["雷灵附体，诛邪辟易。"] = "Lôi linh phụ thể, trừ tà bích dị."
    textfix["雷电吹箭，迅疾刚猛，破邪有奇效。"] = "Tên thổi lôi điện, nhanh mạnh cứng rắn, trừ tà có công hiệu kỳ lạ."
    textfix["雷神之锤，攻击时能释放闪电。"] = "Búa lôi thần, khi tấn công có thể giải phóng sấm sét."
    textfix["雷羊肉冻，蕴含雷电之力。"] = "Thạch thịt dê sấm, hàm chứa lôi điện chi lực."
    textfix["需以至阴灵木为基。"] = "Cần dùng linh mộc chí âm làm nền tảng."
    textfix["需奉上祭品，方显诚意。"] = "Cần dâng tế phẩm, mới thể hiện thành ý."
    textfix["需奉香火，方显灵验。"] = "Cần dâng hương lửa, mới linh nghiệm."
    textfix["需寻得对应钥匙方可开启。"] = "Cần tìm đúng chìa khóa mới mở được."
    textfix["需有灵兽在侧，方可系挂。"] = "Cần có linh thú bên cạnh mới có thể đeo lên."
    textfix["需有相应器鼎，方可炼制。"] = "Cần có khí đỉnh tương ứng mới có thể luyện chế."
    textfix["震海神炮，需填弹药。"] = "Thần pháo chấn hải, cần nạp đạn dược."
    textfix["震海神雷，威力无穷。"] = "Thần lôi chấn hải, uy lực vô cùng."
    textfix["霓虹羽衣，光华流转。"] = "Vũ y cầu vồng, quang hoa lưu chuyển."
    textfix["青冥斗篷，隐迹藏形。"] = "Đấu bồng thanh minh, ẩn tích tàng hình."
    textfix["青玉秘匣，或藏机缘。"] = "Bí hộp ngọc thanh, hoặc ẩn cơ duyên."
    textfix["青砖铺路，稳固踏实。"] = "Gạch xanh lát đường, vững chắc thực tế."
    textfix["青蛙死了。"] = "Con ếch chết rồi."
    textfix["青蛙，会主动攻击并偷取物品。"] = "Ếch, sẽ chủ động tấn công và đánh cắp vật phẩm."
    textfix["青蛟藤蔓，缠绕如龙。"] = "Dây leo thanh giao, quấn quýt như rồng."
    textfix["静待夜幕，方显真容。"] = "Tĩnh chờ màn đêm, mới hiển chân dung."
    textfix["静心帐，于其中打坐可宁神静气，恢复神识。"] = "Tĩnh tâm trướng, trong đó ngồi thiền có thể yên thần tĩnh khí, phục hồi thần thức."
    textfix["非与会之人，不可标记。"] = "Không phải người tham dự, không thể đánh dấu."
    textfix["非吾道之器，不取。"] = "Không phải khí cụ của ta, không lấy."
    textfix["非常坚硬的糖果，需要含化很久。"] = "Kẹo rất cứng, cần ngậm tan rất lâu."
    textfix["非我驯化之灵宠，不可妄动。"] = "Không phải linh thú ta thuần hóa, không thể tùy tiện động vào."
    textfix["非月华法杖不可驱动！"] = "Không có nguyệt hoa pháp trượng không thể kích hoạt!"
    textfix["鞭子，抽打时能发出响亮的声音，可用于驯兽。"] = "Roi da, khi quất phát ra tiếng vang lớn, có thể dùng để thuần thú."
    textfix["韦伯的蜘蛛仆从，会协助他战斗。"] = "Nô bộc nhện của Webber, sẽ hỗ trợ hắn chiến đấu."
    textfix["音律载体，可存妙音。"] = "Vật chứa âm luật, có thể lưu giữ âm thanh diệu."
    textfix["须发皆乃血气之余，此物却隐含灵能。"] = "Râu tóc đều là dư khí huyết, nhưng vật này ẩn chứa linh năng."
    textfix["顽石之地，灵气难存。"] = "Đất đá ngoan cố, linh khí khó tồn tại."
    textfix["顽石也敢抵抗王某法力？"] = "Đá cứng đầu cũng dám kháng cự pháp lực của Vương Mỗ?"
    textfix["颅蕴幻境，惑人心神。"] = "Đầu lâu ẩn chứa huyễn cảnh, mê hoặc tâm thần."
    textfix["额前嵌光石，夜探矿脉如白昼。"] = "Đá sáng nhúng trán, ban đêm thăm dò quặng như ban ngày."
    textfix["风向有变，落帆不易。"] = "Hướng gió đã đổi, hạ buồm không dễ."
    textfix["风干淬炼，去芜存菁。"] = "Phơi gió tôi luyện, loại bỏ tạp lưu giữ tinh túy."
    textfix["风干灵植，药性更纯。"] = "Linh thực phơi gió, dược tính càng thuần."
    textfix["风干的人形生物的肉。"] = "Thịt sinh vật hình người phơi khô."
    textfix["风干的触手标本，残留着微弱的妖气。"] = "Tiêu bản xúc tu phơi khô, còn lưu yêu khí vi nhược."
    textfix["风干肉条，便于携带，可喂食灵宠。"] = "Thịt khô gió, tiện mang theo, có thể cho linh thú ăn."
    textfix["风滚草，滚动时可能裹挟着一些物品。"] = "Cỏ lăn gió, khi lăn có thể cuộn theo một số vật phẩm."
    textfix["飞去来器，轨迹刁钻，可作奇兵。"] = "Dụng cụ bay về, quỹ đạo tinh ranh, có thể làm kỳ binh."
    textfix["飞禽之魂...勉强可炼入飞行法器"] = "Hồn phi cầm... gượng có thể luyện vào phi hành pháp khí."
    textfix["食此可获一丝龙元否？"] = "Ăn vật này có thể thu được một sợi long nguyên không?"
    textfix["食物即将烹煮完成。"] = "Thức ăn sắp nấu xong."
    textfix["食物快要烹制完成了。"] = "Thức ăn sắp chế biến xong rồi."
    textfix["食物灵气尽失，已生秽气，不可再食。"] = "Linh khí thực vật đã tận mất, đã sinh uế khí, không thể ăn nữa."
    textfix["餐桌上摆放着节庆食物。"] = "Trên bàn tiệc bày biện thức ăn ngày lễ."
    textfix["餐桌被烧毁了。"] = "Bàn tiệc bị thiêu huỷ."
    textfix["饥肠辘辘，难以入静。"] = "Bụng đói rỗng, khó nhập tĩnh."
    textfix["饮用后周身会泛起火焰特效的药水。"] = "Thuốc sau khi uống toàn thân sẽ hiện ra hiệu ứng ngọn lửa."
    textfix["饶舌妖鸟，扰乱心神。"] = "Yêu điểu miệng mỏ, nhiễu loạn tâm thần."
    textfix["饼干切割机的外壳。"] = "Vỏ ngoài của máy cắt bánh quy."
    textfix["饼干切割机，一种会攻击船只的小型海洋生物。"] = "Máy cắt bánh quy, một loại sinh vật biển nhỏ sẽ tấn công thuyền."
    textfix["香火微明，可安神魂。"] = "Hương lửa mờ nhạt, có thể an thần hồn."
    textfix["香火未燃，灵气不显。"] = "Hương lửa chưa đốt, linh khí không hiện."
    textfix["香炉已冷，待我再续灵香。"] = "Lò hương đã nguội, để ta thêm linh hương."
    textfix["香蕉冰棍，消暑小食。"] = "Que kem chuối, đồ ăn vặt giải nhiệt."
    textfix["香蕉灵丛，果实累累。"] = "Linh tùng chuối, quả trĩu nặng."
    textfix["香蕉灵液，可补元气。"] = "Linh dịch chuối, có thể bổ nguyên khí."
    textfix["驯兽哨，吹响时可吸引附近的猎犬。"] = "Tiêu thuần thú, khi thổi có thể thu hút liệp khuyển gần đó."
    textfix["驯服魔眼，或可一用。"] = "Ma nhãn đã thuần, hoặc có thể dùng."
    textfix["驱虫香，凡人用品。"] = "Hương đuổi trùng, đồ dùng phàm nhân."
    textfix["骑乘之时，不便开启。"] = "Khi đang cưỡi, không tiện mở ra."
    textfix["骑士雕像，雕琢精细。"] = "Tượng đá kỵ sĩ, được chạm khắc tinh tế."
    textfix["骑枪，适合在坐骑上使用，进行冲锋攻击。"] = "Kỵ thương, phù hợp sử dụng trên tọa kỵ, tiến hành xung phong tấn công."
    textfix["骨头碎片，可用于炼制或制作某些物品。"] = "Mảnh xương, có thể dùng để luyện chế hoặc chế tạo một số vật phẩm."
    textfix["骨架已经完整拼合，似乎蕴含着某种力量。"] = "Bộ xương đã ghép hoàn chỉnh, dường như ẩn chứa một loại sức mạnh."
    textfix["骨汤，可补钙质。"] = "Canh xương, có thể bổ canxi."
    textfix["骨牢之术？雕虫小技。"] = "Thuật lồng xương? Chỉ là vặt vãnh."
    textfix["骨肉炖汤，营养丰富，可恢复体力。"] = "Canh hầm xương thịt, giàu dinh dưỡng, có thể phục hồi thể lực."
    textfix["高兔明灯，光华流转。"] = "Đèn sáng thỏ cao, quang hoa lưu chuyển."
    textfix["高兔灯部件，当择地而置。"] = "Bộ phận đèn thỏ cao, nên chọn đất mà đặt."
    textfix["高级浇水壶？效率更高。"] = "Bình tưới nước cao cấp? Hiệu suất cao hơn."
    textfix["高音刺耳，扰人清修。"] = "Âm cao chói tai, quấy rối tu luyện thanh tịnh."
    textfix["高顶礼帽，凡俗界象征身份的饰物。"] = "Lễ mạo đỉnh cao, đồ trang sức tượng trưng thân phận ở thế giới phàm tục."
    textfix["高鸟灵蛋，别有风味。"] = "Trứng linh cầm cao, hương vị riêng biệt."
    textfix["鬼蜮伎俩，也敢献丑。"] = "Mánh khóe ma quỷ, cũng dám trình diễn?"
    textfix["魂体受阴风侵蚀，灵光黯淡。"] = "Hồn thể bị âm phong xâm thực, linh quang tối tăm."
    textfix["魂体状态的你...更显诡异..."] = "Ngươi trong trạng thái hồn thể... càng trở nên kỳ quái..."
    textfix["魂器与她的联系更深了。"] = "Mối liên hệ giữa hồn khí và cô ta sâu hơn rồi."
    textfix["魔兽血肉，蕴含狂暴戾气，凡人食之立毙。"] = "Huyết nhục ma thú, ẩn chứa cuồng bạo lệ khí, phàm nhân ăn vào lập tức chết."
    textfix["魔域妖花花瓣，煞气缠绕，是炼制毒蛊的材料。"] = "Cánh hoa yêu từ cõi ma, sát khí quấn quanh, là nguyên liệu để luyện chế độc cổ."
    textfix["魔头，纳命来！"] = "Ma đầu, nộp mạng đây!"
    textfix["魔念侵蚀的傀儡，终将归于尘土。"] = "Bù nhìn bị ma niệm xâm thực, cuối cùng cũng về với bụi đất."
    textfix["魔念渐起，需得提防。"] = "Ma niệm dần nổi, cần đề phòng."
    textfix["魔息内敛，风暴前夕往往如此。"] = "Ma tức thu liễm, thường là vậy trước khi bão tố nổi."
    textfix["魔术宝箱，暗藏玄机。"] = "Rương ảo thuật, ẩn huyền cơ."
    textfix["魔术高帽，似有法力。"] = "Mũ cao ảo thuật, dường như có pháp lực."
    textfix["魔气固化，似成领域..."] = "Ma khí cố hóa, dường như thành lĩnh vực..."
    textfix["魔气森然的王座，凡人岂可染指？"] = "Ngai vàng đầy ma khí, phàm nhân sao có thể đụng chạm?"
    textfix["魔潮将退，但不可松懈。"] = "Ma triều sắp lui, nhưng không thể lơi lỏng."
    textfix["魔焰之眼，凶威赫赫。"] = "Nhãn của ma diễm, hung uy hiển hách."
    textfix["魔眼之卵，即将孵化。"] = "Trứng ma nhãn, sắp ấp nở."
    textfix["魔眼盾牌，可御邪祟。"] = "Khiên ma nhãn, có thể chống tà chú."
    textfix["魔障滔天，此地不宜久留！"] = "Ma chướng tràn trời, nơi này không nên ở lâu!"
    textfix["魔魂不灭...正好炼入噬魂幡！"] = "Ma hồn bất diệt... vừa hay luyện vào Thực Hồn Phan!"
    textfix["鱼人争位，无聊闹剧。"] = "Người cá tranh vị, trò hề vô liêu."
    textfix["鱼人伪装，可避水族。"] = "Trang phục giả trang người cá, có thể tránh thủy tộc."
    textfix["鱼人哨塔，与我何干。"] = "Tháp canh người cá, liên quan gì đến ta."
    textfix["鱼人守卫，不堪一击。"] = "Vệ sĩ người cá, không chịu được một đòn."
    textfix["鱼人屋舍，简陋不堪。"] = "Nhà ở người cá, sơ sài không chịu được."
    textfix["鱼人建朝？痴心妄想。"] = "Người cá lập triều? Hoang tưởng."
    textfix["鱼人王座？可笑。"] = "Ngai vàng người cá? Đáng cười."
    textfix["鱼人王？傀儡罢了。"] = "Vua người cá? Chẳng qua là quái lỗi."
    textfix["鱼妖之魂...正好喂养王某的噬魂蛊！"] = "Hồn ngư yêu... vừa hay nuôi cổ thực hồn của Vương Mỗ!"
    textfix["鱼妖巢穴，以污秽水藻与朽木搭建，腥臭不堪。"] = "Tổ ngư yêu, được xây bằng rêu nước ô uế và gỗ mục, tanh hôi không chịu được."
    textfix["鱼妖首级，腥煞之气冲天，可布邪阵或炼毒。"] = "Đầu ngư yêu, tanh sát chi khí xung thiên, có thể bố trận tà hoặc luyện độc."
    textfix["鱼渣一堆。"] = "Một đống xác cá."
    textfix["鱼缸能量耗尽，哈奇暂时无法显现。"] = "Năng lượng bể cá cạn kiệt, Hutch tạm thời không thể hiện ra."
    textfix["鱼群似有灵智，懂得避人。"] = "Đàn cá dường như có linh trí, biết tránh người."
    textfix["鱼肉塔可，是种不错的食物。"] = "Tacos cá, là loại thức ăn không tệ."
    textfix["鱼苗？连塞牙缝都不够。"] = "Cá giống? Ngay cả nhét kẽ răng cũng không đủ."
    textfix["鱼蛙杂烩，味道独特。"] = "Tạp hội cá ếch, hương vị độc đáo."
    textfix["鱼钩？王某徒手便可捉鱼！"] = "Lưỡi câu? Vương Mỗ tay không cũng có thể bắt cá!"
    textfix["鱼饵而已，不值一提。"] = "Chẳng qua là mồi cá, không đáng nhắc đến."
    textfix["鱼首成炭，煞气已泄，沦为无用秽物。"] = "Đầu cá thành than, sát khí đã rò rỉ, suy thành vật ô uế vô dụng."
    textfix["鱼，可以烹饪食用。"] = "Cá, có thể nấu ăn."
    textfix["鱿鱼？可作海鲜食材。"] = "Mực ống? Có thể làm nguyên liệu hải sản."
    textfix["鲨鱼？海中猛兽。"] = "Cá mập? Mãnh thú trong biển."
    textfix["鳄鱼形玩具，栩栩如生。"] = "Đồ chơi hình cá sấu, sống động như thật."
    textfix["鳄鱼指挥官，能号令其他鳄鱼。"] = "Chỉ huy cá sấu, có thể hiệu lệnh cá sấu khác."
    textfix["鸟笼，可囚禁鸟类，便于获取其蛋。"] = "Lồng chim, có thể giam cầm chim, tiện lấy trứng."
    textfix["鸟蛋，可食，亦可孵化。"] = "Trứng chim, có thể ăn, cũng có thể ấp nở."
    textfix["鹅精？也敢在王某面前放肆"] = "Ngỗng tinh? Cũng dám phóng túng trước mặt Vương Mỗ."
